INSERT INTO "characterizations" VALUES(3400,3954,'organic solvent tolerance test','composites and free enzymes incubated 1 h in water, DMF, DMSO at 80 °C and in boiling methanol and ethanol; CALB/ZIF-8 activity remained almost unchanged','the enzyme/ZIF-8 composites were incubated in water, DMF, DMSO at 80 °C and in boiling methanol, boiling ethanol for 1 h','Results and discussion',16392,16512,NULL,'composites and corresponding free enzyme powders; 1 h; substrate 4-nitrophenyl butyrate');
