INSERT INTO "characterizations" VALUES(3721,4167,'HRTEM','nanoparticles: d = 0.354 nm, (101) of anatase (Fig. 6h = échantillon 4 M d''après la légende de la figure 6)','The nanoparticles showed lattice spacing of d = 0.354 nm for the (101) plane of the anatase phase.','Results and Discussion',13413,13511,NULL,NULL);
INSERT INTO "characterizations" VALUES(3722,4167,'HRTEM','aligned nanorods: d = 0.325 nm, (110) plane of rutile (Fig. 6h = échantillon 4 M d''après la légende de la figure 6)','The distance between the lattice fringes (d = 0.325 nm) in the aligned nanorods can be assigned to the interplanar distance of rutile phase (110) plane','Results and Discussion',13512,13663,NULL,NULL);
INSERT INTO "characterizations" VALUES(3723,4168,'XRD','mixture of anatase and rutile (donné pour la plage « 2 to 7 M »)','With the increasing concentration of HCl ranged from 2 to 7 M, a mixture of anatase and rutile was obtained as showed in Fig. 3d–3i.','Results and Discussion',10214,10346,'Philips X’ Pert Pro MPD X-ray diffraction system','Cu-Kα radiation, λ = 0.154056 nm; continuous scan mode, 2θ range of 10–90°, scan rate of 0.02 deg/s');
INSERT INTO "characterizations" VALUES(3724,4168,'SAED','polycrystalline anatase nanoparticles and single-crystalline rutile nanorods (inset de Fig. 6d = échantillon 5 M d''après la légende de la figure 6)','Further observation by SAED (inset image in Fig. 6d) confirmed that the nanoparticles had a polycrystalline anatase structure, and the aligned nanorods were single crystalline TiO2 with rutile structure.','Results and Discussion',13708,13911,NULL,NULL);
INSERT INTO "characterizations" VALUES(3725,4169,'XRD','mixture of anatase and rutile (donné pour la plage « 2 to 7 M »)','With the increasing concentration of HCl ranged from 2 to 7 M, a mixture of anatase and rutile was obtained as showed in Fig. 3d–3i.','Results and Discussion',10214,10346,'Philips X’ Pert Pro MPD X-ray diffraction system','Cu-Kα radiation, λ = 0.154056 nm; continuous scan mode, 2θ range of 10–90°, scan rate of 0.02 deg/s');
