INSERT INTO "characterizations" VALUES(4271,4727,'Raman','spectre Raman mesuré pour tous les échantillons (figure 2)','Figure 2 shows the Raman spectra for all the samples synthesized using different concentrations of NaOH.','4. Discussion',12542,12646,'WITec Alpha 300R (WITec, Knoxville, TN, United State)','excitation laser source of 488 nm');
