INSERT INTO "outcomes" VALUES(17947,4028,'MSN_diameter',80.0,NULL,'nm','For example under the same condition with 0.3 vt% TEA as base catalyst and 0.75 vt% TEOS as silica source, MSNs at 60 or 80 nm was obtained with 10 wt% CTAB or CTAC as templates, respectively.','Size-controlled synthesis and characterization of Ru@MSNs nanosystems',18072,18264,NULL);
