INSERT INTO "outcomes" VALUES(17954,4029,'IC50_HepG2',0.017,NULL,'μM','the IC50 of Ru@MSNs at 20, 40, and 80 nm against HepG2 cells was about 0.017, 0.018, and 0.091 μM, respectively','Size effects on anticancer activity in vitro',23868,23979,NULL);
INSERT INTO "outcomes" VALUES(17955,4029,'IC50_R-HepG2',0.253,NULL,'μM','the IC50 value of Ru@MSNs at 80 nm was lowest, which was about 0.044 μM. And the IC50 value of other two particles sized Ru@MSNs at 20 and 40 nm were about 0.253 and 0.515 μM, respectively','Anti-drug resistance of Ru@MSNs through suppressing drug efflux',39759,39947,NULL);
INSERT INTO "outcomes" VALUES(17956,4029,'cumulative_release_PBS_pH7.4_48h',13.8,NULL,'%','cumulative released of RuPOP in PBS at pH 7.4 after 48 h from Ru@MSNs at 20, 40, and 80 nm diameter were about 13.8, 12.5, and 33.9%, respectively','In vitro drug release from the nanoparticles',29571,29717,NULL);
