INSERT INTO "outcomes" VALUES(17958,4029,'retention_HepG2_20h',94.2,NULL,'%','the smaller sized Ru@MSNs at 20 (94.2%) and 40 nm (91.7%) showed higher retention efficacy in HepG2 cells than that of the lager sized Ru@MSNs at 80 nm (80.7%)','Size effects of nanoparticles on intracellular uptake',27522,27681,NULL);
INSERT INTO "outcomes" VALUES(17959,4029,'retention_R-HepG2_20h',86.7,NULL,'%','remain for a higher retention efficacy in R-HepG2 cells, which was about 86.7, 71.6, and 92.7%, respectively','Anti-drug resistance of Ru@MSNs through suppressing drug efflux',40576,40684,NULL);
