INSERT INTO "outcomes" VALUES(18451,4109,'HT_XRD_spinel_peaks',NULL,'three peaks at 18.8◦, 37.2◦ and 44.99◦ 2θ at 500 ◦C, attributed to the (111), (311) and (400) peaks of the spinel LT-LCO phase',NULL,'With the temperature rising to 500 ◦C during the HT-XRD measurements, three distinct peaks emerged at 18.8◦, 37.2◦, and 44.99◦2θ.','Supporting Information — am4c06503_si_001.pdf',52905,53034,NULL);
