INSERT INTO "outcomes" VALUES(18553,4119,'film_thickness_average',17.8,NULL,'nm','slow cooling results in a thicker h-BN film (an average thickness of 17.8 nm with a s.d. of 6.1 nm over the whole area','Synthesis and materials characterization of multilayer h-BN',7578,7696,NULL);
INSERT INTO "outcomes" VALUES(18554,4119,'grain_size_at_least',160000.0,NULL,'μm2','The grain size of h-BN for fast- and slow-cooling samples was obtained to be at least 40,000 and 160,000 μm2, respectively','Synthesis and materials characterization of multilayer h-BN',7864,7986,NULL);
INSERT INTO "outcomes" VALUES(18555,4119,'CL_D_S_intensity_ratio',0.275,NULL,NULL,'The integrated intensity ratio of D/S is small (0.275), which is comparable to that of single-crystalline h-BN.','Synthesis and materials characterization of multilayer h-BN',9135,9246,NULL);
INSERT INTO "outcomes" VALUES(18556,4119,'surface_roughness',NULL,'∼0.2 nm',NULL,'roughness values of ∼0.2 nm are obtained for both samples, confirming the high quality of the CVD-grown samples','Synthesis and materials characterization of multilayer h-BN',10973,11084,NULL);
INSERT INTO "outcomes" VALUES(18557,4119,'Young_modulus',1.16,NULL,'TPa','corresponding to a Young''s modulus of 1.16±0.1 TPa (ref. )','Mechanical strength of multilayer h-BN film',14605,14663,NULL);
INSERT INTO "outcomes" VALUES(18558,4119,'elastic_modulus_2D',18000.0,NULL,'Nm−1','which results in a measured average elastic modulus of 18,000 Nm−1 corresponding to a Young''s modulus of 1.16±0.1 TPa','Mechanical strength of multilayer h-BN film',14538,14655,NULL);
INSERT INTO "outcomes" VALUES(18559,4119,'d_spacing_10-10',2.17,NULL,'Å','The d-spacings of (10–10) and (11–20) planes are obtained to be 2.17 and 1.26 Å, respectively, which are in good agreement with theoretical values.','Characterization of structural quality of multilayer h-BN',12138,12285,NULL);
INSERT INTO "outcomes" VALUES(18560,4119,'d_spacing_11-20',1.26,NULL,'Å','The d-spacings of (10–10) and (11–20) planes are obtained to be 2.17 and 1.26 Å, respectively, which are in good agreement with theoretical values.','Characterization of structural quality of multilayer h-BN',12138,12285,NULL);
INSERT INTO "outcomes" VALUES(18561,4119,'d_spacing_0002',0.33,NULL,'nm','The (0002) lattice plane with a d-spacing of 0.33 nm in e is identified from the FFT image.','Figure captions',35943,36034,NULL);
INSERT INTO "outcomes" VALUES(18562,4119,'B_N_stoichiometry',NULL,'1:1',NULL,'It was also confirmed that the stoichiometry of boron and nitrogen is 1:1 through the EELS measurement, as well as through X-ray photoemission spectroscopy (Supplementary Figs 9 and 10).','Characterization of structural quality of multilayer h-BN',13340,13526,NULL);
INSERT INTO "outcomes" VALUES(18563,4119,'contact_angle_increase_vs_bare_Fe',NULL,'>30°',NULL,'The contact angle is increased by >30°, suggesting that these h-BN films can be used as hydrophobic surface coatings.','Synthesis and materials characterization of multilayer h-BN',10576,10693,NULL);
INSERT INTO "outcomes" VALUES(18564,4119,'average_terrace_size',NULL,'10 × 10 μm2 or larger',NULL,'The average terrace size of h-BN film was roughly obtained to be 10 × 10 μm2 or larger from AFM morphology analysis (Supplementary Fig. 6).','Synthesis and materials characterization of multilayer h-BN',11216,11355,NULL);
INSERT INTO "outcomes" VALUES(18565,4119,'Fe_substrate_reuse_cycles_with_identical_growth',10.0,NULL,NULL,'Even after 10 synthesis and transfers of h-BN on the reused Fe substrate, the morphology and quality of the growth results were confirmed to be almost identical (Supplementary Fig. 1).','Synthesis and materials characterization of multilayer h-BN',6364,6548,NULL);
INSERT INTO "outcomes" VALUES(18566,4120,'film_thickness_average',11.9,NULL,'nm','In the case of fast cooling (Supplementary Fig. 2b,c), a relatively thin h-BN film (an average thickness of 11.9 nm with a s.d. of 3.3 nm) with triangular islands covered the Fe surface (Supplementary Figs 3 and 4).','Synthesis and materials characterization of multilayer h-BN',7232,7447,NULL);
INSERT INTO "outcomes" VALUES(18567,4120,'grain_size_at_least',40000.0,NULL,'μm2','The grain size of h-BN for fast- and slow-cooling samples was obtained to be at least 40,000 and 160,000 μm2, respectively','Synthesis and materials characterization of multilayer h-BN',7864,7986,NULL);
INSERT INTO "outcomes" VALUES(18568,4121,'domain_size',NULL,'between 100 μm to a few hundred micrometres',NULL,'A typical size of a single-crystalline graphene domain is between 100 μm to a few hundred micrometres (Supplementary Fig. 15).','Device applications of multilayer h-BN',18445,18571,NULL);
INSERT INTO "outcomes" VALUES(18569,4122,'PL_exciton_emission_enhancement_on_hBN_vs_SiO2',NULL,'∼13 times greater',NULL,'The exciton emission of MoS2 on a h-BN substrate (ΔI1) is ∼13 times greater than that of MoS2 on a SiO2 substrate (ΔI2), respectively.','Optical and electrical properties of MoS2 and WSe2 on h-BN',23512,23646,NULL);
INSERT INTO "outcomes" VALUES(18570,4122,'PL_Lorentz_centre_A0_neutral_exciton',1.895,NULL,'eV','the PL spectra were fitted with three Lorentz curves at centres of 1.895 (neutral exciton: A°), 1.852 (multiexciton: X−) and 1.988 eV (B neutral exciton; Fig. 6d)','Optical and electrical properties of MoS2 and WSe2 on h-BN',23721,23883,NULL);
INSERT INTO "outcomes" VALUES(18571,4122,'PL_Lorentz_centre_X_minus_multiexciton',1.852,NULL,'eV','the PL spectra were fitted with three Lorentz curves at centres of 1.895 (neutral exciton: A°), 1.852 (multiexciton: X−) and 1.988 eV (B neutral exciton; Fig. 6d)','Optical and electrical properties of MoS2 and WSe2 on h-BN',23721,23883,NULL);
INSERT INTO "outcomes" VALUES(18572,4122,'PL_Lorentz_centre_B_neutral_exciton',1.988,NULL,'eV','the PL spectra were fitted with three Lorentz curves at centres of 1.895 (neutral exciton: A°), 1.852 (multiexciton: X−) and 1.988 eV (B neutral exciton; Fig. 6d)','Optical and electrical properties of MoS2 and WSe2 on h-BN',23721,23883,NULL);
INSERT INTO "outcomes" VALUES(18573,4122,'monolayer_thickness_AFM',NULL,'around 1 nm',NULL,'The thickness of monolayer MoS2 is around 1 nm, indicating that MoS2 is indeed monolayer.','Supporting Information — ncomms9662-s1.pdf',47642,47731,NULL);
INSERT INTO "outcomes" VALUES(18574,4123,'PL_exciton_emission_enhancement_on_hBN_vs_SiO2',NULL,'~ 6 times greater',NULL,'The exciton emission of WSe2 on an h-BN substrate (ΔI1) is ~ 6 times greater than that of WSe2 on a SiO2 substrate (ΔI2).','Supporting Information — ncomms9662-s1.pdf',49076,49197,NULL);
INSERT INTO "outcomes" VALUES(18575,4123,'monolayer_thickness_AFM',NULL,'around 1 nm',NULL,'The thickness of monolayer WSe2 film is around 1 nm, indicating that WSe2 is indeed monolayer.','Supporting Information — ncomms9662-s1.pdf',48106,48200,NULL);
INSERT INTO "outcomes" VALUES(18576,4127,'breakdown_electric_field',NULL,'∼2–4 MV cm−1 for a film thickness of 8–15 nm',NULL,'The breakdown electric field for a typical film thickness of 8–15 nm was ∼2–4 MV cm−1, which is within observed values for crystalline h-BN.','Dielectric properties of multilayer h-BN film',16028,16168,NULL);
INSERT INTO "outcomes" VALUES(18577,4127,'breakdown_current_density_criterion',NULL,'∼10−5 A cm−2',NULL,'A breakdown current density of ∼10−5 A cm−2 is defined, which is just above the noise floor of the measurement system.','Dielectric properties of multilayer h-BN film',15717,15835,NULL);
INSERT INTO "outcomes" VALUES(18578,4127,'breakdown_electric_field_without_wrinkle',4.12,NULL,'MVcm-1','The breakdown electric field without a wrinkle (a) was 4.12 MVcm-1, while that value was reduced to 1~3 MVcm-1 in the presence of wrinkles (b-d).','Supporting Information — ncomms9662-s1.pdf',45102,45247,NULL);
INSERT INTO "outcomes" VALUES(18579,4127,'breakdown_electric_field_with_wrinkles',NULL,'1~3 MVcm-1',NULL,'The breakdown electric field without a wrinkle (a) was 4.12 MVcm-1, while that value was reduced to 1~3 MVcm-1 in the presence of wrinkles (b-d).','Supporting Information — ncomms9662-s1.pdf',45102,45247,NULL);
INSERT INTO "outcomes" VALUES(18580,4128,'relative_dielectric_constant',NULL,'3 to 5 (average)',NULL,'The average relative dielectric constant ranged from 3 to 5, which is consistent with expected values.','Dielectric properties of multilayer h-BN film',17336,17438,NULL);
INSERT INTO "outcomes" VALUES(18581,4128,'parasitic_capacitance_Cpar',NULL,'∼15 fF in relatively thick devices',NULL,'A typical Cpar of ∼15 fF in the relatively thick devices was extracted.','Dielectric properties of multilayer h-BN film',17194,17265,NULL);
INSERT INTO "outcomes" VALUES(18582,4128,'wrinkle_height_relative_to_hBN_thickness',NULL,'three to six times thicker than the h-BN film',NULL,'The height of wrinkle in a real device is typically ranged from three to six times thicker than that of h-BN film (Supplementary Fig. 13).','Dielectric properties of multilayer h-BN film',17571,17709,NULL);
INSERT INTO "outcomes" VALUES(18583,4128,'device_hBN_thickness_Supp_Fig_13',9.2,NULL,'nm','The thickness of h-BN film is 9.2 nm, which was measured by making trenches','Supporting Information — ncomms9662-s1.pdf',45547,45622,NULL);
