INSERT INTO "outcomes" VALUES(18967,4183,'isotherm',NULL,'no hysteresis but high uptake at high P/P 0 (close to P/P 0 = 1)',NULL,'The isotherm acquired for the MOF obtained without a surfactant (Fig. S8†) showed no hysteresis but high uptake at high P/P 0 (close to P/P 0 = 1), pointing to the formation of much bigger MOF crystals and condensation in macropores formed around these bigger particles','Influence of pH',17262,17531,NULL);
