INSERT INTO "outcomes" VALUES(18970,4184,'mesoporosity_trend',NULL,'a decrease in the amount of CTAB led to a higher mesoporosity together with a narrower BJH pore size distribution',NULL,'It seems that a decrease in the amount of CTAB in the synthesis solution led to a higher mesoporosity together with a narrower BJH pore size distribution.','Supporting Information — CE-017-C4CE02324B-s001.pdf',31709,31863,NULL);
