INSERT INTO "outcomes" VALUES(19134,4205,'osteogenic_gene_expression',NULL,'upregulated when compared to the control samples',NULL,'several genes (type I collagen (COL1a1), runt-related transcription factor-2 (RUNX-2), alkaline phosphatase (ALPP), osterix (SP7), osteonectin (SPARC), and osteocalcin (BGLAP)) were upregulated when compared to the control samples','2.4. Gene Expression and Quantitative Analysis of Osteogenic Proteins',10719,10949,NULL);
INSERT INTO "outcomes" VALUES(19135,4205,'osteogenic_protein_expression_timing',NULL,'Alkaline phosphatase over-expressed at the early stage, then osteocalcin and osteonectin at the medium to later stages, finally collagen type I in the later stage',NULL,'Alkaline phosphatase was over-expressed at the early stage, followed by over-expression of osteocalcin and osteonectin at the medium to later stages, and, finally, collagen type I expression in the later stage','2.4. Gene Expression and Quantitative Analysis of Osteogenic Proteins',11160,11369,NULL);
INSERT INTO "outcomes" VALUES(19136,4205,'in_vivo_control_defect_regeneration',NULL,'limited regeneration (defect site with no implant)',NULL,'The control group (defect site with no implant) showed limited regeneration.','2.5. Micro-Computed Tomography (μ-CT) Analysis',12108,12184,NULL);
INSERT INTO "outcomes" VALUES(19137,4205,'in_vivo_Sinbone_mineralization',NULL,'lack of complete mineralization even after 12 weeks',NULL,'the Sinbone granules showed a lack of complete mineralization even after 12 weeks','2.5. Micro-Computed Tomography (μ-CT) Analysis',12465,12546,NULL);
INSERT INTO "outcomes" VALUES(19138,4205,'histology_new_bone',NULL,'active new bone formation, with Harversian canals within the newly formed bone',NULL,'active new bone formation was observed in the defect site treated with biomimetic hydroxyapatite microspheres (GHM-S) implants, with the presence of Harversian canals within the newly formed bone','2.6. Histological and Immunohistochemical Analysis',13247,13442,NULL);
INSERT INTO "outcomes" VALUES(19139,4205,'histology_fibrous_tissue_inflammation',NULL,'no detectable fibrous tissue invasion or inflammatory cell infiltrates',NULL,'there was no detectable fibrous tissue invasion or inflammatory cell infiltrates in the biomimetic hydroxyapatite microspheres (GHM-S) experimental group','2.6. Histological and Immunohistochemical Analysis',13457,13610,NULL);
