INSERT INTO "outcomes" VALUES(19350,4244,'SBF_reagents',NULL,'sodium chloride salts, sodium hydrogen carbonate, potassium chloride, dipotassium hydrogen phosphate triplets, and magnesium chloride 6 hydrate (quantities calculated and prepared as in Table 2)',NULL,'The quantity of sodium chloride salts, sodium hydrogen carbonate, potassium chloride, dipotassium hydrogen phosphate triplets, and magnesium chloride 6 hydrate were calculated and prepared as in Table 2.','Preparation of simulated body fluid (SBF)',7941,8144,NULL);
INSERT INTO "outcomes" VALUES(19351,4244,'SBF_medium_preparation',NULL,'SBF prepared based on the Kokubo guidelines; the reagents were dissolved one by one in 1 L distilled water; buffered to pH = 7 with a solution of tris-hydroxyethyl aminomethane and hydrochloric acid',NULL,'The reagents were then dissolved one by one in 1 L distilled water, and the solution was buffered to pH = 7 with a solution of tris-hydroxyethyl aminomethane and hydrochloric acid.','Preparation of simulated body fluid (SBF)',8145,8325,NULL);
INSERT INTO "outcomes" VALUES(19352,4244,'SBF_immersion_duration',14.0,NULL,'days','immersion in Simulated Body Fluid (SBF) solution was carried out for 14 days under optimal conditions','Bioactive behavior of HAp powder',39559,39660,NULL);
INSERT INTO "outcomes" VALUES(19353,4244,'SBF_immersion_14_days_final_pH',NULL,'decreased to about 7 (initial pH of 7.4)',NULL,'After 14 days of nanometer hydroxyapatite immersion in the SBF solution, the solution pH decreased to about 7.','Bioactive behavior of HAp powder',39984,40094,NULL);
INSERT INTO "outcomes" VALUES(19354,4244,'bioactivity_SBF',NULL,'formation of a porous apatite layer on the HAp surface after immersion in SBF',NULL,'The formation of a porous apatite layer on the HAp surface in SBF solution is shown in Fig 21C, which indicates suitable level bioactivity of produced HAp [].','Bioactive behavior of HAp powder',41400,41558,NULL);
INSERT INTO "outcomes" VALUES(19355,4244,'SBF_EDX_Ca_P_peaks',NULL,'the peaks belonging to Ca and P have increased after immersion in SBF',NULL,'Due to the formation of an apatite layer on the HAp surface after immersion in SBF solution, the peaks belonging to Ca and P have increased.','Bioactive behavior of HAp powder',41767,41907,NULL);
INSERT INTO "outcomes" VALUES(19356,4245,'MnO2NFs_phase',NULL,'tetragonal α-MnO2',NULL,'It is in good agreement with XRD standard card JSPDF 44-0141 [,], suggesting tetragonal crystalline of α-MnO2 were successfully synthesized.','3.1. Physical Chararazation',12392,12532,NULL);
INSERT INTO "outcomes" VALUES(19357,4245,'MnO2NFs_morphology',NULL,'flower-like nanostructures composed of interconnected nanoflakes',NULL,'Obviously, flower-like nanostructures composed of interconnected nanoflakes suggests MnO2 nanoflowers were successfully synthesized.','3.1. Physical Chararazation',12674,12806,NULL);
INSERT INTO "outcomes" VALUES(19358,4246,'MnO2NFs_NrGO_morphology',NULL,'NrGO nanosheets were warped on the surface of MnO2NFs',NULL,'As shown in Figure 2C,D, the NrGO nanosheets were warped on the surface of MnO2NFs, suggesting MnO2NFs/NrGO nanocomposites were successfully prepared.','3.1. Physical Chararazation',12949,13099,NULL);
INSERT INTO "outcomes" VALUES(19359,4247,'effective_electroactive_area',0.7496,NULL,'cm2','The effective electroactive areas were estimated to be 0.0770, 0.3183, 0.3958, and 0.7496 cm2 for the bare GCE, MnO2NFs/GCE, NrGO/GCE, and MnO2NFs/NrGO/GCE, respectively.','3.2. Evaluation of Electrochemical Performances',14536,14706,NULL);
INSERT INTO "outcomes" VALUES(19360,4247,'charge_transfer_resistance',25.28,NULL,'ohm','The Rct values for the bare GCE, MnO2NFs/GCE, NrGO/GCE, and MnO2NFs/NrGO/GCE are 1950, 2551, 72.47, and 25.28 ohm, respectively.','3.2. Evaluation of Electrochemical Performances',15522,15650,NULL);
INSERT INTO "outcomes" VALUES(19361,4247,'anodic_peak_current_ferricyanide',92.41,NULL,'μA','As expected, a well-defined and sharp redox peak was observed at the MnO2NFs/NrGO/GCE, with the highest anodic and cathodic peak currents (ipa = 92.41 μA, ipc = 87.89 μA).','3.2. Evaluation of Electrochemical Performances',13651,13822,NULL);
INSERT INTO "outcomes" VALUES(19362,4247,'cathodic_peak_current_ferricyanide',87.89,NULL,'μA','As expected, a well-defined and sharp redox peak was observed at the MnO2NFs/NrGO/GCE, with the highest anodic and cathodic peak currents (ipa = 92.41 μA, ipc = 87.89 μA).','3.2. Evaluation of Electrochemical Performances',13651,13822,NULL);
INSERT INTO "outcomes" VALUES(19363,4247,'anodic_peak_current_DA_CV_10uM',14.8,NULL,'μA','Two sharp anodic peaks occurred at MnO2NFs/NrGO/GCE, and the anodic peak currents enhanced remarkably (ipa(DA) = 14.8 μA, ipa(UA) = 36.3 μA).','3.3. Voltammetric Responses of DA and UA at Various Electrodes',17854,17995,NULL);
INSERT INTO "outcomes" VALUES(19364,4247,'anodic_peak_current_UA_CV_10uM',36.3,NULL,'μA','Two sharp anodic peaks occurred at MnO2NFs/NrGO/GCE, and the anodic peak currents enhanced remarkably (ipa(DA) = 14.8 μA, ipa(UA) = 36.3 μA).','3.3. Voltammetric Responses of DA and UA at Various Electrodes',17854,17995,NULL);
INSERT INTO "outcomes" VALUES(19365,4247,'peak_potential_separation_DA_UA',150.0,'about 150 mV','mV','It is worth noting the biggest peak potential separation (about 150 mV) at MnO2NFs/NrGO/GCE, rendering this composite more selective for the simultaneous detection of UA and DA.','3.3. Voltammetric Responses of DA and UA at Various Electrodes',18417,18594,NULL);
INSERT INTO "outcomes" VALUES(19366,4247,'LOD_DA_simultaneous',0.036,NULL,'μM','The LODs are calculated to be 0.036 μM and 0.029 μM for DA and UA, respectively.','3.5. Individual and Simultaneous Determination of DA and UA',24793,24873,NULL);
INSERT INTO "outcomes" VALUES(19367,4247,'LOD_UA_simultaneous',0.029,NULL,'μM','The LODs are calculated to be 0.036 μM and 0.029 μM for DA and UA, respectively.','3.5. Individual and Simultaneous Determination of DA and UA',24793,24873,NULL);
INSERT INTO "outcomes" VALUES(19368,4247,'LOD_DA_individual',0.054,NULL,'μM','The LOD was estimated as 0.054 μM.','3.5. Individual and Simultaneous Determination of DA and UA',22789,22823,NULL);
INSERT INTO "outcomes" VALUES(19369,4247,'LOD_UA_individual',0.062,NULL,'μM','The LOD is 0.062 μM for the individual determination of UA.','3.5. Individual and Simultaneous Determination of DA and UA',23281,23340,NULL);
INSERT INTO "outcomes" VALUES(19370,4247,'linear_range_simultaneous_low',NULL,'0.02 μM–6.0 μM',NULL,'At the lower concentration region (0.02 μM–6.0 μM), the ipa(DA) and ipa(UA) enhanced linearly with their concentrations increasing (Figure 10A, B).','3.5. Individual and Simultaneous Determination of DA and UA',24100,24247,NULL);
INSERT INTO "outcomes" VALUES(19371,4247,'linear_range_simultaneous_high',NULL,'6.0 μM to 100 μM (linear in the Napierian logarithm of the concentration)',NULL,'However, the ipa(DA) and ipa(UA) are positively proportional to the Napierian logarithm of the DA and UA concentrations (lnCDA and lnCUA) at the higher concentration region from 6.0 μM to 100 μM (Figure 10C, D).','3.5. Individual and Simultaneous Determination of DA and UA',24389,24600,NULL);
INSERT INTO "outcomes" VALUES(19372,4247,'repeatability_RSD_DA',6.35,'eight successive determinations of 1 μM DA and UA (1:1)','%','To check the repeatability, eight successive determinations of 1 μM DA and UA (1:1) were also performed. The relative standard deviation (RSD) for DA and UA were 6.35% and 5.32%, respectively, indicating good repeatability.','3.6. Selectivity, Repeatability, and Reproducbility Assay',25998,26221,NULL);
INSERT INTO "outcomes" VALUES(19373,4247,'repeatability_RSD_UA',5.32,'eight successive determinations of 1 μM DA and UA (1:1)','%','To check the repeatability, eight successive determinations of 1 μM DA and UA (1:1) were also performed. The relative standard deviation (RSD) for DA and UA were 6.35% and 5.32%, respectively, indicating good repeatability.','3.6. Selectivity, Repeatability, and Reproducbility Assay',25998,26221,NULL);
INSERT INTO "outcomes" VALUES(19374,4247,'reproducibility_RSD_DA',6.02,'anodic peak currents of 1 μM DA and UA recorded at five MnO2NFs/NrGO/GCEs','%','To examine electrode reproducibility, the anodic peak currents of 1 μM DA and UA were recorded at five MnO2NFs/NrGO/GCEs, which were prepared by similar procedure. The RSD of the anodic peaks were 6.02% and 4.70% for DA and UA respectively, showing that the electrode preparation have excellent reproducibility.','3.6. Selectivity, Repeatability, and Reproducbility Assay',26222,26533,NULL);
INSERT INTO "outcomes" VALUES(19375,4247,'reproducibility_RSD_UA',4.7,'anodic peak currents of 1 μM DA and UA recorded at five MnO2NFs/NrGO/GCEs','%','To examine electrode reproducibility, the anodic peak currents of 1 μM DA and UA were recorded at five MnO2NFs/NrGO/GCEs, which were prepared by similar procedure. The RSD of the anodic peaks were 6.02% and 4.70% for DA and UA respectively, showing that the electrode preparation have excellent reproducibility.','3.6. Selectivity, Repeatability, and Reproducbility Assay',26222,26533,NULL);
INSERT INTO "outcomes" VALUES(19376,4247,'interference_tolerance',NULL,'relative errors less than 5% in the presence of 100-fold interfering species (ascorbic acid, alanine, citric acid, glutamic acid, cysteine, and lysine)',NULL,'the LSV responses of the DA and UA in the coexistence of common interfering substances (i.e., ascorbic acid, alanine, citric acid, glutamic acid, cysteine, and lysine) were compared. The relative errors (less than 5%) were accepted even in the presence of 100-fold the above interfering species, demonstrating good selectivity (Figure S1).','3.6. Selectivity, Repeatability, and Reproducbility Assay',25517,25856,NULL);
INSERT INTO "outcomes" VALUES(19377,4247,'peak_potential_separation_AA_DA',0.26,'∆Ep = 0.260 V','V','It is noted that the 100-fold AA have no obvious interfering because of the well-separated peak potential between AA and DA (∆Ep = 0.260 V).','3.6. Selectivity, Repeatability, and Reproducbility Assay',25857,25997,NULL);
INSERT INTO "outcomes" VALUES(19378,4247,'recovery_DA_serum',NULL,'96.2–105.6%',NULL,'The recoveries are 96.2–105.6% and 96.2–104.9% for DA and UA respectively','3.7. Determination of DA and UA in Human Serum Samples',26972,27045,NULL);
INSERT INTO "outcomes" VALUES(19379,4247,'recovery_UA_serum',NULL,'96.2–104.9%',NULL,'The recoveries are 96.2–105.6% and 96.2–104.9% for DA and UA respectively','3.7. Determination of DA and UA in Human Serum Samples',26972,27045,NULL);
INSERT INTO "outcomes" VALUES(19380,4247,'optimal_measurement_pH',3.93,NULL,NULL,'To ensure the highest possible anodic peak current for DA and UA, pH 3.93 was selected for the following experiments.','3.4.1. Effect of pH',19382,19499,NULL);
INSERT INTO "outcomes" VALUES(19381,4247,'optimal_scan_rate',0.1,NULL,'V s−1','To pursue high-signal to noise (S/N), 0.1 Vs−1 was recommended as the optimal scanning rate.','3.4.2. Effect of Scanning Rate',20695,20787,NULL);
INSERT INTO "outcomes" VALUES(19382,4247,'optimal_accumulation_potential',-0.3,NULL,'V','Therefore, accumulation was performed at −0.3 V for 150 s in the following experiments.','3.4.3. Influence of Accumulation Parameters',21886,21973,NULL);
