INSERT INTO "outcomes" VALUES(19653,4259,'reusability_removal_after_five_recycles',NULL,'more than 90%',NULL,'the regenerated adsorbent after the five adsorption–desorption re-cycles could still remove dyes more than 90% from the aqueous solution','Adsorbent regeneration and reuse experiments',48658,48794,NULL);
INSERT INTO "outcomes" VALUES(19654,4260,'phase',NULL,'pure zeolite X',NULL,'The prepared pure zeolite X with binary meso-microporous structure possessed remarkable thermal stability, high calcium ion exchange capacity of 248 mg/g and large surface area of 453 m2/g.','4. Conclusions',21333,21522,NULL);
INSERT INTO "outcomes" VALUES(19655,4260,'calcium_ion_exchange_capacity',248.0,NULL,'mg/g','Meanwhile, the calcium ion exchange capacity of the prepared zeolite X sample is 248 mg/g, which is higher than that of commercial zeolites X (232 mg/g).','3.4. Effect of Alkalinity',17938,18091,NULL);
INSERT INTO "outcomes" VALUES(19656,4260,'BET_surface_area',453.0,NULL,'m2/g','The specific surface area and total pore volume were up to 453 m2/g and 0.2838 cm3/g, respectively.','3.6. N2 Adsorption Performance',20226,20325,NULL);
INSERT INTO "outcomes" VALUES(19657,4260,'total_pore_volume',0.2838,NULL,'cm3/g','The specific surface area and total pore volume were up to 453 m2/g and 0.2838 cm3/g, respectively.','3.6. N2 Adsorption Performance',20226,20325,NULL);
INSERT INTO "outcomes" VALUES(19658,4260,'micropore_surface_area',399.0,NULL,'m2/g','453 | 399 | 0.2838 | 0.1866','4. Conclusions',22519,22546,NULL);
INSERT INTO "outcomes" VALUES(19659,4260,'micropore_volume',0.1866,NULL,'cm3/g','453 | 399 | 0.2838 | 0.1866','4. Conclusions',22519,22546,NULL);
INSERT INTO "outcomes" VALUES(19660,4260,'Si_Al_ratio',1.21,NULL,NULL,'Meanwhile, the Si/Al ratio is 1.21, which agrees with the theoretical value of 1.13 in the raw material.','3.5. TG-DTA and XRF Analysis',18260,18364,NULL);
INSERT INTO "outcomes" VALUES(19661,4260,'XRF_SiO2',35.31,NULL,NULL,'Optimal X zeolite | 35.31 | 24.87 | 15.17 | 0.96 | 22.90 | 1.21','4. Conclusions',22339,22402,NULL);
INSERT INTO "outcomes" VALUES(19662,4260,'XRF_Al2O3',24.87,NULL,NULL,'Optimal X zeolite | 35.31 | 24.87 | 15.17 | 0.96 | 22.90 | 1.21','4. Conclusions',22339,22402,NULL);
INSERT INTO "outcomes" VALUES(19663,4260,'XRF_Na2O',15.17,NULL,NULL,'Optimal X zeolite | 35.31 | 24.87 | 15.17 | 0.96 | 22.90 | 1.21','4. Conclusions',22339,22402,NULL);
INSERT INTO "outcomes" VALUES(19664,4260,'XRF_Fe2O3',0.96,NULL,NULL,'Optimal X zeolite | 35.31 | 24.87 | 15.17 | 0.96 | 22.90 | 1.21','4. Conclusions',22339,22402,NULL);
INSERT INTO "outcomes" VALUES(19665,4260,'XRF_H2O',22.9,NULL,NULL,'Optimal X zeolite | 35.31 | 24.87 | 15.17 | 0.96 | 22.90 | 1.21','4. Conclusions',22339,22402,NULL);
INSERT INTO "outcomes" VALUES(19666,4260,'Si_content_raw_material',3.22,NULL,'g','In addition, the contents of Si in the raw material and the synthesized X zeolite is 3.22 and 2.88 g, respectively, which is a highly efficient use of diatomite.','3.5. TG-DTA and XRF Analysis',18365,18526,NULL);
INSERT INTO "outcomes" VALUES(19667,4260,'Si_content_product',2.88,NULL,'g','In addition, the contents of Si in the raw material and the synthesized X zeolite is 3.22 and 2.88 g, respectively, which is a highly efficient use of diatomite.','3.5. TG-DTA and XRF Analysis',18365,18526,NULL);
INSERT INTO "outcomes" VALUES(19668,4260,'moisture_loss_TG',22.0,NULL,'wt %','TG results showed that the synthesized zeolite X products lost all its moisture (22 wt %) at temperatures lower than 350 °C.','3.5. TG-DTA and XRF Analysis',18773,18897,NULL);
INSERT INTO "outcomes" VALUES(19669,4260,'DTA_endothermic_peak_water_loss',150.0,NULL,'°C','Furthermore, DTA curves showed that the endothermic peaks occurred at lower temperatures (150 °C) of the synthesized zeolite X sample, which could be assigned to the loss of adsorbed water.','3.5. TG-DTA and XRF Analysis',19041,19230,NULL);
INSERT INTO "outcomes" VALUES(19670,4260,'DTA_exothermic_peak_framework_collapse',820.0,NULL,'°C','However, the exothermic peaks at the temperature of 820 °C could be attributed to the framework collapse and crystallization of NaAlSiO4 (JCPDS 52-1342), which can be attributed to the nepheline (Figure 11b).','3.5. TG-DTA and XRF Analysis',19231,19439,NULL);
INSERT INTO "outcomes" VALUES(19671,4260,'morphology_Na2O_SiO2_1.4',NULL,'better octahedral structure and uniform distribution',NULL,'On the other hand, the sample with Na2O/SiO2 ratio of 1.4 exhibited better octahedral structure and uniform distribution.','3.4. Effect of Alkalinity',17233,17354,NULL);
INSERT INTO "outcomes" VALUES(19672,4260,'calcium_ion_exchange_capacity_aging_time_series',268.0,'lu sur la figure, ± 3 mg/g','mg/g','Figure 7 Effect of (a) aging temperature and (b) aging time on CEC of zeolites prepared upon hydrothermal treatment at 110 °C and 5 h.','Figure captions',24334,24468,'Fig. 7b');
INSERT INTO "outcomes" VALUES(19673,4260,'calcium_ion_exchange_capacity_h2o_na2o_series',226.0,'lu sur la figure, ± 3 mg/g','mg/g','Figure 10 Effect of (a) H2O/Na2O ratio and (b) Na2O/SiO2 ratio on CEC upon hydrothermal treatment at 110 °C and 5 h.','Figure captions',24769,24885,'Fig. 10a');
INSERT INTO "outcomes" VALUES(19674,4260,'calcium_ion_exchange_capacity_na2o_sio2_series',236.0,'lu sur la figure, ± 3 mg/g','mg/g','Figure 10 Effect of (a) H2O/Na2O ratio and (b) Na2O/SiO2 ratio on CEC upon hydrothermal treatment at 110 °C and 5 h.','Figure captions',24769,24885,'Fig. 10b');
INSERT INTO "outcomes" VALUES(19675,4261,'phase',NULL,'only one strong diffraction peak, attributed to aluminum hydroxide',NULL,'the sample at a crystallization temperature of 90 °C showed only one strong diffraction peak at 2θ = 18.35°, which can be attributed to aluminum hydroxide','3.2. Effect of Crystallization',9571,9725,NULL);
INSERT INTO "outcomes" VALUES(19676,4261,'morphology',NULL,'spherical aggregates of ill-defined particles',NULL,'When the crystallization temperature was 90 °C, the reactants formed spherical aggregates of ill-defined particles.','3.2. Effect of Crystallization',11149,11264,NULL);
INSERT INTO "outcomes" VALUES(19677,4261,'calcium_ion_exchange_capacity',105.0,'lu sur la figure, ± 3 mg/g','mg/g','Figure 5 Effect of (a) crystallization temperature and (b) crystallization time on CEC.','Figure captions',24051,24138,'Fig. 5a');
INSERT INTO "outcomes" VALUES(19678,4262,'phase',NULL,'typical diffraction peaks of X zeolite, zeolite X started to crystallize',NULL,'When the temperature was raised to 100 °C, typical diffraction peaks of X zeolite (JCPDS 38-0237) can be seen at 2θ = 6.10°, 9.97°, 11.76°, 15.39°, 18.46°, 20.12°, 23.24°, 26.58° and 30.86° suggesting that zeolite X started to crystallize (Figure 2a).','3.2. Effect of Crystallization',9846,10097,NULL);
INSERT INTO "outcomes" VALUES(19679,4262,'XRD_peak_positions_zeolite_X',NULL,'2θ = 6.10°, 9.97°, 11.76°, 15.39°, 18.46°, 20.12°, 23.24°, 26.58° and 30.86°',NULL,'When the temperature was raised to 100 °C, typical diffraction peaks of X zeolite (JCPDS 38-0237) can be seen at 2θ = 6.10°, 9.97°, 11.76°, 15.39°, 18.46°, 20.12°, 23.24°, 26.58° and 30.86° suggesting that zeolite X started to crystallize (Figure 2a).','3.2. Effect of Crystallization',9846,10097,NULL);
INSERT INTO "outcomes" VALUES(19680,4262,'impurity',NULL,'aluminum hydroxide peak, incomplete reaction of aluminum hydroxide and silica',NULL,'However, the diffraction peak of aluminum hydroxide can also be seen at 2θ = 18.35°, which suggested an incomplete reaction of aluminum hydroxide and silica from diatomite.','3.2. Effect of Crystallization',10098,10270,NULL);
INSERT INTO "outcomes" VALUES(19681,4262,'calcium_ion_exchange_capacity',175.0,'lu sur la figure, ± 3 mg/g','mg/g','Figure 5 Effect of (a) crystallization temperature and (b) crystallization time on CEC.','Figure captions',24051,24138,'Fig. 5a');
INSERT INTO "outcomes" VALUES(19682,4263,'phase',NULL,'almost pure phase of zeolite X along with some zeolite A',NULL,'When the reaction temperature was further raised to 120 °C, almost pure phase of zeolite X was observed along with some zeolite A (JCPDS 43-0142).','3.2. Effect of Crystallization',10381,10527,NULL);
INSERT INTO "outcomes" VALUES(19683,4263,'morphology',NULL,'some cubic crystals appeared, attributed to zeolite A',NULL,'When the crystallization temperature was increased up to 120 °C, some cubic crystals appeared (Figure 3g,h), which could be attributed to the formation of zeolite A.','3.2. Effect of Crystallization',11693,11858,NULL);
INSERT INTO "outcomes" VALUES(19684,4263,'calcium_ion_exchange_capacity',203.0,'lu sur la figure, ± 3 mg/g','mg/g','Figure 5 Effect of (a) crystallization temperature and (b) crystallization time on CEC.','Figure captions',24051,24138,'Fig. 5a');
INSERT INTO "outcomes" VALUES(19685,4264,'calcium_ion_exchange_capacity',172.0,'lu sur la figure, ± 3 mg/g','mg/g','Figure 5 Effect of (a) crystallization temperature and (b) crystallization time on CEC.','Figure captions',24051,24138,'Fig. 5a');
INSERT INTO "outcomes" VALUES(19686,4265,'phase',NULL,'no zeolite X obtained',NULL,'As shown in Figure 2b, no zeolite X was obtained at crystallization time of 3 h at 110 °C.','3.2. Effect of Crystallization',10655,10745,NULL);
INSERT INTO "outcomes" VALUES(19687,4265,'calcium_ion_exchange_capacity',165.0,'lu sur la figure, ± 3 mg/g','mg/g','Figure 5 Effect of (a) crystallization temperature and (b) crystallization time on CEC.','Figure captions',24051,24138,'Fig. 5b');
INSERT INTO "outcomes" VALUES(19688,4266,'morphology',NULL,'crystals with no distinct faces, particles not uniform',NULL,'When the crystallization time was 4 h, the synthesized products formed crystals with no distinct faces, and the particles were not uniform.','3.2. Effect of Crystallization',11968,12107,NULL);
