INSERT INTO "outcomes" VALUES(19873,4328,'crystal_size',220.0,NULL,'nm','All samples showed spherical crystals with slightly increasing sizes, from ∼220 nm (1 v/v %) to ∼260 nm (3 v/v %), and then to ∼350 nm (5 v/v %), as also shown in Figure 2b–d.','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',18363,18538,NULL);
INSERT INTO "outcomes" VALUES(19874,4328,'morphology',NULL,'granular shape',NULL,'Interestingly, at 1 v/v % (overall) concentration of n-hexane in mixture-I, a distinct change in crystal morphology to granular shape was observed, as shown in Figure 2b.','Non-Surfactant-Stabilized Oil-in-Water Emulsion as the Growth Template',17968,18138,NULL);
