INSERT INTO "outcomes" VALUES(20808,4536,'phase',NULL,'significant component of the cubic CsPbBr3 perovskite phase',NULL,'The X-ray diffraction (XRD) patterns in Fig. 3a demonstrate a significant component of the cubic CsPbBr3 perovskite phase (JCPDS card No. 54-0752).','Identify the origins of chirality',13402,13549,NULL);
INSERT INTO "outcomes" VALUES(20809,4536,'morphology',NULL,'spindle-shaped chiral assemblies',NULL,'Spindle-shaped chiral assemblies were observed under TEM (Fig. 3b).','Identify the origins of chirality',13550,13617,NULL);
INSERT INTO "outcomes" VALUES(20810,4536,'crystal_quality',NULL,'poor crystallization and dispersion state limited the sample quality and CD strength',NULL,'However, the poor crystallization and dispersion state limited the sample quality and CD strength.','Results of autonomous discovery',11371,11469,NULL);
INSERT INTO "outcomes" VALUES(20811,4537,'phase',NULL,'QDs appeared in the cubic phase',NULL,'In the higher temperature region (T > 160 °C, in the purple circle), the QDs appeared in the cubic phase, as shown in Fig. 2h, i.','Results of autonomous discovery',12245,12374,NULL);
INSERT INTO "outcomes" VALUES(20812,4537,'CD_intensity',NULL,'fewer chiral assemblies as well as a decreased CD signal intensity compared with those in other phases',NULL,'Due to the high symmetry in the cubic phase, there were fewer chiral assemblies as well as a decreased CD signal intensity compared with those in other phases.','Results of autonomous discovery',12375,12534,NULL);
INSERT INTO "outcomes" VALUES(20813,4538,'CD_inversion',NULL,'inversion from L to D after 300 s of irradiation in solution',NULL,'after 300 s of irradiation in solution, the CD signal of the local optimal sample near the first exciton absorption peak showed inversion from L to D','Inversion of CD signal',16544,16693,NULL);
INSERT INTO "outcomes" VALUES(20814,4538,'inversion_origin',NULL,'regarded as orientation inversion of the chiral assembly',NULL,'the chirality inversion was regarded as belonging to the orientation inversion of the chiral assembly','Inversion of CD signal',17285,17386,NULL);
INSERT INTO "outcomes" VALUES(20815,4538,'absorption_change',NULL,'peak wavelength and intensity of optical absorption varied by <1% (value given for both irradiated samples); CD intensity after irradiation similar to the original',NULL,'The peak wavelength and intensity of optical absorption varied by <1% (the inserts in Fig. 4a, b), and the CD intensity after irradiation was similar to the original intensity.','Inversion of CD signal',16817,16993,NULL);
INSERT INTO "outcomes" VALUES(20816,4538,'nanoplate_shape_and_size',NULL,'unchanged during the laser treatment (stated for both samples)',NULL,'the shape and size of the nanoplates remained unchanged during the laser treatment','Inversion of CD signal',17036,17118,NULL);
INSERT INTO "outcomes" VALUES(20817,4538,'aggregation',NULL,'slight aggregation (stated for both samples)',NULL,'For both samples, slight aggregation occurred according to the TEM images (Fig. 4g, h).','Inversion of CD signal',18454,18541,NULL);
