INSERT INTO "outcomes" VALUES(20819,4539,'CD_inversion',NULL,'inversion from the original D to L',NULL,'The same results were achieved for chirality inversion (Fig. 4b) in the global optimal sample (from the original D to L).','Inversion of CD signal',16695,16816,NULL);
