INSERT INTO "outcomes" VALUES(21058,4557,'optimum_adsorption_pH',5.0,NULL,NULL,'The highest efficiency was attained at pH = 5 where the surface charge of the AGO2–CTS5 is negative.','Effect of pH and a plausible adsorption mechanism',45565,45665,NULL);
INSERT INTO "outcomes" VALUES(21059,4557,'diclofenac_removal_efficiency_pH10',37.32,NULL,'%','The removal efficiency experiences a sharp fall as pH increases up to 10 at which it reaches 37.32%.','Effect of pH and a plausible adsorption mechanism',47050,47150,NULL);
INSERT INTO "outcomes" VALUES(21060,4559,'regeneration_cycles_performed',NULL,'five consecutive cycles of adsorption–desorption',NULL,'Recycling experiments were run for five consecutive cycles of adsorption–desorption and the results are represented in Fig. 18.','Recyclability',48246,48373,NULL);
INSERT INTO "outcomes" VALUES(21061,4559,'efficiency_maintained_cycles',NULL,'efficiency maintained at a relatively high level for three cycles, considerable decrease between the third and the fourth cycle',NULL,'The adsorbent maintained its efficiency at a relatively high level for three cycles but a considerable decrease was observed between the third and the fourth cycle','Abstract',2135,2298,NULL);
INSERT INTO "outcomes" VALUES(21062,4559,'gel_structure_after_third_cycle',NULL,'partially destroyed after the third cycle',NULL,'Moreover, the gel structure of the hydrogel was partially destroyed after the third cycle which can influence the removal efficiency.','Recyclability',48693,48826,NULL);
INSERT INTO "outcomes" VALUES(21063,4559,'removal_efficiency_fourth_cycle_AGO2_CTS5',71.49,NULL,'%','the removal efficiency of the fourth cycle is 71.49% which is relatively low','Recyclability',48396,48472,NULL);
INSERT INTO "outcomes" VALUES(21064,4559,'removal_efficiency_drop_fourth_vs_first_cycle_AGO2_CTS5',25.57,NULL,'%','exhibiting a 25.57% drop compared to the capacity of the adsorbent in the first cycle','Recyclability',48473,48558,NULL);
INSERT INTO "outcomes" VALUES(21309,4613,'TG_first_weight_loss_stage_temperature',100.0,NULL,'°C','First stage of the weight loss at about 100°C was attributed to the loss of water and some gases adsorbed on the surface, which corresponds to an endothermic peak in the differential thermal analysis (DTA) curve.','Thermal analysis',12663,12875,NULL);
INSERT INTO "outcomes" VALUES(21310,4613,'TG_second_weight_loss_stage_temperature',200.0,NULL,'°C','The second one at about 200°C was ascribed to the burning of residual organic groups accompanied by an exothermic peak in the DTA curve which occurs at lower temperature in contrast to the previous report using TEOS as a silica precursor','Thermal analysis',12876,13113,NULL);
INSERT INTO "outcomes" VALUES(21311,4613,'DTA_densification_endotherm_range',NULL,'800-1000°C',NULL,'We can observe a broad endothermic event between 800-1000°C associated with the densification of the nanocomposites.','Thermal analysis',13118,13234,NULL);
