INSERT INTO "outcomes" VALUES(21877,4740,'first_discharge_capacity',1046.23,NULL,'mAhg−1','FV500, FV600, and FV700 electrodes fabricated with a 35 wt.% PAA binder shown in Figure 6a delivered the discharge/charge capacities of 1046.23/771.69 mAhg−1, 730.70/455.99 mAhg−1, and 686.85/367.53 mAhg−1, respectively.','3.5. Electrochemical Performance of FeVO4',32767,32987,NULL);
