INSERT INTO "outcomes" VALUES(21879,4740,'initial_coulombic_efficiency',73.75,NULL,'%','FV500, FV600, and FV700 electrodes fabricated with the PAA binder, as demonstrated in Figure 6c, deliver the initial coulombic efficiencies of 73.75%, 62.40%, and 53.50%, respectively.','3.5. Electrochemical Performance of FeVO4',36280,36464,NULL);
