INSERT INTO "outcomes" VALUES(21977,4748,'OFX_removal_NaCl_0.08_M',11.34,NULL,'%','Similarly, the removal of OFX decreased for higher concentrations of NaCl (0.08 M) and CaCl2 (0.08 M) with 11.34% and 4.63% adsorption capabilities, respectively.','3.6. Effect of Ionic Strength of Solution',41308,41470,NULL);
