INSERT INTO "outcomes" VALUES(22057,4750,'RhB_adsorption_percentage_at_equilibrium_60min',4.71,NULL,'%','the minimum time necessary for the adsorption equilibrium of RhB was 60 minutes, with an adsorption percentage of 4.71, 8.70 and 10.32% to Fe2O3, TiNPs-Fe2O3 and AgNPs-Fe2O3, respectively','Adsorption and photolysis',14775,14962,NULL);
INSERT INTO "outcomes" VALUES(22058,4750,'RhB_degradation_120min_UV',77.38,NULL,'%','After 120 min of UV radiation, 77.38% (k = 0.0124 min−1), 88.03% (k = 0.0173 min−1) and 94.10% (k = 0.022 min−1) of RhB were degraded using Fe2O3, TiNPs-Fe2O3 and AgNPs-Fe2O3, while 38.03% (k = 0.0039 min−1), 48.36% (k = 0.0055 min−1) and 58.36% (k = 0.0070 min−1) of RhB were degraded using Fe2O3, TiNPs-Fe2O3 and AgNPs-Fe2O3 under visible radiation, respectively, according to Fig. 5.','Photocatalytic performance',16518,16904,NULL);
