INSERT INTO "outcomes" VALUES(23032,4898,'UV-CWPO_COD_removal_optimal_conditions',89.7,NULL,'%','Under the conditions of H2O2 dosage of 40 mM, reaction temperature of 120 °C, reaction pressure of 0.5 MPa, catalyst dosage of 1 g/L, pH of 3, and reaction time of 60 min, the removal efficiencies of COD, TOC, and UV254 were 89.7%, 84.6%, and 98.1%, respectively.','Abstract',1458,1721,NULL);
INSERT INTO "outcomes" VALUES(23033,4898,'UV-CWPO_TOC_removal_optimal_conditions',84.6,NULL,'%','Under the conditions of H2O2 dosage of 40 mM, reaction temperature of 120 °C, reaction pressure of 0.5 MPa, catalyst dosage of 1 g/L, pH of 3, and reaction time of 60 min, the removal efficiencies of COD, TOC, and UV254 were 89.7%, 84.6%, and 98.1%, respectively.','Abstract',1458,1721,NULL);
INSERT INTO "outcomes" VALUES(23034,4898,'UV-CWPO_UV254_removal_optimal_conditions',98.1,NULL,'%','Under the conditions of H2O2 dosage of 40 mM, reaction temperature of 120 °C, reaction pressure of 0.5 MPa, catalyst dosage of 1 g/L, pH of 3, and reaction time of 60 min, the removal efficiencies of COD, TOC, and UV254 were 89.7%, 84.6%, and 98.1%, respectively.','Abstract',1458,1721,NULL);
INSERT INTO "outcomes" VALUES(23035,4898,'COD_removal_UV_photocatalysis_only',16.6,NULL,'%','Figure 10 showed that COD removal efficiency of wastewater by UV photocatalysis was quite low, only 16.6%.','3.3.1. Comparison to Several Kinds of Reaction Systems',22651,22757,NULL);
INSERT INTO "outcomes" VALUES(23036,4898,'COD_removal_CWPO_without_UV',75.9,NULL,'%','The COD removal efficiency in wastewater by CWPO was 75.9%.','3.3.1. Comparison to Several Kinds of Reaction Systems',22912,22971,NULL);
INSERT INTO "outcomes" VALUES(23037,4898,'COD_removal_H2O2_40mM',88.5,NULL,'%','When the H2O2 dosage reached 40 mM, the removal efficiencies of COD, TOC, and UV254 reached the maximum values of 88.5%, 81.2%, and 97.9%, respectively.','3.3.2. Effect of H2O2 Dosage on Wastewater Purification',23572,23724,NULL);
