INSERT INTO "outcomes" VALUES(23276,4943,'Raman_peak_assignments_cm-1',NULL,'685 and 420: combination of T2g and Eg; 448 and 341: combinations A1g + T2g and A1g + Eg; 120, 174 and 582: T2g; 652: Eg (peak positions as written in the text, same list for all samples)',NULL,'(1) the peaks at the 685 and 420 sites come from the combination of modes T2g and Eg, (2) the peaks at the 448 and 341 sites belong to the combination of modes A1g + T2g and modes A1g + Eg, (3) the peaks at the 120, 174 and 582 sites result from mode T2g, and (4) the peak at the 652 site stems from phonon mode Eg.','3.1. Structural Analysis',9001,9316,NULL);
