INSERT INTO "outcomes" VALUES(23321,4946,'DSC_new_phase_above_1100C',NULL,'apparent new phase formation above 1100 °C, especially for the samples with higher Zn contents; attributed by the authors to a ZnFe2O4 phase (« Further research can prove »)',NULL,'the results show apparent new phase formation above 1100 °C, especially for the samples with higher Zn contents. Further research can prove that this is due to the formation of a ZnFe2O4 phase.','3.1. Structural Analysis',13577,13770,NULL);
