INSERT INTO "outcomes" VALUES(23323,4946,'Raman_peak_assignments_cm-1',NULL,'685 and 420: combination of T2g and Eg; 448 and 341: combinations A1g + T2g and A1g + Eg; 120, 174 and 582: T2g; 652: Eg (peak positions as written in the text, same list for all samples)',NULL,'(1) the peaks at the 685 and 420 sites come from the combination of modes T2g and Eg, (2) the peaks at the 448 and 341 sites belong to the combination of modes A1g + T2g and modes A1g + Eg, (3) the peaks at the 120, 174 and 582 sites result from mode T2g, and (4) the peak at the 652 site stems from phonon mode Eg.','3.1. Structural Analysis',9001,9316,NULL);
INSERT INTO "outcomes" VALUES(23324,4946,'Raman_272_cm-1_T2g',NULL,'T2g mode of the cation translational vibration (dodecahedral and tetrahedral sites) at the 272 site, for pure garnet',NULL,'For pure garnet at the 272 site, the T2g mode stems from the characteristic translational vibration mode of a cation in the dodecahedral and tetrahedral sites','3.1. Structural Analysis',8519,8677,NULL);
