INSERT INTO "outcomes" VALUES(23711,5006,'TEM_morphology_and_size_trend',NULL,'minimum particle size observed at 0.28 mM; sea-urchin-like shape begins to appear',NULL,'The minimum particle size was observed at 0.28 mM, and a sea-urchin-like shape began to appear at this concentration (Fig. 5c).','HR-TEM Images',15246,15373,NULL);
INSERT INTO "outcomes" VALUES(23712,5006,'solution_color',NULL,'gray (dark)',NULL,'Fig. 2 Digital images of AuNPs. The final concentration of caffeic acid is a 0.008, b 0.04, c 0.08, d 0.12, e 0.16, f 0.2, g 0.24, h 0.28, i 0.4, j 0.48, and k 0.56 mM.','Figure captions',23052,23220,'Fig. 2h');
