INSERT INTO "outcomes" VALUES(23715,5007,'HR-TEM_particle_size',NULL,'micro-sized particles, mean particle size of >50 μm; insufficient to reduce Au3+ to AuNPs',NULL,'The lowest concentration of caffeic acid (0.008 mM) was insufficient to reduce Au3+ to AuNPs and instead generated micro-sized particles with a mean particle size of >50 μm (Additional file 1: Figure S2 (a)).','HR-TEM Images',14781,14989,NULL);
INSERT INTO "outcomes" VALUES(23716,5007,'solution_color',NULL,'no visible change in color',NULL,'In our experiments, no visible change in color was detected for caffeic acid solutions at the lowest tested concentrations of 0.008 and 0.04 mM (Fig. 2a, b).','Color of AuNP Solutions and UV-Visible Spectra',12354,12511,NULL);
INSERT INTO "outcomes" VALUES(23717,5007,'UV-vis_absorbance',NULL,'no significant absorbance',NULL,'The UV-visible spectrum obtained for the 0.008 mM solution of caffeic acid did not demonstrate any significant absorbance (Fig. 3a).','Color of AuNP Solutions and UV-Visible Spectra',12637,12769,NULL);
