INSERT INTO "outcomes" VALUES(23720,5008,'solution_color',NULL,'no visible change in color',NULL,'In our experiments, no visible change in color was detected for caffeic acid solutions at the lowest tested concentrations of 0.008 and 0.04 mM (Fig. 2a, b).','Color of AuNP Solutions and UV-Visible Spectra',12354,12511,NULL);
INSERT INTO "outcomes" VALUES(23721,5008,'UV-vis_absorbance',NULL,'slight absorbance in the range of 500–580 nm',NULL,'A slight absorbance was detected in the range of 500–580 nm with 0.04 mM caffeic acid, as shown in Fig. 3b.','Color of AuNP Solutions and UV-Visible Spectra',12770,12877,NULL);
INSERT INTO "outcomes" VALUES(23722,5008,'TEM_morphology',NULL,'polygonal particles',NULL,'To minimize the surface energies in an Au nanoparticle, the low surface free energy facets such as {111} or {100} are dominantly exposed to form the polygonal particles as shown in Fig. 7. This is consistent with our observations from HR-TEM images (Fig. 5a, b) and MD simulations (Fig. 5f, g).','DFT Interpretation',17299,17593,NULL);
