INSERT INTO "outcomes" VALUES(23825,5027,'reflectivity_edge',1.76,NULL,'eV','The particles that were produced using 6 mL TEA showed a reflectivity edge at 1.76 eV.','2.2. Effect of the Amount of TEA',8380,8466,NULL);
