INSERT INTO "outcomes" VALUES(23828,5028,'reflectivity_edge_redshift_vs_6mL_TEA',0.2,NULL,'eV','The larger nanoparticles produced using 4 mL and 2 mL TEA showed reflectivity edges that are red-shifted by ~0.1 eV and ~0.2 eV, respectively, compared to that of the SnS nanoparticles prepared using 6 mL TEA.','2.2. Effect of the Amount of TEA',8467,8676,NULL);
INSERT INTO "outcomes" VALUES(23829,5029,'particle_size_mean',3.3,NULL,'nm','When 4 mL TEA was used, the SnS particle size was 3.3 ± 0.5 nm (Figure 5c,d).','2.2. Effect of the Amount of TEA',6959,7036,NULL);
INSERT INTO "outcomes" VALUES(23830,5029,'particle_size_plus_minus',0.5,NULL,'nm','When 4 mL TEA was used, the SnS particle size was 3.3 ± 0.5 nm (Figure 5c,d).','2.2. Effect of the Amount of TEA',6959,7036,NULL);
