INSERT INTO "outcomes" VALUES(23832,5030,'yield',NULL,'less yield (8 mL TEA or more)',NULL,'It was noticed that using 8 mL TEA or more tended to highly stabilise the Sn2+ precursor complex, and therefore, slowed down the formation of SnS nanoparticles and gave less yield under the same conditions.','2.2. Effect of the Amount of TEA',7770,7976,NULL);
