INSERT INTO "outcomes" VALUES(23850,5037,'initial_discharge_capacity',1551.0,NULL,'mAh g−1','The initial discharge capacities of the NFO-600, NFO-700, and NFO-800 electrodes were 1551, 1553, and 1804 mAh g−1, and the columbic efficiencies of each sample were 76, 77, and 76%, respectively.','3. Results',15943,16139,NULL);
