INSERT INTO "outcomes" VALUES(23881,5039,'cv_cathodic_peak_first_cycle',0.7,NULL,'V','In the first cathodic cycle, a large peak at 0.7 V is observed, which is attributed to the reduction reaction of Fe3+ and Ni2+ to Fe0 and Ni0, respectively.','3. Results',16968,17124,NULL);
INSERT INTO "outcomes" VALUES(23882,5039,'cv_cathodic_peaks_subsequent_cycles',NULL,'0.8 and 1.1 V',NULL,'In the subsequent cycles, the reduction peaks were shifted to 0.8 and 1.1 V, indicating the irreversible reaction in the first cycle.','3. Results',17125,17258,NULL);
INSERT INTO "outcomes" VALUES(23883,5039,'cv_anodic_peak_first_cycle',1.6,NULL,'V','For the reversible cycle, the anodic peak at 1.6 V was related to the oxidation of Fe and Ni to Fe3+ and Ni2+, and it shifted to 1.9 V in the second cycle due to the change in the ionic environment','3. Results',17259,17456,NULL);
INSERT INTO "outcomes" VALUES(23884,5039,'cv_anodic_peak_second_cycle',1.9,NULL,'V','For the reversible cycle, the anodic peak at 1.6 V was related to the oxidation of Fe and Ni to Fe3+ and Ni2+, and it shifted to 1.9 V in the second cycle due to the change in the ionic environment','3. Results',17259,17456,NULL);
INSERT INTO "outcomes" VALUES(23885,5039,'interlayer_structure',NULL,'NiFe2O4 (outer layer)/Cr2O3 (transition layer), Fe-Cr spinel, and stainless steel (substrate)',NULL,'Consequently, the NiFe2O4 electrode was formed by NiFe2O4 (outer layer)/Cr2O3 (transition layer), Fe-Cr spinel, and stainless steel (substrate) from the outer to inner oxide layer.','3. Results',11460,11640,NULL);
INSERT INTO "outcomes" VALUES(23886,5039,'film_thickness',500.0,NULL,'nm','The mass loading of NFO on the stainless steel according to the density of NFO, and the average thickness of NFO from the cross-section SEM images, is about 0.3 mg and 500 nm.','2. Materials and Methods',7247,7422,NULL);
INSERT INTO "outcomes" VALUES(23887,5039,'mass_loading',0.3,NULL,'mg','The mass loading of NFO on the stainless steel according to the density of NFO, and the average thickness of NFO from the cross-section SEM images, is about 0.3 mg and 500 nm.','2. Materials and Methods',7247,7422,NULL);
INSERT INTO "outcomes" VALUES(23888,5039,'xps_film_thickness_vs_other_electrodes',NULL,'not similar before and after annealing (thickness of the NiFe2O4 electrode differs for NFO-800; not quantified)',NULL,'the thickness of the NiFe2O4 electrode was similar before and after annealing except for the NFO-800 electrode','3. Results',13882,13992,NULL);
INSERT INTO "outcomes" VALUES(23889,5042,'SPR_band_lambda_max',450.0,NULL,'nm','the sharp SPR band at 450 nm after 5 min exposure of sunlight','3.1. UV–Visible Spectroscopy',16400,16461,NULL);
INSERT INTO "outcomes" VALUES(23890,5042,'average_particle_size_TEM',26.0,NULL,'nm','A TEM image size distribution histogram shows that AgNPs range from 5 to 40 nm in size with an average size of 26 nm, as shown in Figure 8b.','3.5. Morphological Characterization of Biomolecule-Capped AgNPs',32014,32154,NULL);
INSERT INTO "outcomes" VALUES(23891,5042,'particle_size_range_TEM',NULL,'5 to 40 nm',NULL,'The TEM image shows the abundance of approximately spherical-shaped biomolecule-capped AgNPs with the size ranging from 5 to 40 nm.','3.5. Morphological Characterization of Biomolecule-Capped AgNPs',31743,31874,NULL);
INSERT INTO "outcomes" VALUES(23892,5042,'most_abundant_size_range_TEM_histogram',NULL,'5 to 15 nm',NULL,'The size distribution histogram shows that the maximum AgNPs were in the range of 5 to 15 nm.','3.5. Morphological Characterization of Biomolecule-Capped AgNPs',32155,32248,NULL);
INSERT INTO "outcomes" VALUES(23893,5042,'crystallite_size_XRD_Scherrer',12.02,NULL,'nm','was found to be 12.02 nm','3.5. Morphological Characterization of Biomolecule-Capped AgNPs',34673,34697,NULL);
INSERT INTO "outcomes" VALUES(23894,5042,'XRD_phase',NULL,'face-centered cubic metallic silver, JCPDS 04-0783',NULL,'The XRD pattern was obtained as per the standard powder diffraction (JCPDS) file no: 04-0783 corresponding to the silver metallic nanoparticles of the crystalline face-centered cubic (fcc) planer geometry.','3.5. Morphological Characterization of Biomolecule-Capped AgNPs',33951,34156,NULL);
INSERT INTO "outcomes" VALUES(23895,5042,'TGA_total_weight_loss_to_800C',36.63,NULL,'%','The thermal decomposition of the AgNPs occurs in several steps and shows a total weight loss of 36.63% after thermal analysis to 800 °C.','3.5. Morphological Characterization of Biomolecule-Capped AgNPs',35674,35810,NULL);
INSERT INTO "outcomes" VALUES(23896,5042,'TGA_weight_loss_30_to_130C',1.7,NULL,'%','The first weight loss of 1.70% from 30 to 130 °C is due to the moisture content and absorbed water molecules present on the surface of the AgNPs.','3.5. Morphological Characterization of Biomolecule-Capped AgNPs',35811,35956,NULL);
INSERT INTO "outcomes" VALUES(23897,5042,'TGA_weight_loss_130_to_510C',26.25,NULL,'%','Upon further heating, the sample exhibited a second weight loss of 26.25% between the temperature range of 130 and 510 °C','3.5. Morphological Characterization of Biomolecule-Capped AgNPs',35957,36078,NULL);
INSERT INTO "outcomes" VALUES(23898,5042,'TGA_weight_loss_510_to_690C',8.68,NULL,'%','the final weight loss of 8.68% took place at a temperature range of 510 to 690 °C','3.5. Morphological Characterization of Biomolecule-Capped AgNPs',36083,36164,NULL);
INSERT INTO "outcomes" VALUES(23899,5042,'calculated_AgNP_molar_concentration',6.18e-08,NULL,'mol/L','The following equation calculated the molar concentration of as-prepared AgNPs, C = 6.18 × 10−8 mol/L (Equation (7)).','3.2. AgNO3 Concentration Optimization',22740,22857,NULL);
INSERT INTO "outcomes" VALUES(23900,5042,'Ag+_complete_reduction_test_NaCl_NaBr',NULL,'no AgCl or AgBr precipitate observed after adding NaCl and NaBr to the sol',NULL,'It was clearly observed that no white precipitation of Ag+ as AgCl and yellowish precipitation of Ag+ as AgBr took place, which confirms the complete reduction/conversion of Ag+ to Ag0.','3.2. AgNO3 Concentration Optimization',21370,21555,NULL);
INSERT INTO "outcomes" VALUES(23901,5042,'colloidal_stability_30C',NULL,'no precipitation or turbidity over several days at 30 °C',NULL,'The stability of as-prepared AgNPs was determined by keeping the silver sols at 30 °C for several days. During this time, we did not observe any kind of precipitation or turbidity in the reaction mixture.','3.2. AgNO3 Concentration Optimization',20844,21048,NULL);
INSERT INTO "outcomes" VALUES(23902,5042,'RB_photodegradation_after_130_min_UV',93.37,NULL,'%','After 130 min, the percent degradation of RB was observed as 93.37%, as depicted in Figure 12b.','3.6. Photocatalytic Dye Degradation of Rhodamine B',38335,38430,NULL);
INSERT INTO "outcomes" VALUES(23903,5042,'activation_energy_RB_photodegradation',11.79,NULL,'KJ/mol','Meanwhile, the activation energy was obtained from the lnk vs. 1/T curve and was calculated to be 11.79 KJ/mol.','3.7. Effect of Temperature',39637,39748,NULL);
