INSERT INTO "outcomes" VALUES(24016,5056,'CH4_production_rate_300W_xenon_1h',48.0,NULL,'μmol g–1 h–1','Gas chromatography confirms that, in the presence of NC-ATNT, 48 μmol g–1 h–1 of CH4 and a neglectable amount of CO (0.12 μmol g–1 h–1) are released','Photocatalytic CO2 Reduction',25605,25753,NULL);
