INSERT INTO "outcomes" VALUES(24018,5056,'CH4_average_efficiency_after_4h',188.4,NULL,'μmol g–1','Besides, the average efficiency after 4 h of photoreaction for NC-ATNT is 188.4 μmol g–1 for CH4 (Figure 9b).','Photocatalytic CO2 Reduction',27183,27292,NULL);
