INSERT INTO "outcomes" VALUES(24070,5071,'phase',NULL,'mixture phases of anatase TiO2 and sodium titanate NTs',NULL,'By increasing the starting material loading from 0.5 g to 1 g, the crystal structure changes from sodium titanate to mixture phases of anatase TiO2 and sodium titanate NTs','The Effect of NaOH/TiO2 Ratio and Precursors',17163,17334,NULL);
INSERT INTO "outcomes" VALUES(24071,5072,'phase',NULL,'sodium titanate phase',NULL,'whereas the sodium titanate phase was obtained when using rutile as a precursor (Figure 5f)','The Effect of NaOH/TiO2 Ratio and Precursors',18595,18686,NULL);
INSERT INTO "outcomes" VALUES(24072,5072,'morphology',NULL,'a mixture of nanoparticles and NTs, nonhomogeneous TNTs growth',NULL,'The morphology structure of the obtained sodium titanate NTs shows a mixture of nanoparticles and NTs (Figure 5g,h), indicating nonhomogeneous TNTs growth with rutile as precursors.','The Effect of NaOH/TiO2 Ratio and Precursors',18767,18948,NULL);
INSERT INTO "outcomes" VALUES(24073,5073,'phase',NULL,'pure phase ATNT (C-ATNT) (JCPDS card no. 21-1272)',NULL,'The prepared Na2Ti3O7 (at 110 °C for 96 h) was calcinated at 400 °C for 5 h, resulting in a pure phase ATNT (C-ATNT) (JCPDS card no. 21-1272), as shown in Figure 6a.','Calcination Effect',19061,19226,NULL);
INSERT INTO "outcomes" VALUES(24074,5073,'morphology',NULL,'shorter tubular structure than the NC-ATNT',NULL,'Figure 6b,c depicts the FE-SEM images of prepared C-ATNT and shows a shorter tubular structure than the NC-ATNT (Figure 2a,b).','Calcination Effect',19669,19795,NULL);
INSERT INTO "outcomes" VALUES(24075,5073,'BET_surface_area',21.9,NULL,'m2/g','Figure 8a depicts the measured surface areas of NC-ATNT, Na2Ti3O7 NTs, and C-ATNT samples, which are 118.1, 109.6, and 21.9 m2/g, respectively.','Photocatalytic CO2 Reduction',22954,23097,NULL);
INSERT INTO "outcomes" VALUES(24076,5073,'band_gap',3.2,NULL,'eV','the estimated Eg values for NC-ATNT, Na2Ti3O7, and C-ATNT are 3.1, 3.27, and 3.2 eV, respectively','Photocatalytic CO2 Reduction',23518,23615,NULL);
INSERT INTO "outcomes" VALUES(24077,5073,'CH4_production_rate_300W_xenon_1h',17.0,NULL,'μmol g–1 h–1','while in the presence of C-ATNT, 17 μmol g–1 h–1 of CH4 and 0.8 μmol g–1 h–1 of CO are generated','Photocatalytic CO2 Reduction',25767,25863,NULL);
INSERT INTO "outcomes" VALUES(24078,5073,'CO_production_rate_300W_xenon_1h',0.8,NULL,'μmol g–1 h–1','while in the presence of C-ATNT, 17 μmol g–1 h–1 of CH4 and 0.8 μmol g–1 h–1 of CO are generated','Photocatalytic CO2 Reduction',25767,25863,NULL);
INSERT INTO "outcomes" VALUES(24079,5073,'conduction_band_position',-0.3,NULL,'V','Ec was found to be −0.25, −0.326, and −0.3 V, and Ev was 2.85, 2.944, and 2.9 V for NC-ATNT, Na2Ti3O7, and C-ATNT, respectively.','Photocatalytic CO2 Reduction',28839,28967,NULL);
INSERT INTO "outcomes" VALUES(24080,5073,'valence_band_position',2.9,NULL,'V','Ec was found to be −0.25, −0.326, and −0.3 V, and Ev was 2.85, 2.944, and 2.9 V for NC-ATNT, Na2Ti3O7, and C-ATNT, respectively.','Photocatalytic CO2 Reduction',28839,28967,NULL);
INSERT INTO "outcomes" VALUES(24081,5073,'flat_band_potential',-0.13,NULL,'V','the flat band potentials (Efb) of the NC-ATNT, C-NTNT, and Na2Ti3O7 have values of −0.11, −0.13, and −0.16 V, respectively','Photocatalytic CO2 Reduction',29218,29340,NULL);
INSERT INTO "outcomes" VALUES(24082,5073,'photocurrent_density_steady_under_simulated_solar_light',10.0,NULL,'μA/cm2','(c) PL spectra and (d) photocurrent response of NC-ATNT, Na2Ti3O7, and C-ATNT samples.','Figure captions',37316,37402,'Fig. 8d');
INSERT INTO "outcomes" VALUES(24083,5073,'PL_intensity_rank_among_NC-ATNT_Na2Ti3O7_C-ATNT',NULL,'intermediate (Na2Ti3O7 > C-ATNT > NC-ATNT)',NULL,'(c) PL spectra and (d) photocurrent response of NC-ATNT, Na2Ti3O7, and C-ATNT samples.','Figure captions',37316,37402,'Fig. 8c');
INSERT INTO "outcomes" VALUES(24084,5074,'film_formation',NULL,'a thin layer of film at the bottom of the reactor',NULL,'dried for 10 h at 70 °C in a hot air oven, forming a thin layer of film at the bottom of the reactor.','Photocatalytic CO2 Reduction',8490,8591,NULL);
INSERT INTO "outcomes" VALUES(24085,5074,'CO2_production_without_NC-ATNT_reference_for_CO2_conversion',1293.0,NULL,'μmol g–1 h–1','The CO2 conversion has been calculated by measuring the CO2 production in the absence of the NC-ATNT; it was found to be 1293 μmol g–1 h–1.','Photocatalytic CO2 Reduction',28239,28378,NULL);
INSERT INTO "outcomes" VALUES(24086,5075,'slurry_dispersion',NULL,'homogeneous dispersion',NULL,'After adding 0.005 mL of Nafion to the slurry, it was sonicated for 30 minutes to achieve a homogeneous dispersion.','Supporting Information — ao2c04211_si_001.pdf',40471,40586,NULL);
