INSERT INTO "outcomes" VALUES(24243,5100,'phase_XRD',NULL,'pics de SrCO3 orthorhombique, aucun pic typique de g-C3N4 ; pics de SrCO3 décalés légèrement vers les bas angles',NULL,'There is no observation of the typical diffraction of g-C3N4 in the synthesized composite, the diffraction peaks were mostly the same as the SrCO3, but the feature peaks positions of SrCO3 shifted slightly toward a lower diffraction angle.','Characterization of the samples',8576,8815,NULL);
INSERT INTO "outcomes" VALUES(24244,5100,'FTIR_new_peak_nitrile',2112.0,NULL,'cm−1','the peak at 2112 cm−1 assigned to the nitrile groups','Adsorption mechanism of crystal violet',23036,23088,NULL);
INSERT INTO "outcomes" VALUES(24245,5100,'morphology_SEM_TEM',NULL,'g-C3N4 couvrant incomplètement SrCO3 ; bords de feuillets de g-C3N4 et SrCO3 en bâtonnets qui se chevauchent',NULL,'In Fig. 4c, it could be seen clearly that the g-C3N4 covered on the SrCO3 incompletely.','Characterization of the samples',11979,12066,NULL);
INSERT INTO "outcomes" VALUES(24246,5100,'XPS_C1s_peak_shift',NULL,'pic à 284.2 eV déplacé à 284.6 eV après calcination mixte',NULL,'But after the blended calcinations, the peak at 284.2 eV shifted to 284.6 eV.','Characterization of the samples',13999,14076,NULL);
INSERT INTO "outcomes" VALUES(24247,5100,'CV_max_removal_rate_C0_1600mgL',98.56,NULL,'%','The maximum removal rate of CV was 98.56% when the initial concentration was 1600 mg L−1.','Abstract',954,1043,NULL);
INSERT INTO "outcomes" VALUES(24248,5100,'CV_removal_rate_10mgL_2h',97.46,NULL,'%','0.08 g tested materials were dispersed in 80 mL CV solution (10 mg L−1), respectively. After 2 h adsorption process, the removal rate of CV for tested materials is exhibited in Fig. 14. It could be seen obviously that the removal ability of g-C3N4 and SrCO3 to CV is much smaller than that of the nanocomposite. The removal rate of g-C3N4, SrCO3 and SrCO3/g-C3N4 were 31.30%, 17.30% and 97.46%, respectively.','Adsorption mechanism of crystal violet',21856,22264,NULL);
INSERT INTO "outcomes" VALUES(24249,5100,'selective_adsorption_CV_in_mixtures',NULL,'adsorption sélective de CV dans les mélanges CV/MB, CV/RhB et CV/MB/RhB ; pic UV-vis de CV très diminué, pic de MB presque inchangé',NULL,'It could be concluded that the SrCO3/g-C3N4 performed selective adsorption of CV from CV/MB/RhB.','The selective adsorption of CV',16930,17026,NULL);
INSERT INTO "outcomes" VALUES(24250,5100,'pH_effect_mixed_dyes_pH4_to_10',NULL,'le pH initial (4 à 10) n''influence pas significativement l''adsorption',NULL,'It could be seen that the initial pH (ranged from 4 to 10) of mixed dye solution did not significantly influence the adsorption process in each tested group.','The selective adsorption of CV',17141,17298,NULL);
INSERT INTO "outcomes" VALUES(24251,5100,'equilibrium_contact_time_removal_constant',120.0,NULL,'min','For all concentrations, the removal rate of CV became constant after 120 min.','Effect of contact time',17542,17619,NULL);
INSERT INTO "outcomes" VALUES(24252,5100,'optimal_dosage',1.0,NULL,'g L−1','So the amount of adsorbent 1.00 g L−1 was the suitable dosage for the adsorption of CV.','Effect of adsorbent dosage',19001,19088,NULL);
INSERT INTO "outcomes" VALUES(24253,5100,'CV_removal_rate_pH_4_to_10',NULL,'peu d''effet du pH initial de la solution de CV sur la capacité d''adsorption',NULL,'The results in Fig. 11 show that the initial pH of CV solution had little effect on the adsorption capacity.','Effect of pH',19354,19462,NULL);
INSERT INTO "outcomes" VALUES(24254,5100,'kinetic_model_best_fit',NULL,'pseudo-second ordre (R2 bien plus élevé que pour le pseudo-premier ordre)',NULL,'indicating that the pseudo-second order equation is more suitable to describe the CV adsorption with SrCO3/g-C3N4','Adsorption kinetics',20377,20490,NULL);
