INSERT INTO "outcomes" VALUES(24368,5144,'XRD_phase_purity',NULL,'impurity peaks of Li3PO4 and Fe3(PO4)2 much stronger than at 170°C; reaction did not occur sufficiently below 170°C',NULL,'Notably, the XRD pattern of the sample that reacted at 150°C appears to have a much stronger intensity of impurity peaks such as Li3PO4 and Fe3(PO4)2 than that at 170°C, indicating that the reaction for the olivine nanoparticles did not occur sufficiently below 170°C.','Results and discussion',8732,9000,NULL);
INSERT INTO "outcomes" VALUES(24369,5145,'XRD_phase_purity',NULL,'mainly olivine phase, with second phases Li3PO4 and Fe3(PO4)2',NULL,'Although the XRD pattern of the sample synthesized at 170°C showed mainly an olivine phase, it was revealed that second phases existed, such as Li3PO4 and Fe3(PO4)2, because of deficiency of heat energy.','Results and discussion',8528,8731,NULL);
INSERT INTO "outcomes" VALUES(24370,5145,'first_discharge_capacity',149.0,NULL,'mAh g-1','The first discharge capacities of the LiFePO4 synthesized at 170°C and 200°C were registered to be 149 and 168 mAh g-1, respectively.','Results and discussion',9314,9447,NULL);
INSERT INTO "outcomes" VALUES(24371,5145,'first_charge_capacity',120.0,NULL,'mAh g-1','The electrochemical performances of the LiFePO4 samples synthesized at 170°C; and 200°C. (a) Initial charge/discharge curves at a current density of 0.1 mA cm-2 in the voltage range of 2.5 to approximately 4.2 V and (b) the charge/discharge capacity retention rates.','Figure captions',13910,14176,'Fig. 2a');
INSERT INTO "outcomes" VALUES(24372,5145,'discharge_capacity_cycle_18',140.0,NULL,'mAh g-1','The electrochemical performances of the LiFePO4 samples synthesized at 170°C; and 200°C. (a) Initial charge/discharge curves at a current density of 0.1 mA cm-2 in the voltage range of 2.5 to approximately 4.2 V and (b) the charge/discharge capacity retention rates.','Figure captions',13910,14176,'Fig. 2b');
INSERT INTO "outcomes" VALUES(24373,5145,'discharge_capacity_attribution',NULL,'much lower discharge capacity than the sample at 200°C because of the impurities of Li3PO4 and Fe3(PO4)2',NULL,'However, the sample at 170°C revealed a much lower discharge capacity than the other sample because of the impurities of Li3PO4 and Fe3(PO4)2, as evidenced from XRD patterns in Figure 1.','Results and discussion',9632,9818,NULL);
INSERT INTO "outcomes" VALUES(24374,5146,'XRD_phase_purity',NULL,'all peaks indexed on orthorhombic olivine-type structure (Pnma), no second phase such as Li3PO4 or transition metal compounds',NULL,'In the case of the sample synthesized at 200°C, all of the peaks are indexed on the basis of an orthorhombic olivine-type structure (space group: Pnma), and no second phase such as Li3PO4 or transition metal compounds was observed.','Results and discussion',8296,8527,NULL);
INSERT INTO "outcomes" VALUES(24375,5146,'first_discharge_capacity',168.0,NULL,'mAh g-1','The first discharge capacities of the LiFePO4 synthesized at 170°C and 200°C were registered to be 149 and 168 mAh g-1, respectively.','Results and discussion',9314,9447,NULL);
INSERT INTO "outcomes" VALUES(24376,5146,'first_discharge_capacity_fraction_of_theoretical',99.0,NULL,'%','Interestingly, the initial discharge capacity of the sample that reacted at 200°C was close to 99% of its theoretical capacity with almost no capacity fade during the extended cycles.','Results and discussion',9448,9631,NULL);
INSERT INTO "outcomes" VALUES(24377,5146,'capacity_fade',NULL,'almost no capacity fade during the extended cycles',NULL,'Interestingly, the initial discharge capacity of the sample that reacted at 200°C was close to 99% of its theoretical capacity with almost no capacity fade during the extended cycles.','Results and discussion',9448,9631,NULL);
INSERT INTO "outcomes" VALUES(24378,5146,'first_charge_capacity',170.0,NULL,'mAh g-1','The electrochemical performances of the LiFePO4 samples synthesized at 170°C; and 200°C. (a) Initial charge/discharge curves at a current density of 0.1 mA cm-2 in the voltage range of 2.5 to approximately 4.2 V and (b) the charge/discharge capacity retention rates.','Figure captions',13910,14176,'Fig. 2a');
INSERT INTO "outcomes" VALUES(24379,5146,'discharge_capacity_cycle_43',160.0,NULL,'mAh g-1','The electrochemical performances of the LiFePO4 samples synthesized at 170°C; and 200°C. (a) Initial charge/discharge curves at a current density of 0.1 mA cm-2 in the voltage range of 2.5 to approximately 4.2 V and (b) the charge/discharge capacity retention rates.','Figure captions',13910,14176,'Fig. 2b');
INSERT INTO "outcomes" VALUES(24380,5147,'XRD_phase_purity',NULL,'all impurities disappeared, and peak intensities increased after reaction using carbon',NULL,'Even though the sample without carbon revealed little impurity peaks in XRD pattern, all impurities disappeared, and peak intensities increased after reaction using carbon.','Results and discussion',11095,11267,NULL);
INSERT INTO "outcomes" VALUES(24381,5147,'morphology',NULL,'mono-dispersed and carbon-mixed plate-type LiFePO4 nanoparticles',NULL,'In the case of the sample with 10 wt% carbon, it showed mono-dispersed and carbon-mixed plate-type LiFePO4 nanoparticles with average length, width, and thickness of approximately 100 to 300 nm, 100 to 200 nm, and 50 nm, respectively, as shown in Figure 4.','Results and discussion',11401,11657,NULL);
INSERT INTO "outcomes" VALUES(24382,5147,'particle_length',NULL,'approximately 100 to 300 nm',NULL,'In the case of the sample with 10 wt% carbon, it showed mono-dispersed and carbon-mixed plate-type LiFePO4 nanoparticles with average length, width, and thickness of approximately 100 to 300 nm, 100 to 200 nm, and 50 nm, respectively, as shown in Figure 4.','Results and discussion',11401,11657,NULL);
INSERT INTO "outcomes" VALUES(24383,5147,'particle_width',NULL,'100 to 200 nm',NULL,'In the case of the sample with 10 wt% carbon, it showed mono-dispersed and carbon-mixed plate-type LiFePO4 nanoparticles with average length, width, and thickness of approximately 100 to 300 nm, 100 to 200 nm, and 50 nm, respectively, as shown in Figure 4.','Results and discussion',11401,11657,NULL);
