INSERT INTO "outcomes" VALUES(24385,5147,'first_discharge_capacity',160.0,NULL,'mAh g-1','The first discharge capacity of the synthesized LiFePO4 with 10 wt% carbon at 170°C was registered to be 160 mAh g-1 which was close to 94% of its theoretical capacity.','Results and discussion',12105,12273,NULL);
