INSERT INTO "outcomes" VALUES(24397,5150,'phase',NULL,'tetragonal phase (PDF-79-1771) predominant',NULL,'The tetragonal phase (PDF-79-1771), evidenced by the peaks centered at about 30° and 50°, was predominant for the sample heated at 600 °C.','3.2. Effect of Thermal Treatment Temperature',18370,18508,NULL);
INSERT INTO "outcomes" VALUES(24398,5150,'wall_morphology_SEM',NULL,'more textured appearance of the macropore walls',NULL,'The main effect of the SDS amount was on the structures that composed the macropore walls, which were densest for the samples prepared with 5% SDS and had a more textured appearance when 10% and 15% SDS were used.','3.1. Effect of Sodium Dodecylsulfate (SDS) Amount',14806,15019,NULL);
INSERT INTO "outcomes" VALUES(24399,5150,'pore_morphology_SEM',NULL,'open-pore structure',NULL,'The thermal analysis revealed that large quantities of compounds were eliminated between 500 and 700 °C, leading to the open-pore structure (Figure 3c,d and Figure 8b).','3.2. Effect of Thermal Treatment Temperature',21037,21205,NULL);
