INSERT INTO "outcomes" VALUES(24435,5155,'template_removal_defects',NULL,'coalescence of pores or cracking in pore walls during removal of the template',NULL,'It was evident that an excess of SDS could be harmful to the stability of the liquid foam, as observed for the sample prepared with 20% SDS, where there was coalescence of pores or cracking in pore walls during removal of the template.','3.1. Effect of Sodium Dodecylsulfate (SDS) Amount',11072,11307,NULL);
INSERT INTO "outcomes" VALUES(24436,5155,'pore_families',NULL,'one main family of macropores (d > 4 μm) with high pore volume, together with a secondary family of supermesopores (d < 4 μm)',NULL,'The foamed samples (Figure 2b,f) presented one main family of macropores (d > 4 μm) with high pore volume, together with a secondary family of supermesopores (d < 4 μm)','3.1. Effect of Sodium Dodecylsulfate (SDS) Amount',13091,13259,NULL);
