INSERT INTO "outcomes" VALUES(24442,5156,'phase',NULL,'amorphous (no diffraction peaks)',NULL,'An amorphous structure was observed for the sample heated at 500 °C, as evidenced by the absence of diffraction peaks.','3.2. Effect of Thermal Treatment Temperature',18251,18369,NULL);
INSERT INTO "outcomes" VALUES(24443,5156,'pore_morphology_SEM',NULL,'closed pores',NULL,'At 500 °C (Figure 8a), the presence of closed pores is in agreement with the smaller pore volume observed by porosimetry, because mercury is unable to penetrate closed pores.','3.2. Effect of Thermal Treatment Temperature',20862,21036,NULL);
