INSERT INTO "outcomes" VALUES(24449,5157,'phase',NULL,'only the monoclinic crystalline phase (PDF-83-0943)',NULL,'For the samples heated at 800 and 1000 °C, only the monoclinic crystalline phase was identified (PDF-83-0943), since all the sulfate groups had been eliminated.','3.2. Effect of Thermal Treatment Temperature',18651,18811,NULL);
INSERT INTO "outcomes" VALUES(24450,5157,'pore_morphology_SEM',NULL,'open-pore structure',NULL,'The thermal analysis revealed that large quantities of compounds were eliminated between 500 and 700 °C, leading to the open-pore structure (Figure 3c,d and Figure 8b).','3.2. Effect of Thermal Treatment Temperature',21037,21205,NULL);
