INSERT INTO "outcomes" VALUES(24457,5158,'pore_wall_morphology_SEM',NULL,'pore walls seemed denser than for the other samples',NULL,'Nevertheless, at 1000 °C the pore walls seemed to be denser than for the other samples, as evidenced in the magnified image of the junction between three closed pores (Figure 8c,d).','3.2. Effect of Thermal Treatment Temperature',21206,21387,NULL);
INSERT INTO "outcomes" VALUES(24458,5159,'wet_gel_mass_loss_first_process',25.0,NULL,'%','The first started at room temperature and continued up to about 140 °C, with the loss of around 25% of the mass, and was attributed to the elimination of surface water.','3.2. Effect of Thermal Treatment Temperature',16608,16776,NULL);
INSERT INTO "outcomes" VALUES(24459,5159,'wet_gel_mass_loss_second_process',23.0,NULL,'%','The second process, which occurred between around 500 and 650 °C, corresponded to a 23% mass loss and was related to the removal of carbon and sulfates','3.2. Effect of Thermal Treatment Temperature',16777,16928,NULL);
INSERT INTO "outcomes" VALUES(24611,5200,'morphology',NULL,'microflowers consisting of several petaloid nanosheets',NULL,'the as-prepared CdS with special microflower configuration consists of several petaloid nanosheets and the thickness of the freestanding single ultrathin nanosheets is about 20 nm','Results and discussion',13927,14106,NULL);
INSERT INTO "outcomes" VALUES(24612,5200,'nanosheet_thickness',20.0,NULL,'nm','the thickness of the freestanding single ultrathin nanosheets is about 20 nm','Results and discussion',14030,14106,NULL);
INSERT INTO "outcomes" VALUES(24613,5200,'Cd_S_atomic_ratio',NULL,'close to 1 : 1',NULL,'their atomic ratio is close to 1 : 1','Results and discussion',14248,14284,NULL);
INSERT INTO "outcomes" VALUES(24614,5200,'phase',NULL,'pure-phase CdS (JCPDS no. 1-780)',NULL,'This result further confirms that the as-obtained CdS nanomaterials has pure-phase.','Results and discussion',14549,14632,NULL);
INSERT INTO "outcomes" VALUES(24615,5200,'crystal_system',NULL,'hexagonal',NULL,'(1 0 0), (0 0 2), (1 0 1), (1 0 2), (1 1 0), (1 0 3) and (1 1 2) planes of hexagonal phase','Results and discussion',14758,14848,NULL);
INSERT INTO "outcomes" VALUES(24616,5200,'direct_band_gap',2.44,NULL,'eV','indicating that the direct band gap value of CdS was 2.44 eV, CdS/Cu7S4-1 was 2.41 eV, CdS/Cu7S4-2 was 2.37 eV, CdS/Cu7S4-3 was 2.32 eV, CdS/Cu7S4-4 was 2.12 eV and CdS/Cu7S4-5 was 1.61 eV','Results and discussion',24184,24372,NULL);
INSERT INTO "outcomes" VALUES(24617,5200,'conduction_band_potential_vs_SCE',-0.61,NULL,'eV','the estimated band potentials of the samples are −0.61, −0.59, −0.59, −0.56, −0.62 and −0.60 eV versus a saturated calomel electrode (SCE) for CdS, CdS/Cu7S4-1, CdS/Cu7S4-2, CdS/Cu7S4-3, CdS/Cu7S4-4 and CdS/Cu7S4-5, respectively','Results and discussion',24949,25177,NULL);
INSERT INTO "outcomes" VALUES(24618,5200,'conduction_band_potential_vs_NHE',-0.413,NULL,'eV','the converted values are −0.413, −0.393, −0.393, −0.363, −0.423 and −0.403 eV versus NHE for CdS, CdS/Cu7S4-1, CdS/Cu7S4-2, CdS/Cu7S4-3, CdS/Cu7S4-4 and CdS/Cu7S4-5, respectively','Results and discussion',25304,25482,NULL);
INSERT INTO "outcomes" VALUES(24619,5200,'MB_degradation_time_under_UV_H2O2',280.0,NULL,'min','Fig. 4a shows that after 280 min irradiation, the MB aqueous solution is degraded into almost colourless','Results and discussion',30192,30296,NULL);
INSERT INTO "outcomes" VALUES(24620,5200,'MB_decolouring_degree_20min',15.0,NULL,'%','The decolouring degree are 15% for CdS, 44% for CdS/Cu7S4-1, 63% for CdS/Cu7S4-2, 74% for CdS/Cu7S4-3, 76% for CdS/Cu7S4-4 and 98% for CdS/Cu7S4-5 after the degradation of MB for 20 min under the same condition','Results and discussion',32000,32210,NULL);
INSERT INTO "outcomes" VALUES(24621,5200,'MB_first_order_rate_constant',0.008,NULL,'min−1','The first order rate constant of CdS, CdS/Cu7S4-1, CdS/Cu7S4-2, CdS/Cu7S4-3, CdS/Cu7S4-4 and CdS/Cu7S4-5 for degradation of the MB solution (Fig. 4h) are calculated to be 0.008 min−1, 0.039 min−1, 0.058 min−1, 0.076 min−1, 0.086 min−1 and 0.168 min−1, respectively','Results and discussion',32654,32918,NULL);
INSERT INTO "outcomes" VALUES(24622,5200,'RB@MB_decolouring_degree_15min',5.0,NULL,'%','the decolouring degree are about 5% for CdS, 57.45% for CdS/Cu7S4-1, 72.34% for CdS/Cu7S4-2, 72.77% for CdS/Cu7S4-3, 87.23% for CdS/Cu7S4-4 and 97.87% for CdS/Cu7S4-5 after the degradation of MB for 15 min under the same condition','Results and discussion',33249,33479,NULL);
INSERT INTO "outcomes" VALUES(24623,5200,'RB@MB_first_order_rate_constant',0.027,NULL,'min−1','The first order rate constant of CdS, CdS/Cu7S4-1, CdS/Cu7S4-2, CdS/Cu7S4-3, CdS/Cu7S4-4 and CdS/Cu7S4-5 for degradation of the mixed solution of RB@MB (Fig. 5h) are calculated to be 0.027 min−1, 0.058 min−1, 0.067 min−1, 0.076 min−1, 0.148 min−1 and 0.245 min−1, respectively','Results and discussion',33624,33900,NULL);
INSERT INTO "outcomes" VALUES(24624,5200,'RB@MB_last_recorded_irradiation_time_Fig5a',120.0,NULL,'min','Fig. 5 Time-dependent absorption spectra of catalytic degradation of RB@MB under UV light using the following catalysts: (a) CdS, (b) CdS/Cu7S4-1, (c) CdS/Cu7S4-2, (d) CdS/Cu7S4-3, (e) CdS/Cu7S4-4, and (f) CdS/Cu7S4-5','Figure captions',37122,37339,'Fig. 5a');
INSERT INTO "outcomes" VALUES(24625,5200,'XRD_peak_positions_hexagonal_CdS',NULL,'25.0°, 26.6°, 28.4°, 36.65°, 43.68°, 47.84° et 51.91° (2θ), indexés (1 0 0), (0 0 2), (1 0 1), (1 0 2), (1 1 0), (1 0 3) et (1 1 2) de la phase hexagonale',NULL,'The XRD diffraction peaks of pure CdS located at 25.0°, 26.6°, 28.4°, 36.65°, 43.68°, 47.84° and 51.91° are corresponding to (1 0 0), (0 0 2), (1 0 1), (1 0 2), (1 1 0), (1 0 3) and (1 1 2) planes of hexagonal phase, respectively.','Results and discussion',14633,14863,NULL);
INSERT INTO "outcomes" VALUES(24626,5200,'interlayer_spacing',NULL,'2.52 Å to 4.20 Å',NULL,'The interlayer spacing between 2.52 Å to 4.20 Å and considerably larger than Cd ion (d = 1.97 Å) and Cu ion (d Cu(i) = 1.54 Å, d Cu(ii) = 1.46 Å).','Results and discussion',15086,15232,NULL);
INSERT INTO "outcomes" VALUES(24627,5200,'Cd_S_distribution',NULL,'Cd2+ and S2− distributed uniformly',NULL,'The EDS surface scanning images prove that the Cd2+ and S2− are distributed uniformly in CdS nanomaterials (as shown in Fig. 1c).','Results and discussion',14286,14415,NULL);
INSERT INTO "outcomes" VALUES(24628,5200,'XPS_S_2p_binding_energies',NULL,'160.78 and 161.79 eV (S 2p3/2 and S 2p1/2)',NULL,'the two peaks located at 160.78 and 161.79 eV are attributed to S 2p3/2 and S 2p1/2, respectively.','Results and discussion',15897,15995,NULL);
INSERT INTO "outcomes" VALUES(24629,5201,'morphology',NULL,'collected precipitation composed of some irregular particles',NULL,'The SEM image of CdS-1 shows that the collected precipitation is composed of some irregular particles.','Results and discussion',16697,16799,NULL);
