INSERT INTO "outcomes" VALUES(24782,5224,'color_change_after_AgNO3',NULL,'light brown to dark brown (formation of nanoparticles)',NULL,'The observed color change for DW, E/DW and M/DW based plant extract solutions from light brown to dark brown after adding them to a 5 mM AgNO3 precursor solution with a 1:1 (v/v) ratio reviled the formation of nanoparticles.','Green synthesis of Va-AgNPs and solvent selection for extraction',17395,17619,NULL);
INSERT INTO "outcomes" VALUES(24783,5225,'color_change_after_AgNO3',NULL,'light brown to dark brown (formation of nanoparticles)',NULL,'The observed color change for DW, E/DW and M/DW based plant extract solutions from light brown to dark brown after adding them to a 5 mM AgNO3 precursor solution with a 1:1 (v/v) ratio reviled the formation of nanoparticles.','Green synthesis of Va-AgNPs and solvent selection for extraction',17395,17619,NULL);
