INSERT INTO "outcomes" VALUES(25572,5390,'surface_morphology',NULL,'smoother surface morphology than 30, 60 and 90 min; small particles in the form of agglomeration spread over the sample',NULL,'The TiN coating that was prepared at 120 min deposition time exhibited smoother surface morphology compared to coatings prepared at 30, 60 and 90 min deposition time.','4.2. Morphological Analysis Using Scanning Electron Microscopy (SEM)',18505,18671,NULL);
