INSERT INTO "outcomes" VALUES(25575,5390,'yield_strength_trend',NULL,'decreased with deposition time according to the authors (qualitative; inferred by them from H3/E2)',NULL,'An increase in deposition time also resulted in the consecutive reduction in yield strength of the coating.','5. Conclusions',27802,27909,NULL);
