INSERT INTO "outcomes" VALUES(26114,5470,'emission_maximum',499.0,NULL,'nm','when 22 days old precursor solution was used for the colloidal solution preparation, the emission maximum was of 499 nm','Supporting Information — 41598_2020_72826_MOESM1_ESM.docx',40241,40360,NULL);
