INSERT INTO "outcomes" VALUES(26204,5480,'specific_surface_area',32.3,NULL,'m2 g−1','the N-LMFP showed a larger specific surface area of 55.3 m2 g−1 than that of the C-LMFP (32.3 m2 g−1) and O-LMFP (19.9 m2 g−1)','Results and discussion',12797,12923,NULL);
INSERT INTO "outcomes" VALUES(26205,5480,'main_pore_size',4.0,NULL,'nm','The main pore size distribution of the N-LMFP, C-LMFP and O-LMFP composites was approximately 4 nm, whereas N-LMFP has a broad pore size distribution at the position of 9 nm','Results and discussion',12493,12666,NULL);
INSERT INTO "outcomes" VALUES(26206,5480,'particle_diameter',500.0,NULL,'nm','the N-LMFP sample prepared using FeNO3 shows the particles with a diameter of about 200 nm, which was relatively smaller than those of other two samples (approximately 500 nm)','Results and discussion',13671,13846,NULL);
INSERT INTO "outcomes" VALUES(26207,5480,'morphology',NULL,'rod-like shape with particle aggregation',NULL,'The N-LMFP exhibits a uniformly spherical morphology, whereas the C-LMFP shows a rod-like shape with particle aggregation, and O-LMFP displays a rough flake-like shape with some floc morphology on its surface.','Results and discussion',13448,13657,NULL);
INSERT INTO "outcomes" VALUES(26208,5480,'discharge_capacity_0.1C',126.0,NULL,'mA h g−1','The N-LMFP exhibited the highest initial discharge capacity of 136 mA h g−1 at 0.1C, when compared with C-LMFP (126 mA h g−1) and O-LMFP (120 mA h g−1).','Results and discussion',16264,16416,NULL);
INSERT INTO "outcomes" VALUES(26209,5480,'discharge_capacity_5C',104.0,NULL,'mA h g−1','More strikingly, a discharge capacity of 122 at 5C was obtained for the N-LMFP, whereas it was 104, and 75 mA h g−1 for C-LMFP and O-LMFP, respectively.','Results and discussion',16417,16569,NULL);
INSERT INTO "outcomes" VALUES(26210,5480,'discharge_capacity_2C',120.0,NULL,'mA h g−1','Fig. 4 The charge/discharge curves for (a) N-LMFP/C, (b) C-LMFP/C, (c) O-LMFP/C and (d) their rate capabilities.','Figure captions',23911,24023,'Fig. 4d');
INSERT INTO "outcomes" VALUES(26211,5480,'cv_peak_potential_difference',0.34,NULL,'V','the N-LMFP showed the sharpest peak and the smallest potential difference with 0.30 V between the anodic and cathodic peaks when compared with C-LMFP (0.34 V), and O-LMFP (0.38 V)','Results and discussion',18276,18455,NULL);
INSERT INTO "outcomes" VALUES(26212,5480,'cv_main_anodic_peak_current_density',0.12,NULL,'A g−1','Fig. 5 (a) The CV curves at a scan rate of 0.1 mV s−1 for the as-prepared samples, and (b) their cycling performances at 2C for 400 cycles.','Figure captions',24024,24163,'Fig. 5a');
INSERT INTO "outcomes" VALUES(26213,5480,'cycling_behaviour',NULL,'deteriorating reversible capacity and capacity retention',NULL,'In comparison, the C-LMFP and O-LMFP showed deteriorating reversible capacity and capacity retention','Results and discussion',18915,19015,NULL);
INSERT INTO "outcomes" VALUES(26214,5480,'capacity_after_400_cycles',100.0,NULL,'mA h g−1','Fig. 5 (a) The CV curves at a scan rate of 0.1 mV s−1 for the as-prepared samples, and (b) their cycling performances at 2C for 400 cycles.','Figure captions',24024,24163,'Fig. 5b');
INSERT INTO "outcomes" VALUES(26215,5480,'charge_transfer_resistance_before_cycling',150.7,NULL,'Ω','The Rct were 123.0, 150.7 and 279.7 Ω for N-LMFP, C-LMFP and O-LMFP samples, respectively, measured before the charge/discharge test.','Results and discussion',21733,21866,NULL);
INSERT INTO "outcomes" VALUES(26216,5480,'charge_transfer_resistance_after_100_cycles',358.8,NULL,'Ω','After 100 cycles, the N-LMFP merely yielded a Rct of 111.1 Ω, which was lower than those of the O-LMFP (150.1 Ω) and the C-LMFP (358.8 Ω)','Results and discussion',21867,22004,NULL);
INSERT INTO "outcomes" VALUES(26217,5480,'lithium_diffusion_coefficient_after_100_cycles',2.02e-14,NULL,'cm2 s−1','the N-LMFP had a DLi+ value of 9.54 × 10−13 cm2 s−1 after the 100th cycle, which was higher than those of O-LMFP (8.29 × 10−13 cm2 s−1) and C-LMFP (2.02 × 10−14 cm2 s−1)','Results and discussion',22083,22252,NULL);
INSERT INTO "outcomes" VALUES(26218,5481,'crystal_phase',NULL,'olivine-type LiMnPO4, Pnma, high purity',NULL,'In Fig. 1a, all the diffraction peaks of the three samples could be indexed well with the olivine-type LiMnPO4 with a Pnma space group (JCPDS 089-7115), which indicated the high purity of the three as-prepared samples.','Results and discussion',8853,9071,NULL);
INSERT INTO "outcomes" VALUES(26219,5481,'carbon_content',6.35,NULL,'wt%','The carbon coating contents of N-LMFP, C-LMFP and O-LMFP were found to be 6.32, 7.12 and 6.35 wt%, respectively.','Results and discussion',9232,9344,NULL);
INSERT INTO "outcomes" VALUES(26220,5481,'cell_volume',300.1,NULL,'Å','The cell volumes of 300.42, 300.04 and 300.10 Å for the N-LMFP, C-LMFP and O-LMFP samples, respectively, lie between those of LiFePO4 (291.47 Å) and LiMnPO4 (302.70 Å)','Results and discussion',10109,10276,NULL);
