INSERT INTO "outcomes" VALUES(26235,5481,'capacity_limitation_cause_proposed',NULL,'deteriorating capacity may mainly be caused by the incomplete reduction of Fe2O3',NULL,'Therefore, it was speculated that the deteriorating capacity of the O-LMFP may mainly be caused by the incomplete reduction of Fe2O3.','Results and discussion',19338,19471,NULL);
INSERT INTO "outcomes" VALUES(26236,5482,'specific_capacity',122.0,NULL,'mA h g−1','As shown in Fig. S5 (ESI†), the pure LMP yielded a lower specific capacity of 122 mA h g−1 than the doped N-LMFP','Results and discussion',17519,17631,NULL);
INSERT INTO "outcomes" VALUES(26237,5482,'morphology_after_200_cycles',NULL,'showed some agglomerates in the cross section of the powder after 200 cycles',NULL,'In Fig. 6, the spherical morphology of the N-LMFP sample was almost maintained after the cycling, whereas the as-prepared pure LiMnPO4 (LMP/C) showed some agglomerates in the cross section of the powder after 200 cycles.','Results and discussion',19645,19865,NULL);
INSERT INTO "outcomes" VALUES(26238,5482,'mn_content_loss_after_cycling_vs_N-LMFP',NULL,'reduction of Mn content after recycling larger than in N-LMFP',NULL,'A comparison of the EDS analyses (Fig. S6 and S7, ESI†) showed that the reduction of Mn content in the N-LMFP samples after recycling was lower than that of the LMP/C material','Results and discussion',19866,20041,NULL);
