INSERT INTO "outcomes" VALUES(26346,5494,'optimal_ratio',NULL,'1:1',NULL,'Due to the conjugate instability at increased QDs concentration with changes in optical spectra away from the porphyrin, ratio, 1:1 was selected as optimum ratio for CuInS/ZnS:TPPS4 to maintain the spectroscopic properties of both the porphyrin and QDs within the conjugate.','Conjugation of TPPS4 porphyrin with CuInS/ZnS QDs',19139,19413,NULL);
