INSERT INTO "outcomes" VALUES(26370,5506,'total_pore_volume',0.4262,NULL,'cc/g','The calculated BET surface area, total pore volume, and average pore diameter of CuGA 90–2.2 are 198.22 m2/g, 0.4262 cc/g, and 8.6 nm, respectively','Characterization of CuGA MOF',10390,10537,NULL);
INSERT INTO "outcomes" VALUES(26371,5506,'average_pore_diameter',8.6,NULL,'nm','The calculated BET surface area, total pore volume, and average pore diameter of CuGA 90–2.2 are 198.22 m2/g, 0.4262 cc/g, and 8.6 nm, respectively','Characterization of CuGA MOF',10390,10537,NULL);
INSERT INTO "outcomes" VALUES(26372,5506,'N2_isotherm_type',NULL,'type IV isotherm, mesoporous, H3 hysteresis loop',NULL,'A hysteresis loop was observed at P/P0 = 0.5, and the curve is a type IV isotherm curve which indicates that CuGA 90–2.2 has a mesoporous structure with an H3 hysteresis loop caused by a delay of the desorption process–.','Characterization of CuGA MOF',10169,10389,NULL);
INSERT INTO "outcomes" VALUES(26373,5506,'thermal_stability_TGA',219.0,NULL,'°C','The TGA result (Fig. 3b) shows that CuGA 90–2.2 was thermally stable up to 219 °C.','Characterization of CuGA MOF',9469,9551,NULL);
INSERT INTO "outcomes" VALUES(26374,5506,'TGA_weight_loss_220_257C',43.7,NULL,'%','At higher temperature (220–257 °C), significant weight loss at approximately 43.7% was observed which indicates thermal degradation of the ligand building blocks.','Characterization of CuGA MOF',9552,9714,NULL);
INSERT INTO "outcomes" VALUES(26375,5506,'TGA_residue_above_257C',48.8,NULL,'%','This suggests that no additional breakdown occurred in the sample, and approximately 48.8% weight of Cu-residue remain in metal oxide form.','Characterization of CuGA MOF',9799,9938,NULL);
INSERT INTO "outcomes" VALUES(26376,5506,'TGA_water_loss',7.5,NULL,'%','Figure 3 (a) FTIR chromatogram, (b) TGA thermogram, (c) N2 sorption isotherm, and (d) SEM image of CuGA 90–2.2.','Figure captions',26457,26568,'Fig. 3b');
INSERT INTO "outcomes" VALUES(26377,5506,'morphology_SEM',NULL,'irregular granular shaped particles with rough surface morphology, no specific geometry',NULL,'The SEM image of CuGA (Fig. 3d) shows the irregular granular shaped particles with rough surface morphology.','Characterization of CuGA MOF',10879,10987,NULL);
INSERT INTO "outcomes" VALUES(26378,5506,'elemental_analysis',NULL,'calculated formula Cu2C8H6O8 (fw.296): 26.90% C, 1.80% H, and 35.30% O',NULL,'This TGA result is congruent with results on the elemental analysis of the CuGA 90–2.2; calculated formula Cu2C8H6O8 (fw.296): 26.90% C, 1.80% H, and 35.30% O.','Characterization of CuGA MOF',9939,10098,NULL);
INSERT INTO "outcomes" VALUES(26379,5506,'pHPZC',4.41,NULL,NULL,'The pHPZC of the CuGA 90–2.2 is about 4.41; thus, at pH 6 and 7, the surface charge of this MOF is negative.','Effect of pH on the adsorption of dye by CuGA 90–2.2',11599,11707,NULL);
INSERT INTO "outcomes" VALUES(26380,5506,'MB_removal_at_pH6',98.0,NULL,'%','Figure 4 (a) Effect of pH on the efficiency of CuGA 90–2.2 for MB (blue bar) and CR (red bar) removal.','Figure captions',26569,26671,'Fig. 4a');
INSERT INTO "outcomes" VALUES(26381,5506,'CR_removal_at_pH7',99.0,NULL,'%','Figure 4 (a) Effect of pH on the efficiency of CuGA 90–2.2 for MB (blue bar) and CR (red bar) removal.','Figure captions',26569,26671,'Fig. 4a');
INSERT INTO "outcomes" VALUES(26382,5506,'MB_removal_best_pH',6.0,NULL,NULL,'The percent removal of MB and CR peaked at pH 6 and 7, respectively.','Effect of pH on the adsorption of dye by CuGA 90–2.2',11372,11440,NULL);
INSERT INTO "outcomes" VALUES(26383,5506,'CR_removal_best_pH',7.0,NULL,NULL,'The percent removal of MB and CR peaked at pH 6 and 7, respectively.','Effect of pH on the adsorption of dye by CuGA 90–2.2',11372,11440,NULL);
INSERT INTO "outcomes" VALUES(26384,5506,'MB_removal_efficiency_after_5_cycles',94.96,NULL,'%','After fifth adsorption–desorption cycles, the efficiency of CuGA is 94.96% and 93.82% for MB and CR, respectively—with the corresponding adsorption capacity for MB and CR removal of 115.51 mg/g and 310.67 mg/g, respectively.','Reusability',19250,19474,NULL);
INSERT INTO "outcomes" VALUES(26385,5506,'CR_removal_efficiency_after_5_cycles',93.82,NULL,'%','After fifth adsorption–desorption cycles, the efficiency of CuGA is 94.96% and 93.82% for MB and CR, respectively—with the corresponding adsorption capacity for MB and CR removal of 115.51 mg/g and 310.67 mg/g, respectively.','Reusability',19250,19474,NULL);
INSERT INTO "outcomes" VALUES(26386,5506,'MB_adsorption_capacity_after_5_cycles',115.51,NULL,'mg/g','After fifth adsorption–desorption cycles, the efficiency of CuGA is 94.96% and 93.82% for MB and CR, respectively—with the corresponding adsorption capacity for MB and CR removal of 115.51 mg/g and 310.67 mg/g, respectively.','Reusability',19250,19474,NULL);
INSERT INTO "outcomes" VALUES(26387,5506,'CR_adsorption_capacity_after_5_cycles',310.67,NULL,'mg/g','After fifth adsorption–desorption cycles, the efficiency of CuGA is 94.96% and 93.82% for MB and CR, respectively—with the corresponding adsorption capacity for MB and CR removal of 115.51 mg/g and 310.67 mg/g, respectively.','Reusability',19250,19474,NULL);
INSERT INTO "outcomes" VALUES(26388,5506,'MB_adsorption_capacity_cycle_1',120.0,NULL,'mg/g','Figure 8 Effect of recycle number of Cu-GA MOF on the (a) MB and (b) CR adsorption capacity.','Figure captions',27199,27291,'Fig. 8a');
INSERT INTO "outcomes" VALUES(26389,5506,'CR_adsorption_capacity_cycle_1',330.0,NULL,'mg/g','Figure 8 Effect of recycle number of Cu-GA MOF on the (a) MB and (b) CR adsorption capacity.','Figure captions',27199,27291,'Fig. 8b');
INSERT INTO "outcomes" VALUES(26390,5506,'PXRD_after_5_cycles',NULL,'no significant change in the PXRD pattern before and after 5 cycles',NULL,'As shown in Fig. 7b, there is no significant change in the PXRD pattern of the adsorbent before and after 5 cycles of dye removal.','Reusability',19598,19728,NULL);
