INSERT INTO "outcomes" VALUES(27259,5611,'phase',NULL,'hexagonal wurtzite structure of ZnO with space group P63mc',NULL,'The XRD spectra in Figure 2a,b revealed broad peaks at 31.63°, 34.50°, 36.25°, 47.50°, 56.60°, 62.80° and 67.92°; these diffraction peaks matched the JCPDS file for ZnO (JCPDS 36–1451) and were indexed as a hexagonal wurtzite structure of ZnO with space group P63mc.','Results and discussion',13824,14090,NULL);
