INSERT INTO "outcomes" VALUES(27315,5622,'pHpzc',4.6,NULL,NULL,'the pHpzc values of the three frameworks are 4.8, 4.9, and 4.6, respectively (Figure b)','Comparative Adsorption Performance and Structure–Activity Relationship',34290,34377,NULL);
INSERT INTO "outcomes" VALUES(27316,5622,'CIP_removal_efficiency_5_min_pH7_20mg',90.0,NULL,'%','The experiments were conducted using 20 mg of the adsorbent dispersed in 25 mL of a 10 mg L–1 CIP solution at a neutral pH of 7. The results, depicted in Figure , reveal a remarkably rapid adsorption process. A substantial removal efficiency of 90% was achieved within the first 5 min, corresponding to an adsorption capacity (q t ) of 11.25 mg g–1.','Effect of Contact Time',19958,20307,NULL);
INSERT INTO "outcomes" VALUES(27317,5622,'CIP_removal_efficiency_20_min_pH7_20mg',93.9,NULL,'%','The experiments were conducted using 20 mg of the adsorbent dispersed in 25 mL of a 10 mg L–1 CIP solution at a neutral pH of 7. The results, depicted in Figure , reveal a remarkably rapid adsorption process. A substantial removal efficiency of 90% was achieved within the first 5 min, corresponding to an adsorption capacity (q t ) of 11.25 mg g–1. This initial fast uptake phase is characteristic of processes where a high number of readily accessible active sites are available on the adsorbent surface. The system then approached equilibrium, reaching a removal efficiency of 93.9% (11.74 mg g–1) at the 20 min mark.','Effect of Contact Time',19958,20578,NULL);
INSERT INTO "outcomes" VALUES(27318,5622,'CIP_removal_efficiency_60_min_pH7_20mg',94.3,NULL,'%','The experiments were conducted using 20 mg of the adsorbent dispersed in 25 mL of a 10 mg L–1 CIP solution at a neutral pH of 7. The results, depicted in Figure , reveal a remarkably rapid adsorption process. A substantial removal efficiency of 90% was achieved within the first 5 min, corresponding to an adsorption capacity (q t ) of 11.25 mg g–1. This initial fast uptake phase is characteristic of processes where a high number of readily accessible active sites are available on the adsorbent surface. The system then approached equilibrium, reaching a removal efficiency of 93.9% (11.74 mg g–1) at the 20 min mark. Beyond this point, the adsorption rate slowed considerably, with only a marginal increase to a maximum of 94.3% (11.79 mg g–1) observed at 60 min.','Effect of Contact Time',19958,20725,NULL);
INSERT INTO "outcomes" VALUES(27319,5622,'CIP_removal_efficiency_dose_range',NULL,'rose from 87.5% to 94.8%',NULL,'As shown in Figure , increasing the dosage resulted in a higher removal efficiency, which rose from 87.5% to 94.8%.','Effect of Adsorbent Dosage',21420,21535,NULL);
INSERT INTO "outcomes" VALUES(27320,5622,'CIP_adsorption_capacity_dose_range',NULL,'decreased from 43.8 to 7.9 mg g–1',NULL,'Conversely, the adsorption capacity (q e) decreased from 43.8 to 7.9 mg g–1, a result of a lower adsorbate-to-adsorbent ratio.','Effect of Adsorbent Dosage',21618,21744,NULL);
INSERT INTO "outcomes" VALUES(27321,5622,'CIP_removal_efficiency_pH_5',97.6,NULL,'%','Removal efficiency peaked at pH 5 with a removal rate of 97.6%, and then gradually decreased to 74.8% at pH 10.','Effect of pH',22338,22449,NULL);
INSERT INTO "outcomes" VALUES(27322,5622,'CIP_removal_efficiency_pH_10',74.8,NULL,'%','Removal efficiency peaked at pH 5 with a removal rate of 97.6%, and then gradually decreased to 74.8% at pH 10.','Effect of pH',22338,22449,NULL);
INSERT INTO "outcomes" VALUES(27323,5622,'CIP_removal_efficiency_C0_range',NULL,'decreased from 97.6% to 71.7% as the concentration increased from 10 to 300 mg L–1',NULL,'which decreased from 97.6% to 71.7% as the concentration increased from 10 to 300 mg L–1','Effect of Initial CIP Concentration',24158,24246,NULL);
INSERT INTO "outcomes" VALUES(27324,5622,'CIP_adsorption_capacity_C0_range',NULL,'from 9.76 to 215.2 mg g–1',NULL,'In contrast, the adsorption capacity (q e) increased significantly with rising C 0, from 9.76 to 215.2 mg g–1.','Effect of Initial CIP Concentration',24463,24573,NULL);
INSERT INTO "outcomes" VALUES(27325,5622,'PSO_qe_calculated',9.86,NULL,'mg g–1','the equilibrium adsorption capacity predicted by the PSO model (q e,cal = 9.86 mg g–1)','Kinetics of Adsorption',25592,25678,NULL);
