INSERT INTO "outcomes" VALUES(27334,5622,'adsorption_enthalpy_dH',-34.49,NULL,'kJ mol–1','The enthalpy change (ΔH° = −34.49 kJ mol–1) further confirms the exothermic nature of the adsorption process.','Adsorption Thermodynamics',30851,30960,NULL);
