INSERT INTO "outcomes" VALUES(27999,5717,'solid_state',NULL,'precursor nanoparticles observed',NULL,'precursor nanoparticles were observed when the sample crystallized for 24 h','2.3. Investigation on MWW Zeolite Crystallization',14689,14764,NULL);
INSERT INTO "outcomes" VALUES(28000,5717,'solid_state_scheme',NULL,'precursor particles gradually aggregated into larger particles',NULL,'(1) in the first 24 h, the precursor particles gradually aggregated into larger particles','2.4. The Proposed Mechanism of Crystallization of MWW Zeolite',18514,18603,NULL);
INSERT INTO "outcomes" VALUES(28001,5718,'solid_state',NULL,'crystallization by nanoparticle-by-nanoparticle attachment',NULL,'the crystallization occurs by nanoparticle-by-nanoparticle attachment with the crystallization to 36 h as shown in SEM (Figure 4)','2.3. Investigation on MWW Zeolite Crystallization',14770,14899,NULL);
INSERT INTO "outcomes" VALUES(28002,5718,'solid_state_scheme',NULL,'larger particles accumulated to a hydrogel network (24 h to 36 h)',NULL,'(2) the larger particles were further accumulated to a hydrogel network with the prolonged reaction time from 24 h to 36 h','2.4. The Proposed Mechanism of Crystallization of MWW Zeolite',18605,18727,NULL);
INSERT INTO "outcomes" VALUES(28003,5719,'solid_state',NULL,'many small nanoparticles still around the large aggregated ones (attachment)',NULL,'From the SEM picture of 48 h, it can be seen that many small nanoparticles were still around the large aggregated ones, suggesting the state of attachment.','2.3. Investigation on MWW Zeolite Crystallization',14901,15056,NULL);
INSERT INTO "outcomes" VALUES(28004,5720,'solid_state',NULL,'amorphous components nearly completely consumed, gradual growth into large crystals',NULL,'When the reaction reached 72 h, the amorphous components were nearly completely consumed, and then gradually grew into large crystals.','2.3. Investigation on MWW Zeolite Crystallization',15057,15191,NULL);
INSERT INTO "outcomes" VALUES(28005,5720,'solid_state_scheme',NULL,'network changed into an ellipsoid shape with a micro size and low crystallinity',NULL,'(3) the network quickly changed into an ellipsoid shape with a micro size and low crystallinity when reaction prolonged to 72 h','2.4. The Proposed Mechanism of Crystallization of MWW Zeolite',18729,18856,NULL);
INSERT INTO "outcomes" VALUES(28006,5720,'XRD_reflections',NULL,'(100), (002), (101) and (102) reflections with high intensity appear on the third day',NULL,'For all the samples, crystallization almost finished accompanied by the emergence of (100), (002), (101), and (102) reflection planes with high peak intensity that appear on the third day.','2.3. Investigation on MWW Zeolite Crystallization',16872,17060,NULL);
INSERT INTO "outcomes" VALUES(28007,5720,'induction_time',72.0,NULL,'h','NaHCO3 (36 h) < Na2CO3 (72 h) = NaOH (72 h)','Abstract',889,932,NULL);
INSERT INTO "outcomes" VALUES(28008,5721,'solid_state',NULL,'larger sphere (Ostwald ripening), highest crystallinity',NULL,'After 5 days, the sphere grew larger due to the Ostwald ripening and the crystallinity reached its highest.','2.3. Investigation on MWW Zeolite Crystallization',15192,15299,NULL);
INSERT INTO "outcomes" VALUES(28009,5721,'XRD',NULL,'integrated peaks are seen on the 5th day (change of the PXRD patterns not obvious before)',NULL,'The change of the PXRD patterns of the samples is not so obvious until the 5th day when the integrated peaks are seen','2.3. Investigation on MWW Zeolite Crystallization',15300,15417,NULL);
INSERT INTO "outcomes" VALUES(28010,5721,'solid_state_scheme',NULL,'fine crystalline mesocrystal MWW zeolite with a rough surface',NULL,'(4) finally, a fine crystalline mesocrystal MWW zeolite with a rough surface is obtained','2.4. The Proposed Mechanism of Crystallization of MWW Zeolite',18858,18946,NULL);
INSERT INTO "outcomes" VALUES(28011,5722,'solid_state',NULL,'amorphous haze (broad reflection from 5 to 50°)',NULL,'For Na2CO3 added sample, on the first day, an amorphous haze was obtained judging from a broad reflection from 5 to 50°.','2.3. Investigation on MWW Zeolite Crystallization',15433,15553,NULL);
INSERT INTO "outcomes" VALUES(28012,5723,'solid_state',NULL,'weak PXRD peaks, precursor aggregates',NULL,'After 48 h, weak PXRD peaks appear, the precursor aggregates with a particle size of about ca. 6 μm, as shown in SEM (Figure 4).','2.3. Investigation on MWW Zeolite Crystallization',15554,15682,NULL);
INSERT INTO "outcomes" VALUES(28013,5723,'aggregate_size',6.0,NULL,'μm','After 48 h, weak PXRD peaks appear, the precursor aggregates with a particle size of about ca. 6 μm, as shown in SEM (Figure 4).','2.3. Investigation on MWW Zeolite Crystallization',15554,15682,NULL);
INSERT INTO "outcomes" VALUES(28014,5724,'solid_state',NULL,'more crystals with high crystallinity',NULL,'More crystals with high crystallinity were produced when the growth time increased to 5 d.','2.3. Investigation on MWW Zeolite Crystallization',15934,16024,NULL);
INSERT INTO "outcomes" VALUES(28015,5725,'solid_state',NULL,'aggregated plates composed of nanoparticles',NULL,'the aggregated plates composed of nanoparticles appear at the first 24 h','2.3. Investigation on MWW Zeolite Crystallization',16237,16309,NULL);
INSERT INTO "outcomes" VALUES(28016,5726,'solid_state',NULL,'larger aggregated precipitates further grown, no hydrogel network',NULL,'(2) the larger aggregated precipitates further grew at 36 h instead of forming a hydrogel network','2.4. The Proposed Mechanism of Crystallization of MWW Zeolite',19165,19262,NULL);
INSERT INTO "outcomes" VALUES(28017,5726,'induction_time',36.0,NULL,'h','NaHCO3 (36 h) < Na2CO3 (72 h) = NaOH (72 h)','Abstract',889,932,NULL);
INSERT INTO "outcomes" VALUES(28018,5727,'morphology',NULL,'hexahedron, spiral growth observed',NULL,'Different from the round sphere above, hexahedron morphology was obtained at 48 h, and spiral growth can be observed','2.3. Investigation on MWW Zeolite Crystallization',16404,16520,NULL);
INSERT INTO "outcomes" VALUES(28019,5727,'XRD',NULL,'whole peaks with weak intensity were seen',NULL,'From the PXRD patterns (Figure S10c), whole peaks with weak intensity were seen.','2.3. Investigation on MWW Zeolite Crystallization',16582,16662,NULL);
INSERT INTO "outcomes" VALUES(28020,5728,'morphology',NULL,'single hexahedron grown into multilayers',NULL,'With a prolonged reaction time of 72 h, single hexahedron grew into multilayers.','2.3. Investigation on MWW Zeolite Crystallization',16663,16743,NULL);
INSERT INTO "outcomes" VALUES(28021,5728,'XRD_reflections',NULL,'(100), (002), (101) and (102) reflections with high intensity appear on the third day',NULL,'For all the samples, crystallization almost finished accompanied by the emergence of (100), (002), (101), and (102) reflection planes with high peak intensity that appear on the third day.','2.3. Investigation on MWW Zeolite Crystallization',16872,17060,NULL);
INSERT INTO "outcomes" VALUES(28022,5729,'solid_state',NULL,'aggregated plate-like particles of a few micrometres (SEM image, scale bar 3 μm)',NULL,'SEM pictures of the samples synthesized with Na salts at different crystalline time','Figure captions',26073,26156,'Fig. 4');
INSERT INTO "outcomes" VALUES(28023,5730,'solid_state',NULL,'crystallinity markedly increased with larger particle size between 48 and 72 h',NULL,'The crystallinity of the sample markedly increased with the larger particle size between 48 and 72 h.','2.3. Investigation on MWW Zeolite Crystallization',15683,15784,NULL);
INSERT INTO "outcomes" VALUES(28024,5730,'solid_state_figure',NULL,'spherical aggregates of plate-like particles (SEM image, scale bar 5 μm)',NULL,'SEM pictures of the samples synthesized with Na salts at different crystalline time','Figure captions',26073,26156,'Fig. 4');
INSERT INTO "outcomes" VALUES(28025,5730,'XRD_reflections',NULL,'(100), (002), (101) and (102) reflections with high intensity appear on the third day',NULL,'For all the samples, crystallization almost finished accompanied by the emergence of (100), (002), (101), and (102) reflection planes with high peak intensity that appear on the third day.','2.3. Investigation on MWW Zeolite Crystallization',16872,17060,NULL);
INSERT INTO "outcomes" VALUES(28026,5730,'induction_time',72.0,NULL,'h','NaHCO3 (36 h) < Na2CO3 (72 h) = NaOH (72 h)','Abstract',889,932,NULL);
INSERT INTO "outcomes" VALUES(28027,5731,'solid_state',NULL,'high crystalline structure with more regular morphology at the final stage of the crystallization',NULL,'(4) a high crystalline structure with more regular morphology could be collected at the final stage of the crystallization','2.4. The Proposed Mechanism of Crystallization of MWW Zeolite',19388,19510,NULL);
INSERT INTO "outcomes" VALUES(28028,5731,'solid_state_figure',NULL,'multilayered plate-like crystals, 20 μm scale bar (SEM image)',NULL,'SEM pictures of the samples synthesized with Na salts at different crystalline time','Figure captions',26073,26156,'Fig. 4');
