INSERT INTO "outcomes" VALUES(28142,5744,'MTA_methanol_conversion_vs_TOS',NULL,'about 99% up to about 60 h, then 70% at about 72 h (last point)',NULL,'Figure 8. Conversion of methanol with time on stream (TOS) over HZSM-5 catalysts of different crystal sizes with the same core and the same crystal size with different cores.','Figure captions',35603,35777,'Fig. 8f');
INSERT INTO "outcomes" VALUES(28143,5745,'crystal_size',NULL,'obviously decreased relative to the unseeded sample, relatively uniform, agglomeration observed',NULL,'With the addition of 0.2 wt.% silicalite-1 seeds crystallized for 1 d at 60°C, the crystal size of the prepared ZSM-5 zeolite obviously decreased and was relatively uniform, although the phenomenon of agglomeration was observed.','Effect of the silicalite-1 seed on physico-chemical properties of ZSM-5 zeolites',11734,11962,NULL);
INSERT INTO "outcomes" VALUES(28144,5748,'crystal_size',NULL,'no evident change from the 20 d seed sample',NULL,'The crystal size of ZSM-5 zeolite did not show evident changes when the crystallization time of the used seed exceeded 10 d (figure 2e,f).','Effect of the silicalite-1 seed on physico-chemical properties of ZSM-5 zeolites',12111,12249,NULL);
INSERT INTO "outcomes" VALUES(28145,5749,'morphology_stability',NULL,'size and morphology unchanged when the crystallization time was prolonged',NULL,'The size and morphology of ZSM-5 remained unchanged when the crystallization time was prolonged (figure 4d–f).','Effect of the silicalite-1 seed on physico-chemical properties of ZSM-5 zeolites',16702,16812,NULL);
INSERT INTO "outcomes" VALUES(28146,5749,'relative_crystallinity',99.0,NULL,'%','Figure 5. (a) XRD patterns of ZSM-5 synthesized with different crystallization times by using 0.8 wt.% S80 and (b) the crystallization curves of the synthesized ZSM-5 zeolites with or without adding seeds.','Figure captions',35076,35281,'Fig. 5b');
INSERT INTO "outcomes" VALUES(28147,5750,'morphology',NULL,'irregular granules with the crystal size of several tenths nanometers, smaller than the added S80 seeds',NULL,'In the initial stage, the gel used to synthesize ZSM-5 was almost full of irregular granules with the crystal size of several tenths nanometers which were smaller than the added S80 seeds (figure 4a).','Effect of the silicalite-1 seed on physico-chemical properties of ZSM-5 zeolites',15826,16026,NULL);
INSERT INTO "outcomes" VALUES(28148,5750,'XRD',NULL,'only partially dissolved seeds with damaged structures; XRD peak strength very weak',NULL,'At the initial stage of crystallization (1 h), only partially dissolved seeds with damaged structures existed. Therefore, the peak strength of XRD was very weak.','Effect of the silicalite-1 seed on physico-chemical properties of ZSM-5 zeolites',16940,17101,NULL);
INSERT INTO "outcomes" VALUES(28149,5750,'relative_crystallinity',0.0,NULL,'%','Figure 5. (a) XRD patterns of ZSM-5 synthesized with different crystallization times by using 0.8 wt.% S80 and (b) the crystallization curves of the synthesized ZSM-5 zeolites with or without adding seeds.','Figure captions',35076,35281,'Fig. 5b');
INSERT INTO "outcomes" VALUES(28150,5751,'morphology',NULL,'ZSM-5 crystals with fluffy round morphology',NULL,'With increasing the crystallization time, the amorphous silica and alumina species located around the seeds started to deposit onto the seed surface and agglomerate together to generate ZSM-5 crystals with fluffy round morphology (figure 4b).','Effect of the silicalite-1 seed on physico-chemical properties of ZSM-5 zeolites',16359,16601,NULL);
INSERT INTO "outcomes" VALUES(28151,5751,'relative_crystallinity',55.0,NULL,'%','Figure 5. (a) XRD patterns of ZSM-5 synthesized with different crystallization times by using 0.8 wt.% S80 and (b) the crystallization curves of the synthesized ZSM-5 zeolites with or without adding seeds.','Figure captions',35076,35281,'Fig. 5b');
INSERT INTO "outcomes" VALUES(28152,5752,'crystal_formation',NULL,'the final crystals of ZSM-5 were obtained',NULL,'When the crystallization time reached 2.5 h, the final crystals of ZSM-5 were obtained (figure 4c).','Effect of the silicalite-1 seed on physico-chemical properties of ZSM-5 zeolites',16602,16701,NULL);
INSERT INTO "outcomes" VALUES(28153,5752,'XRD',NULL,'perfect ZSM-5 crystals after 2.5 h, peak intensity hardly changed afterwards',NULL,'Finally, the perfect ZSM-5 crystals were prepared after crystallization for 2.5 h, and the peak intensity hardly changed at all, consistent with above SEM results.','Effect of the silicalite-1 seed on physico-chemical properties of ZSM-5 zeolites',17217,17380,NULL);
INSERT INTO "outcomes" VALUES(28154,5752,'relative_crystallinity',98.0,NULL,'%','Figure 5. (a) XRD patterns of ZSM-5 synthesized with different crystallization times by using 0.8 wt.% S80 and (b) the crystallization curves of the synthesized ZSM-5 zeolites with or without adding seeds.','Figure captions',35076,35281,'Fig. 5b');
INSERT INTO "outcomes" VALUES(28155,5753,'XRD',NULL,'peak intensity hardly changed after 2.5 h (Fig. 5a pattern labelled 4 h)',NULL,'Finally, the perfect ZSM-5 crystals were prepared after crystallization for 2.5 h, and the peak intensity hardly changed at all, consistent with above SEM results.','Effect of the silicalite-1 seed on physico-chemical properties of ZSM-5 zeolites',17217,17380,NULL);
