INSERT INTO "outcomes" VALUES(28157,5754,'morphology_stability',NULL,'size and morphology unchanged when the crystallization time was prolonged',NULL,'The size and morphology of ZSM-5 remained unchanged when the crystallization time was prolonged (figure 4d–f).','Effect of the silicalite-1 seed on physico-chemical properties of ZSM-5 zeolites',16702,16812,NULL);
INSERT INTO "outcomes" VALUES(28158,5754,'relative_crystallinity',99.0,NULL,'%','Figure 5. (a) XRD patterns of ZSM-5 synthesized with different crystallization times by using 0.8 wt.% S80 and (b) the crystallization curves of the synthesized ZSM-5 zeolites with or without adding seeds.','Figure captions',35076,35281,'Fig. 5b');
