INSERT INTO "reagents" VALUES(4121,3953,'horseradish peroxidase',NULL,'template',4.0,'mL','4 mL of a 5 mg/mL aqueous solution','reagent grade','Sigma-Aldrich','HRP, CALB, Cyt c water solution (5 mg/mL, 4 mL)','Synthesis of the enzyme/ZIF-8 composite',5029,5076,'Horseradish peroxidase (HRP) (reagent grade), Candida antarctica lipase (CALB), 2-methylimidazole, phosphate buffer saline (1×), 1,2,3-trihydroxybenzene (THB, ACS reagent), and 4-nitrophenyl butyrate (p-NPB) were purchased from Sigma-Aldrich.');
