INSERT INTO "reagents" VALUES(4271,4085,'R-MBA:Br',NULL,'ligand',200.0,'mg',NULL,NULL,NULL,'a saturated solution of R-,S-MBA:Br in EtOAc was prepared by sonicating 200 mg of R-,S-MBA:Br in 20 mL of EtOAc','Purification and Ligand Treatment of FAPbBr3 NCs',26331,26442,NULL);
