INSERT INTO "reagents" VALUES(4277,4087,'cobalt nitrate hexahydrate','Co(NO3)2·6H2O','precursor',NULL,NULL,NULL,NULL,'Thermo Scientific','The nitrate precursor was formulated by dissolving cobalt nitrate hexahydrate [Co(NO3)2·6H2O, Thermo Scientific] and lithium nitrate [LiNO3, Thermo Scientific] in deionized water, achieving a Li:Co molar ratio of 1.05:1.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',8850,9070,'The nitrate precursor was formulated by dissolving cobalt nitrate hexahydrate [Co(NO3)2·6H2O, Thermo Scientific] and lithium nitrate [LiNO3, Thermo Scientific] in deionized water, achieving a Li:Co molar ratio of 1.05:1.');
INSERT INTO "reagents" VALUES(4278,4087,'lithium nitrate','LiNO3','precursor',NULL,NULL,NULL,NULL,'Thermo Scientific','The nitrate precursor was formulated by dissolving cobalt nitrate hexahydrate [Co(NO3)2·6H2O, Thermo Scientific] and lithium nitrate [LiNO3, Thermo Scientific] in deionized water, achieving a Li:Co molar ratio of 1.05:1.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',8850,9070,'The nitrate precursor was formulated by dissolving cobalt nitrate hexahydrate [Co(NO3)2·6H2O, Thermo Scientific] and lithium nitrate [LiNO3, Thermo Scientific] in deionized water, achieving a Li:Co molar ratio of 1.05:1.');
INSERT INTO "reagents" VALUES(4279,4087,'deionized water','H2O','solvent',NULL,NULL,NULL,NULL,NULL,'The nitrate precursor was formulated by dissolving cobalt nitrate hexahydrate [Co(NO3)2·6H2O, Thermo Scientific] and lithium nitrate [LiNO3, Thermo Scientific] in deionized water, achieving a Li:Co molar ratio of 1.05:1.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',8850,9070,NULL);
INSERT INTO "reagents" VALUES(4280,4087,'nitrogen','N2','gas',NULL,NULL,NULL,'99.998%','BOC','This section operated at an uptake rate of 1 m/min and was coupled with a nitrogen flow rate of 1 L/min (99.998% purity, BOC), with the preheating temperature regulated at 400 °C to ensure thorough vaporization.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9856,10067,'This section operated at an uptake rate of 1 m/min and was coupled with a nitrogen flow rate of 1 L/min (99.998% purity, BOC), with the preheating temperature regulated at 400 °C to ensure thorough vaporization.');
INSERT INTO "reagents" VALUES(4281,4087,'air (quenching)',NULL,'gas',NULL,NULL,NULL,NULL,NULL,'The quenching section, employing an air flow rate of 30 L/min, reduced the temperature of the decomposed particles, which had partially transformed into oxides (discussed further below), to below 150 °C before collecting them in a filter bag.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10636,10878,NULL);
INSERT INTO "reagents" VALUES(4282,4102,'cobalt(II) acetate tetrahydrate','C4H6CoO4·4H2O','precursor',NULL,NULL,NULL,NULL,'Acros Organics','In parallel, the acetate precursor was prepared by dissolving cobalt(II) acetate tetrahydrate [C4H6CoO4·4H2O, Acros Organics] and lithium acetate dihydrate [C2H3LiO2·2H2O, Acros Organics] in deionized water, ensuring the same metal ratios, concentration, and excess lithium were preserved.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9214,9503,'In parallel, the acetate precursor was prepared by dissolving cobalt(II) acetate tetrahydrate [C4H6CoO4·4H2O, Acros Organics] and lithium acetate dihydrate [C2H3LiO2·2H2O, Acros Organics] in deionized water, ensuring the same metal ratios, concentration, and excess lithium were preserved.');
INSERT INTO "reagents" VALUES(4283,4102,'lithium acetate dihydrate','C2H3LiO2·2H2O','precursor',NULL,NULL,NULL,NULL,'Acros Organics','In parallel, the acetate precursor was prepared by dissolving cobalt(II) acetate tetrahydrate [C4H6CoO4·4H2O, Acros Organics] and lithium acetate dihydrate [C2H3LiO2·2H2O, Acros Organics] in deionized water, ensuring the same metal ratios, concentration, and excess lithium were preserved.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9214,9503,'In parallel, the acetate precursor was prepared by dissolving cobalt(II) acetate tetrahydrate [C4H6CoO4·4H2O, Acros Organics] and lithium acetate dihydrate [C2H3LiO2·2H2O, Acros Organics] in deionized water, ensuring the same metal ratios, concentration, and excess lithium were preserved.');
INSERT INTO "reagents" VALUES(4284,4102,'deionized water','H2O','solvent',NULL,NULL,NULL,NULL,NULL,'In parallel, the acetate precursor was prepared by dissolving cobalt(II) acetate tetrahydrate [C4H6CoO4·4H2O, Acros Organics] and lithium acetate dihydrate [C2H3LiO2·2H2O, Acros Organics] in deionized water, ensuring the same metal ratios, concentration, and excess lithium were preserved.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9214,9503,NULL);
INSERT INTO "reagents" VALUES(4285,4102,'nitrogen','N2','gas',NULL,NULL,NULL,'99.998%','BOC','This section operated at an uptake rate of 1 m/min and was coupled with a nitrogen flow rate of 1 L/min (99.998% purity, BOC), with the preheating temperature regulated at 400 °C to ensure thorough vaporization.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9856,10067,'This section operated at an uptake rate of 1 m/min and was coupled with a nitrogen flow rate of 1 L/min (99.998% purity, BOC), with the preheating temperature regulated at 400 °C to ensure thorough vaporization.');
INSERT INTO "reagents" VALUES(4286,4102,'air (quenching)',NULL,'gas',NULL,NULL,NULL,NULL,NULL,'The quenching section, employing an air flow rate of 30 L/min, reduced the temperature of the decomposed particles, which had partially transformed into oxides (discussed further below), to below 150 °C before collecting them in a filter bag.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10636,10878,NULL);
INSERT INTO "reagents" VALUES(4287,4114,'nitrate-derived LiCoO2 (active material; cathodes of N800_A775_0.5h and N800_A775_1h)','LiCoO2','active_material',NULL,NULL,'90 parts by weight (active material:Super-P:PVDF = 90:5:5)',NULL,NULL,'The slurry for nitrate-derived LCO was formulated by combining the active material with carbon black (Super-P) and polyvinylidene fluoride (PVDF) in a weight ratio of 90:5:5.','Coin Cell Assembly and Electrochemical Tests',11483,11657,NULL);
INSERT INTO "reagents" VALUES(4288,4114,'carbon black (Super-P)','C','conductive_additive',NULL,NULL,'5 parts by weight (active material:Super-P:PVDF = 90:5:5)',NULL,NULL,'The slurry for nitrate-derived LCO was formulated by combining the active material with carbon black (Super-P) and polyvinylidene fluoride (PVDF) in a weight ratio of 90:5:5.','Coin Cell Assembly and Electrochemical Tests',11483,11657,NULL);
INSERT INTO "reagents" VALUES(4289,4114,'polyvinylidene fluoride (PVDF)',NULL,'binder',NULL,NULL,'5 parts by weight (active material:Super-P:PVDF = 90:5:5)',NULL,NULL,'The slurry for nitrate-derived LCO was formulated by combining the active material with carbon black (Super-P) and polyvinylidene fluoride (PVDF) in a weight ratio of 90:5:5.','Coin Cell Assembly and Electrochemical Tests',11483,11657,NULL);
INSERT INTO "reagents" VALUES(4290,4114,'N-methyl-2-pyrrolidone (NMP)',NULL,'solvent',NULL,NULL,NULL,NULL,NULL,'PVDF was dissolved in N-methyl-2-pyrrolidone (NMP) to fine-tune the slurry’s viscosity, ensuring optimal electrode coating quality.','Coin Cell Assembly and Electrochemical Tests',11658,11789,NULL);
INSERT INTO "reagents" VALUES(4291,4114,'aluminum foil','Al','substrate',NULL,NULL,NULL,NULL,NULL,'cast onto aluminum foil using a linear coater set to a 150 μm gap','Coin Cell Assembly and Electrochemical Tests',11845,11910,NULL);
INSERT INTO "reagents" VALUES(4292,4114,'lithium metal disc (counter electrode)','Li','counter_electrode',NULL,NULL,'15 mm disc',NULL,NULL,'CR2032 coin cells were assembled in an argon-filled glovebox, each containing a 15 mm Li metal disc counter electrode, a 19 mm diameter Celgard separator, and filled with 20 μL of LP40 electrolyte (1 M LiPF6 in EC/DEC, 1:1 v/v).','Coin Cell Assembly and Electrochemical Tests',12048,12276,NULL);
INSERT INTO "reagents" VALUES(4293,4114,'Celgard separator',NULL,'separator',NULL,NULL,'19 mm diameter',NULL,NULL,'CR2032 coin cells were assembled in an argon-filled glovebox, each containing a 15 mm Li metal disc counter electrode, a 19 mm diameter Celgard separator, and filled with 20 μL of LP40 electrolyte (1 M LiPF6 in EC/DEC, 1:1 v/v).','Coin Cell Assembly and Electrochemical Tests',12048,12276,NULL);
INSERT INTO "reagents" VALUES(4294,4114,'LP40 electrolyte (1 M LiPF6 in EC/DEC, 1:1 v/v)',NULL,'electrolyte',20.0,'μL',NULL,NULL,NULL,'CR2032 coin cells were assembled in an argon-filled glovebox, each containing a 15 mm Li metal disc counter electrode, a 19 mm diameter Celgard separator, and filled with 20 μL of LP40 electrolyte (1 M LiPF6 in EC/DEC, 1:1 v/v).','Coin Cell Assembly and Electrochemical Tests',12048,12276,NULL);
INSERT INTO "reagents" VALUES(4295,4114,'argon','Ar','gas',NULL,NULL,NULL,NULL,NULL,'CR2032 coin cells were assembled in an argon-filled glovebox','Coin Cell Assembly and Electrochemical Tests',12048,12108,NULL);
INSERT INTO "reagents" VALUES(4296,4115,'acetate-derived LiCoO2 (active material; cathodes of A900_A750_3h and A900_A750_15h)','LiCoO2','active_material',NULL,NULL,'80 parts by weight (LCO:Super P:PVDF = 80:10:10)',NULL,NULL,'Adjusting for the acetate-derived LCO’s porous aggregated structure, the electrode composition was optimized to an 80:10:10 ratio of LCO to Super P to PVDF.','Coin Cell Assembly and Electrochemical Tests',12510,12666,NULL);
INSERT INTO "reagents" VALUES(4297,4115,'carbon black (Super P)','C','conductive_additive',NULL,NULL,'10 parts by weight (LCO:Super P:PVDF = 80:10:10)',NULL,NULL,'Adjusting for the acetate-derived LCO’s porous aggregated structure, the electrode composition was optimized to an 80:10:10 ratio of LCO to Super P to PVDF.','Coin Cell Assembly and Electrochemical Tests',12510,12666,NULL);
INSERT INTO "reagents" VALUES(4298,4115,'polyvinylidene fluoride (PVDF)',NULL,'binder',NULL,NULL,'10 parts by weight (LCO:Super P:PVDF = 80:10:10)',NULL,NULL,'Adjusting for the acetate-derived LCO’s porous aggregated structure, the electrode composition was optimized to an 80:10:10 ratio of LCO to Super P to PVDF.','Coin Cell Assembly and Electrochemical Tests',12510,12666,NULL);
INSERT INTO "reagents" VALUES(4299,4115,'lithium metal (counter electrode)','Li','counter_electrode',NULL,NULL,NULL,NULL,NULL,'We assessed the effectiveness of the selected annealing conditions in synthesizing LCO particles for battery cathodes through electrochemical tests using half-cells with a Li-metal counter electrode.','Electrochemical Performance',36039,36238,NULL);
INSERT INTO "reagents" VALUES(4300,4115,'Celgard separator',NULL,'separator',NULL,NULL,'18 mm',NULL,NULL,'The processed electrodes were punched into 14 mm discs and assembled into 2032-type coin cells, incorporating an 18 mm Celgard separator and 80 μL of 1.3 M LiPF6 electrolyte in EC:DEC (3:7 wt/wt), tailored for the electrode’s specific needs.','Coin Cell Assembly and Electrochemical Tests',12813,13054,NULL);
INSERT INTO "reagents" VALUES(4301,4115,'1.3 M LiPF6 electrolyte in EC:DEC (3:7 wt/wt)',NULL,'electrolyte',80.0,'μL',NULL,NULL,NULL,'The processed electrodes were punched into 14 mm discs and assembled into 2032-type coin cells, incorporating an 18 mm Celgard separator and 80 μL of 1.3 M LiPF6 electrolyte in EC:DEC (3:7 wt/wt), tailored for the electrode’s specific needs.','Coin Cell Assembly and Electrochemical Tests',12813,13054,NULL);
INSERT INTO "reagents" VALUES(4302,4116,'3-aminopropyltriethoxysilane (APTES)',NULL,'precursor',8.85,'g',NULL,'analytical grade','Shanghai Aladdin Biochemical Reagents','8.85 g (39.98 mmoL) of APTES, 4.88 g (39.96 mmoL) of salicylaldehyde, and 100 mL of ethanol were added to a flask and reacted at 95 °C for 3 h','2.2.1. Preparation of Salicylaldimine',8251,8393,'Cetyl trimethyl ammonium bromide (CTAB), tetraethyl orthosilicate (TEOS), 3-Aminopropyltriethyloxy silane (APTES), and salicylaldehyde were all obtained from Shanghai Aladdin Biochemical Reagents (Shanghai, China). Ethanol, dichloromethane, anhydrous magnesium sulfate, ammonia solution (wt = 25%), zinc nitrate, and methyl orange (MO) were obtained from Tianjin Damao Chemical Reagents (Tianjin, China). All chemicals were analytical grade and used as received without any further purification.');
INSERT INTO "reagents" VALUES(4303,4116,'salicylaldehyde',NULL,'precursor',4.88,'g',NULL,'analytical grade','Shanghai Aladdin Biochemical Reagents','8.85 g (39.98 mmoL) of APTES, 4.88 g (39.96 mmoL) of salicylaldehyde, and 100 mL of ethanol were added to a flask and reacted at 95 °C for 3 h','2.2.1. Preparation of Salicylaldimine',8251,8393,'Cetyl trimethyl ammonium bromide (CTAB), tetraethyl orthosilicate (TEOS), 3-Aminopropyltriethyloxy silane (APTES), and salicylaldehyde were all obtained from Shanghai Aladdin Biochemical Reagents (Shanghai, China). Ethanol, dichloromethane, anhydrous magnesium sulfate, ammonia solution (wt = 25%), zinc nitrate, and methyl orange (MO) were obtained from Tianjin Damao Chemical Reagents (Tianjin, China). All chemicals were analytical grade and used as received without any further purification.');
INSERT INTO "reagents" VALUES(4304,4116,'ethanol (salicylaldimine synthesis)',NULL,'solvent',100.0,'mL',NULL,'analytical grade','Tianjin Damao Chemical Reagents','8.85 g (39.98 mmoL) of APTES, 4.88 g (39.96 mmoL) of salicylaldehyde, and 100 mL of ethanol were added to a flask and reacted at 95 °C for 3 h','2.2.1. Preparation of Salicylaldimine',8251,8393,'Cetyl trimethyl ammonium bromide (CTAB), tetraethyl orthosilicate (TEOS), 3-Aminopropyltriethyloxy silane (APTES), and salicylaldehyde were all obtained from Shanghai Aladdin Biochemical Reagents (Shanghai, China). Ethanol, dichloromethane, anhydrous magnesium sulfate, ammonia solution (wt = 25%), zinc nitrate, and methyl orange (MO) were obtained from Tianjin Damao Chemical Reagents (Tianjin, China). All chemicals were analytical grade and used as received without any further purification.');
