INSERT INTO "reagents" VALUES(4511,4223,'gelatin (type B)',NULL,'capping_agent',2.0,'g',NULL,'analytical grade','Sigma-Aldrich','2.0 g of gelatin was added to 190 mL of H2O in a flask, and the solution was stirred to obtain a clear solution.','Synthesis of gelatin-reduced Ag-NPs',5003,5115,'Chemicals were analytical grade and used as received without further purification. AgNO3 (99.98%, Merck KGaA, Darmstadt, Germany), gelatin (type B, Sigma-Aldrich, St Louis, MO, USA), and glucose (BDH Chemical Ltd, Poole, England) were used as silver precursor, capping agent, and reducing agent, respectively.');
