INSERT INTO "reagents" VALUES(4538,4251,'zinc acetate dihydrate',NULL,'precursor',5.0,'g',NULL,'analytical grade','Sigma-Aldrich','5 g of zinc acetate dihydrate was dissolved in 20 mL of water','Preparation of rare earth metal (RE)-doped ZnO',7449,7510,'Zinc acetate dihydrate and rare earth metal nitrates were purchased from Sigma-Aldrich. The water used in all experiments was double distilled. Methylene Blue (MB) and Rhodamine B (RhB) were selected as model organic pollutants. The different scavengers such as disodium ethylenediaminetetraacetate (EDTA-2Na), 1,4-benzoquinone (BQ) and isopropyl alcohol (IPA) used in this study were purchased from Alfa-Aesar. Nitric acid and sodium hydroxide were obtained from S.D. fine chemicals. Commercial ZnO was purchased from Merck-India. All the chemical used in this study were of analytical grade and were used without any further purification.');
INSERT INTO "reagents" VALUES(4539,4251,'water','H2O','solvent',20.0,'mL',NULL,'double distilled',NULL,'5 g of zinc acetate dihydrate was dissolved in 20 mL of water','Preparation of rare earth metal (RE)-doped ZnO',7449,7510,'The water used in all experiments was double distilled.');
INSERT INTO "reagents" VALUES(4540,4251,'sodium hydroxide aqueous solution','NaOH','base',NULL,NULL,'1 M aqueous NaOH solution','analytical grade','S.D. fine chemicals','a freshly prepared 1 M aqueous NaOH solution was added dropwise to maintain the pH 11','Preparation of rare earth metal (RE)-doped ZnO',7724,7809,'Nitric acid and sodium hydroxide were obtained from S.D. fine chemicals. Commercial ZnO was purchased from Merck-India. All the chemical used in this study were of analytical grade and were used without any further purification.');
INSERT INTO "reagents" VALUES(4541,4251,'water','H2O','wash',NULL,NULL,NULL,NULL,NULL,'The obtained product was filtered and washed several times with water followed by ethanol to remove the impurities.','Preparation of rare earth metal (RE)-doped ZnO',7897,8012,NULL);
