INSERT INTO "reagents" VALUES(4549,4256,'ultrapure water (washing of the HNO3-treated CNTs)','H2O','wash',NULL,NULL,NULL,NULL,NULL,'the HNO3-treated CNTs were recovered and washed with ultrapure water until the pH of the CNT solution neared neutral','Functionalization of carbon nanotubes',9872,9988,NULL);
