INSERT INTO "reagents" VALUES(4552,4257,'copper(II) sulfate pentahydrate solution','CuSO4·5H2O','precursor',50.0,'mL',NULL,NULL,'Sigma-Aldrich','the resulting homogeneous dispersion of the CNTs was mixed with 50 mL of CuSO4.5H2O solution under constant stirring','Synthesis of CuO-CNT nanocomposite',10369,10485,'Nitric acid (HNO3, 70%), copper (II) sulfate pentahydrate (CuSO4.5H2O), hexamethylenetetramine (HMTA, C6H12N4), zinc nitrate hexahydrate (Zn(NO3)2⋅6H2O), thioacetamide (CH3CSNH2), cetyltrimethylammonium bromide (CTAB, CH3(CH2)15 N(Br)(CH3)3), absolute ethanol (CH3CH2OH), hydrochloric acid solution (HCl, 37%), and sodium hydroxide (NaOH, pellets) were all purchased from Sigma-Aldrich without any impurities.');
