INSERT INTO "reagents" VALUES(4573,4300,'zinc nitrate hexahydrate','Zn(NO3)2·6H2O','precursor',5.9,'g',NULL,'98%','Acros Organics B.V.B.A. Chemicals Co.','Subsequently, mixture-I was hard sonicated (2 L Digital Ultrasonic Cleaner Cavitek Professional, 100 W) for 2 h (as shown in Figure 1) before the addition of 20 mL metal solution (5.9 g of zinc nitrate hexahydrate in 400 mL DI water).','Synthesis Procedures',10422,10656,'2-methylimidazole (2-mim) (C4H6N2; 99%) and zinc nitrate hexahydrate [Zn(NO3)2·6H2O; 98%] were purchased from Acros Organics B.V.B.A. Chemicals Co.');
INSERT INTO "reagents" VALUES(4574,4300,'deionized water (metal solution)','H2O','solvent',400.0,'mL',NULL,NULL,NULL,'Subsequently, mixture-I was hard sonicated (2 L Digital Ultrasonic Cleaner Cavitek Professional, 100 W) for 2 h (as shown in Figure 1) before the addition of 20 mL metal solution (5.9 g of zinc nitrate hexahydrate in 400 mL DI water).','Synthesis Procedures',10422,10656,NULL);
INSERT INTO "reagents" VALUES(4575,4300,'n-hexane','C6H14','template',4.0,'mL',NULL,'95%','Alfa Aesar','In this part, a fixed concentration of n-hexane (4 mL equivalent to 9 v/v %) was used, while the amount of the HFS surfactant was varied to study their effects on hollow ZIF-8 formation.','Effect of the Amount of HFS Surfactant',38247,38433,'1H,1H,2H,2H-Perfluorodecyltriethoxysilane (HFS) (C16H19F17O3Si; 97%), n-hexane (n-C6H14; 95%), herein referred to as “surfactant” and “oil/solvent” respectively, c-hexane (c-C6H12; 99.8%), and n-dodecane (n-C12H26; 99%) were provided by Alfa Aesar.');
INSERT INTO "reagents" VALUES(4576,4300,'HFS','C16H19F17O3Si','surfactant',0.3,'g',NULL,'97%','Alfa Aesar','only at the S/O ratio of 0.075 g mL–1 (0.3 g of HFS and 4 mL of n-hexane)','Effect of the Amount of HFS Surfactant',38668,38741,'1H,1H,2H,2H-Perfluorodecyltriethoxysilane (HFS) (C16H19F17O3Si; 97%), n-hexane (n-C6H14; 95%), herein referred to as “surfactant” and “oil/solvent” respectively, c-hexane (c-C6H12; 99.8%), and n-dodecane (n-C12H26; 99%) were provided by Alfa Aesar.');
INSERT INTO "reagents" VALUES(4577,4300,'methanol','CH3OH','wash',NULL,NULL,NULL,'>99.8%','Fisher Scientific UK Ltd','After the synthesis, the resultant mixture was centrifuged (Thermo Scientific IEC CL40) at 6000–6500 rpm and repeatedly washed using methanol.','Synthesis Procedures',10906,11048,'Methanol (CH3OH; >99.8%), and ethanol (C2H5OH; >99.8%) was supplied by Fisher Scientific UK Ltd and used as received without further purification.');
INSERT INTO "reagents" VALUES(4578,4308,'ethanol','C2H5OH','template',9.0,'v/v %',NULL,'>99.8%','Fisher Scientific UK Ltd','Under similar hollow ZIF-8 synthesis conditions, ethanol (9 v/v%) as a co-solvent resulted in the formation of ZIF-L/ZIF-8 mixed-phase','Supporting Information — am3c06502_si_001.pdf',70299,70433,'Methanol (CH3OH; >99.8%), and ethanol (C2H5OH; >99.8%) was supplied by Fisher Scientific UK Ltd and used as received without further purification.');
INSERT INTO "reagents" VALUES(4579,4309,'n-dodecane','C12H26','template',4.0,'mL',NULL,'99%','Alfa Aesar','the addition of 9 v/v% (4 mL) of n-dodecane resulted in the formation of a jelly-like substance with no solid crystal formation','Supporting Information — am3c06502_si_001.pdf',71739,71866,'1H,1H,2H,2H-Perfluorodecyltriethoxysilane (HFS) (C16H19F17O3Si; 97%), n-hexane (n-C6H14; 95%), herein referred to as “surfactant” and “oil/solvent” respectively, c-hexane (c-C6H12; 99.8%), and n-dodecane (n-C12H26; 99%) were provided by Alfa Aesar.');
INSERT INTO "reagents" VALUES(4580,4310,'c-hexane','C6H12','template',NULL,NULL,NULL,'99.8%','Alfa Aesar','Interestingly, unlike ethanol and n-dodecane, the use of c-hexane as a co-solvent resulted in the formation of a pure ZIF-8 phase','Supporting Information — am3c06502_si_001.pdf',72244,72373,'1H,1H,2H,2H-Perfluorodecyltriethoxysilane (HFS) (C16H19F17O3Si; 97%), n-hexane (n-C6H14; 95%), herein referred to as “surfactant” and “oil/solvent” respectively, c-hexane (c-C6H12; 99.8%), and n-dodecane (n-C12H26; 99%) were provided by Alfa Aesar.');
