INSERT INTO "reagents" VALUES(4761,4545,'zinc chloride','ZnCl2','precursor',10.0,'mmol',NULL,'99%','Sinopharm Chemical Reagent Co. Ltd.','Firstly, 10 mmol ZnCl2 was dispersed in 100 mL methanol and kept stirring vigorously for 30 min until it was dissolved absolutely.','Synthesis of Ag/AgCl@ZIF-8 hybrid photocatalysts',6613,6743,'Silver nitrate (AgNO3, 99%), zinc chloride (ZnCl2, 99%), 2-methylimidazole (C4H6N2, 99%), rhodamine B (RhB, 99%) and methanol (CH3OH, 99%) were all analytical reagents and purchased from Sinopharm Chemical Reagent Co. Ltd.');
INSERT INTO "reagents" VALUES(4762,4545,'methanol (dispersion of ZnCl2)','CH3OH','solvent',100.0,'mL',NULL,'99%','Sinopharm Chemical Reagent Co. Ltd.','Firstly, 10 mmol ZnCl2 was dispersed in 100 mL methanol and kept stirring vigorously for 30 min until it was dissolved absolutely.','Synthesis of Ag/AgCl@ZIF-8 hybrid photocatalysts',6613,6743,'Silver nitrate (AgNO3, 99%), zinc chloride (ZnCl2, 99%), 2-methylimidazole (C4H6N2, 99%), rhodamine B (RhB, 99%) and methanol (CH3OH, 99%) were all analytical reagents and purchased from Sinopharm Chemical Reagent Co. Ltd.');
INSERT INTO "reagents" VALUES(4763,4545,'2-methylimidazole','C4H6N2','ligand',80.0,'mmol',NULL,'99%','Sinopharm Chemical Reagent Co. Ltd.','Then, 100 mL methanol, containing 80 mmol 2-methylimidazole, was added dropwise into the above solution and intensively stirred for 30 min to form a homogeneous milky suspension.','Synthesis of Ag/AgCl@ZIF-8 hybrid photocatalysts',6744,6922,'Silver nitrate (AgNO3, 99%), zinc chloride (ZnCl2, 99%), 2-methylimidazole (C4H6N2, 99%), rhodamine B (RhB, 99%) and methanol (CH3OH, 99%) were all analytical reagents and purchased from Sinopharm Chemical Reagent Co. Ltd.');
INSERT INTO "reagents" VALUES(4764,4545,'methanol (solution of 2-methylimidazole)','CH3OH','solvent',100.0,'mL',NULL,'99%','Sinopharm Chemical Reagent Co. Ltd.','Then, 100 mL methanol, containing 80 mmol 2-methylimidazole, was added dropwise into the above solution and intensively stirred for 30 min to form a homogeneous milky suspension.','Synthesis of Ag/AgCl@ZIF-8 hybrid photocatalysts',6744,6922,'Silver nitrate (AgNO3, 99%), zinc chloride (ZnCl2, 99%), 2-methylimidazole (C4H6N2, 99%), rhodamine B (RhB, 99%) and methanol (CH3OH, 99%) were all analytical reagents and purchased from Sinopharm Chemical Reagent Co. Ltd.');
INSERT INTO "reagents" VALUES(4765,4545,'silver nitrate','AgNO3','precursor',5.0,'mmol',NULL,'99%','Sinopharm Chemical Reagent Co. Ltd.','With 5 mmol AgNO3, ZIF-8 also exhibits well-defined truncated rhombic dodecahedral crystals and its particle size decreases to 550 nm (Fig. 2b).','Results and discussion',11521,11665,'Silver nitrate (AgNO3, 99%), zinc chloride (ZnCl2, 99%), 2-methylimidazole (C4H6N2, 99%), rhodamine B (RhB, 99%) and methanol (CH3OH, 99%) were all analytical reagents and purchased from Sinopharm Chemical Reagent Co. Ltd.');
INSERT INTO "reagents" VALUES(4766,4545,'methanol (solution of AgNO3)','CH3OH','solvent',40.0,'mL',NULL,'99%','Sinopharm Chemical Reagent Co. Ltd.','Then, 40 mL of methanol, containing 3 mL of H2O and X mmol of AgNO3 (X is 5, 10, 15 and 20, respectively), was injected slowly into the above milky solution and kept stirring for 24 h under dark conditions.','Synthesis of Ag/AgCl@ZIF-8 hybrid photocatalysts',6923,7129,'Silver nitrate (AgNO3, 99%), zinc chloride (ZnCl2, 99%), 2-methylimidazole (C4H6N2, 99%), rhodamine B (RhB, 99%) and methanol (CH3OH, 99%) were all analytical reagents and purchased from Sinopharm Chemical Reagent Co. Ltd.');
INSERT INTO "reagents" VALUES(4767,4545,'water (in the AgNO3 solution)','H2O','solvent',3.0,'mL',NULL,NULL,NULL,'Then, 40 mL of methanol, containing 3 mL of H2O and X mmol of AgNO3 (X is 5, 10, 15 and 20, respectively), was injected slowly into the above milky solution and kept stirring for 24 h under dark conditions.','Synthesis of Ag/AgCl@ZIF-8 hybrid photocatalysts',6923,7129,NULL);
INSERT INTO "reagents" VALUES(4768,4545,'ethanol','C2H5OH','wash',NULL,NULL,NULL,NULL,NULL,'After that, it was centrifuged and washed with ethanol and distilled water to obtain the AgCl(x)@ZIF-8 composites.','Synthesis of Ag/AgCl@ZIF-8 hybrid photocatalysts',7130,7244,NULL);
INSERT INTO "reagents" VALUES(4769,4545,'distilled water (washing)','H2O','wash',NULL,NULL,NULL,NULL,NULL,'After that, it was centrifuged and washed with ethanol and distilled water to obtain the AgCl(x)@ZIF-8 composites.','Synthesis of Ag/AgCl@ZIF-8 hybrid photocatalysts',7130,7244,NULL);
INSERT INTO "reagents" VALUES(4770,4545,'distilled water (photoreduction)','H2O','solvent',100.0,'mL',NULL,NULL,NULL,'Finally, 1 g of the AgCl(x)@ZIF-8 composites was dispersed in 100 mL of distilled water and kept stirring vigorously for 30 min under UV light (λ ≤ 400 nm, from a 500 W mercury lamp) to prepare Ag/AgCl(x)@ZIF-8 hybrid photocatalysts.','Synthesis of Ag/AgCl@ZIF-8 hybrid photocatalysts',7245,7478,NULL);
