INSERT INTO "reagents" VALUES(5669,5405,'terephthalic acid (benzene-1,4-dicarboxylic acid)','C6H4(CO2H)2','ligand',70.0,'mg',NULL,'99%','Merck Company, Germany','Ce-MOF was synthesized at RT by adding 70 mg terephthalic acid as ligand to 50 mL DI under stirring.','Room temperature synthesis',9664,9764,'Cerium nitrate (Ce(NO3)3.6H2O, 99%), benzene-1, 4-dicarboxylate (terephthalic acid/C6H4(CO2H)2,99%), ethanol absolute (CH3CH2OH, 99.9%), hydrochloride acid (HCl,37%), sodium carbonate (Na₂CO₃,99%), ammonia (NH3,25%), Ethylenedinitrilotetraacetic acid disodium salt dihydrate (EDTA, 99%), benzoquinone (BQ, 99%), and isopropanol (IPA, 99%) were purchased from Merck Company, Germany.');
