INSERT INTO "reagents" VALUES(5671,5405,'ammonia solution','NH3','base',NULL,NULL,NULL,'46 wt.%','Merck Company, Germany','Ammonia solution (46 wt.%) was then gradually added to the solution to increase pH to 7.','Room temperature synthesis',9765,9853,'Cerium nitrate (Ce(NO3)3.6H2O, 99%), benzene-1, 4-dicarboxylate (terephthalic acid/C6H4(CO2H)2,99%), ethanol absolute (CH3CH2OH, 99.9%), hydrochloride acid (HCl,37%), sodium carbonate (Na₂CO₃,99%), ammonia (NH3,25%), Ethylenedinitrilotetraacetic acid disodium salt dihydrate (EDTA, 99%), benzoquinone (BQ, 99%), and isopropanol (IPA, 99%) were purchased from Merck Company, Germany.');
