INSERT INTO "reagents" VALUES(5685,5423,'N,N-dimethylformamide','C3H7NO','solvent',NULL,NULL,NULL,'reagent grade','VWR','Initially, the ratio of precursor chemicals was 1:1.1:0.8:9.5 for PbBr2:MABr:AdNH2:HeA and as a coordinating solvent N,N-dimethylformamide (DMF) was selected.','Nanoparticle synthesis',31246,31404,'N,N-dimethylformamide (DMF), xylene (a mixture of isomers), acetone, diethylether, cyclohexane, chlorobenzene, chloroform and toluene were of reagent grade, n-hexane and acetonitrile (ACN) were of HPLC grade, all provided from VWR.');
INSERT INTO "reagents" VALUES(5686,5423,'toluene','C7H8','antisolvent',10.0,'mL',NULL,'reagent grade','VWR','The precipitation of 20 μl of the precursor solution was performed in 10 mL of toluene (precursor solution and toluene were in a volume ratio of 0.002) which acted as a non-coordinating non-polar solvent under cold conditions (ice bath at 3–4 °C), while being stirred.','Nanoparticle synthesis',31661,31929,'N,N-dimethylformamide (DMF), xylene (a mixture of isomers), acetone, diethylether, cyclohexane, chlorobenzene, chloroform and toluene were of reagent grade, n-hexane and acetonitrile (ACN) were of HPLC grade, all provided from VWR.');
