INSERT INTO "reagents" VALUES(5704,5472,'glass substrate',NULL,'substrate',NULL,NULL,NULL,NULL,NULL,'A glass substrate (1 × 1 cm) was placed on the bottom of the tube and the sample was centrifuged (at 5000 rpm for 10 min).','General methods',34741,34863,NULL);
INSERT INTO "reagents" VALUES(5710,5479,'sucrose','C12H22O11','carbon_source',2.0,'mmol',NULL,'AR, 99.0%',NULL,'Initially, 2 mmol of sucrose (C12H22O11, AR, 99.0%), and 15 mmol of lithium dihydrogen phosphate (LiH2PO4, ACS, 98.0%, Aladdin) were dissolved 10 ml of deionized water under continuous stirring.','Synthesis procedure',5338,5532,NULL);
INSERT INTO "reagents" VALUES(5711,5479,'lithium dihydrogen phosphate','LiH2PO4','precursor',15.0,'mmol',NULL,'ACS, 98.0%','Aladdin','Initially, 2 mmol of sucrose (C12H22O11, AR, 99.0%), and 15 mmol of lithium dihydrogen phosphate (LiH2PO4, ACS, 98.0%, Aladdin) were dissolved 10 ml of deionized water under continuous stirring.','Synthesis procedure',5338,5532,NULL);
INSERT INTO "reagents" VALUES(5712,5479,'deionized water','H2O','solvent',10.0,'mL',NULL,NULL,NULL,'Initially, 2 mmol of sucrose (C12H22O11, AR, 99.0%), and 15 mmol of lithium dihydrogen phosphate (LiH2PO4, ACS, 98.0%, Aladdin) were dissolved 10 ml of deionized water under continuous stirring.','Synthesis procedure',5338,5532,NULL);
INSERT INTO "reagents" VALUES(5713,5479,'manganese oxide','MnO','precursor',12.0,'mmol',NULL,'AR, 99.0%','Aladdin','Then 12 mmol of manganese oxide (MnO, Aladdin, AR, 99.0%) and 3 mmol of iron salt were gradually added to the previously mentioned solution while stirring vigorously, followed by ball milling for 5 h to form a uniform slurry.','Synthesis procedure',5533,5758,NULL);
INSERT INTO "reagents" VALUES(5714,5479,'iron nitrate','Fe(NO3)3·9H2O','precursor',3.0,'mmol',NULL,NULL,NULL,'Then 12 mmol of manganese oxide (MnO, Aladdin, AR, 99.0%) and 3 mmol of iron salt were gradually added to the previously mentioned solution while stirring vigorously, followed by ball milling for 5 h to form a uniform slurry.','Synthesis procedure',5533,5758,NULL);
INSERT INTO "reagents" VALUES(5715,5479,'argon','Ar','gas',NULL,NULL,NULL,NULL,NULL,'Finally, the dried slurry was sintered at 700 °C for 10 h under an Ar atmosphere to yield a black LiMn0.8Fe0.2PO4/C powder, denoted as N-LMFP.','Synthesis procedure',5856,5998,NULL);
INSERT INTO "reagents" VALUES(5716,5480,'iron oxalate','FeC2O4','precursor',NULL,NULL,NULL,NULL,NULL,'To determine the influence of the iron sources on the LiMnPO4/C composites, the Fe-substituted LiMnPO4/C materials were prepared using FeC2O4 and Fe2O3 as Fe sources using the same synthetic route, denoted as C-LMFP and O-LMFP, respectively.','Synthesis procedure',5999,6240,NULL);
INSERT INTO "reagents" VALUES(5717,5481,'iron(III) oxide','Fe2O3','precursor',NULL,NULL,NULL,NULL,NULL,'To determine the influence of the iron sources on the LiMnPO4/C composites, the Fe-substituted LiMnPO4/C materials were prepared using FeC2O4 and Fe2O3 as Fe sources using the same synthetic route, denoted as C-LMFP and O-LMFP, respectively.','Synthesis procedure',5999,6240,NULL);
INSERT INTO "reagents" VALUES(5718,5483,'N-LMFP (and C-LMFP, O-LMFP, LMP/C) LMFP/C active material',NULL,'intermediate',80.0,'wt%',NULL,NULL,NULL,'The cathode electrode consisted of 80 wt% of LMFP/C active material, 10 wt% of poly(propylene fluoride) and 10 wt% of acetylene black.','Electrochemical measurements',7544,7678,NULL);
INSERT INTO "reagents" VALUES(5719,5483,'poly(propylene fluoride)',NULL,'binder',10.0,'wt%',NULL,NULL,NULL,'The cathode electrode consisted of 80 wt% of LMFP/C active material, 10 wt% of poly(propylene fluoride) and 10 wt% of acetylene black.','Electrochemical measurements',7544,7678,NULL);
INSERT INTO "reagents" VALUES(5720,5483,'acetylene black',NULL,'conductive_additive',10.0,'wt%',NULL,NULL,NULL,'The cathode electrode consisted of 80 wt% of LMFP/C active material, 10 wt% of poly(propylene fluoride) and 10 wt% of acetylene black.','Electrochemical measurements',7544,7678,NULL);
INSERT INTO "reagents" VALUES(5721,5483,'Celgard 2502 membrane',NULL,'separator',NULL,NULL,NULL,NULL,NULL,'A Celgard 2502 membrane was used as a separator, lithium metal was used as the anode, and a 1 M LiPF6 solution (ethylene carbonate (EC) + diethyl carbonate (DEC) + dimethyl carbonate (DMC), 1 : 1 : 1 v/v) as the electrolyte.','Electrochemical measurements',7913,8137,NULL);
