INSERT INTO "reagents" VALUES(5723,5483,'LiPF6 solution in EC + DEC + DMC (1 : 1 : 1 v/v)','LiPF6','electrolyte',1.0,'M',NULL,NULL,NULL,'A Celgard 2502 membrane was used as a separator, lithium metal was used as the anode, and a 1 M LiPF6 solution (ethylene carbonate (EC) + diethyl carbonate (DEC) + dimethyl carbonate (DMC), 1 : 1 : 1 v/v) as the electrolyte.','Electrochemical measurements',7913,8137,NULL);
INSERT INTO "reagents" VALUES(5724,5483,'dimethyl carbonate','C3H6O3','wash',NULL,NULL,NULL,NULL,NULL,'The cells after the charge/discharge cycle were disassembled in the glove box, and the electrodes were taken out, and then washed with DMC and dried.','Electrochemical measurements',8581,8730,NULL);
