INSERT INTO "reagents" VALUES(5755,5501,'gallic acid','C7H6O5','ligand',2.5,'mmol',NULL,'≥ 97.5%','Sigma-Aldrich','2.5 mmol (0.425 g) of GA was dissolved in 5 mL NaOH solution at certain molar concentration (Table 4).','Synthesis of CuGA MOF',21272,21374,'Copper (II) chloride dihydrate (CuCl2.2H2O, CAS 10125-13-0, ≥ 99% purity) and gallic acid (C7H6O5, CAS 149-91-7, ≥ 97.5% purity) were obtained from Sigma-Aldrich (St Louis, MO).');
