INSERT INTO "reagents" VALUES(5757,5501,'copper(II) chloride dihydrate','CuCl2·2H2O','precursor',2.5,'mmol',NULL,'≥ 99%','Sigma-Aldrich','Into the GA solution, 2.5 mmol (0.426 g) CuCl2.2H2O solution in 5 ml DI water was added dropwise.','Synthesis of CuGA MOF',21375,21472,'Copper (II) chloride dihydrate (CuCl2.2H2O, CAS 10125-13-0, ≥ 99% purity) and gallic acid (C7H6O5, CAS 149-91-7, ≥ 97.5% purity) were obtained from Sigma-Aldrich (St Louis, MO).');
INSERT INTO "reagents" VALUES(5758,5501,'deionized water (copper chloride solution)','H2O','solvent',5.0,'mL',NULL,NULL,NULL,'Into the GA solution, 2.5 mmol (0.426 g) CuCl2.2H2O solution in 5 ml DI water was added dropwise.','Synthesis of CuGA MOF',21375,21472,NULL);
