INSERT INTO "reagents" VALUES(5768,5510,'cobalt nitrate hexahydrate','Co(NO3)2·6H2O','precursor',NULL,NULL,NULL,'99%','Sigma-Aldrich','A mixture of cobalt nitrate and iron(III) nitrate with different molar ratios (0.25:0.75, 0.50:0.50, and 0.75:0.25) was mixed with terephthalic acid and dissolved in DMF (40 mL) under continuous stirring for 1 h.','Synthesis of (Cox–Fe1–x–MOF)',6534,6746,'Ferric nitrate pentahydrate [Fe (NO3)3·9H2O, 99%] and cobalt nitrate hexahydrate [Co (NO3)2·6H2O, 99% %] were obtained from Sigma-Aldrich.');
INSERT INTO "reagents" VALUES(5769,5510,'iron(III) nitrate (ferric nitrate)','Fe(NO3)3·9H2O','precursor',NULL,NULL,NULL,'99%','Sigma-Aldrich','A mixture of cobalt nitrate and iron(III) nitrate with different molar ratios (0.25:0.75, 0.50:0.50, and 0.75:0.25) was mixed with terephthalic acid and dissolved in DMF (40 mL) under continuous stirring for 1 h.','Synthesis of (Cox–Fe1–x–MOF)',6534,6746,'Ferric nitrate pentahydrate [Fe (NO3)3·9H2O, 99%] and cobalt nitrate hexahydrate [Co (NO3)2·6H2O, 99% %] were obtained from Sigma-Aldrich.');
INSERT INTO "reagents" VALUES(5770,5510,'terephthalic acid (1,4-BDC)','C8H6O4','ligand',NULL,NULL,NULL,'99%','Sigma-Aldrich','A mixture of cobalt nitrate and iron(III) nitrate with different molar ratios (0.25:0.75, 0.50:0.50, and 0.75:0.25) was mixed with terephthalic acid and dissolved in DMF (40 mL) under continuous stirring for 1 h.','Synthesis of (Cox–Fe1–x–MOF)',6534,6746,'Terephthalic acid (1,4-BDC, 99%) was supplied from Sigma-Aldrich.');
INSERT INTO "reagents" VALUES(5771,5510,'N,N-dimethylformamide (DMF)','C3H7NO','solvent',40.0,'mL',NULL,'99.5%','Sigma-Aldrich','A mixture of cobalt nitrate and iron(III) nitrate with different molar ratios (0.25:0.75, 0.50:0.50, and 0.75:0.25) was mixed with terephthalic acid and dissolved in DMF (40 mL) under continuous stirring for 1 h.','Synthesis of (Cox–Fe1–x–MOF)',6534,6746,'N,N-Dimethylformamide (DMF, 99.5%), ethanol (99.5%), N-butylamine, acetonitrile, lead nitrate, cadmium chloride, β-naphthol benzaldehyde, HNO3, and NaOH were supplied from Sigma-Aldrich and used as received.');
INSERT INTO "reagents" VALUES(5772,5510,'N,N-dimethylformamide (DMF, soaking of the precipitate)','C3H7NO','wash',NULL,NULL,NULL,NULL,NULL,'the resultant precipitate was soaked in DMF for 1 day to remove the unreacted linker (BDC) captured inside the pores','Synthesis of (Cox–Fe1–x–MOF)',6925,7041,NULL);
INSERT INTO "reagents" VALUES(5773,5510,'distilled water (soaking of the precipitate)','H2O','wash',NULL,NULL,NULL,NULL,NULL,'then soaked in distilled water to remove any unreacted metal precursor loaded inside the pores','Synthesis of (Cox–Fe1–x–MOF)',7046,7140,NULL);
INSERT INTO "reagents" VALUES(5793,5553,'organically modified montmorillonite (O-MMT, modified by CTAB)',NULL,'precursor',0.15,'g',NULL,NULL,'Zhejiang Fenghong New Material Co., Ltd.','0.15 g of O-MMT powder was fully dissolved in 20 mL of DMF solution after sonication for 3 h','2.2. Preparation of Lac-Immobilized PAN/O-MMT/TiO2 Nanofibers',7702,7794,'Organically modified montmorillonite (O-MMT, modified by CTAB) was obtained from Zhejiang Fenghong New Material Co., Ltd. (Zhejiang, China).');
