INSERT INTO "reagents" VALUES(5795,5553,'polyacrylonitrile (PAN, Mw = 50,000 g/mol)','(C3H3N)n','polymer',3.0,'g',NULL,NULL,'Shangyu Wu & Yue Economic and Trade Co., Ltd.','Then, 3 g PAN powder was added into the solution before magnetic stirring for 24 h.','2.2. Preparation of Lac-Immobilized PAN/O-MMT/TiO2 Nanofibers',7796,7879,'Polyacrylonitrile (PAN) (Mw = 50,000 g/mol) powder was purchased from Shangyu Wu & Yue Economic and Trade Co., Ltd. (Zhejiang, China).');
INSERT INTO "reagents" VALUES(5796,5554,'titanium butoxide','Ti(OC4H9)4','precursor',NULL,NULL,NULL,NULL,NULL,'first, Ti(OC4H9)4 was added into 6 mol/L HCl dropwise and stirred for 30 min to prepare the TiO2 sol.','2.2. Preparation of Lac-Immobilized PAN/O-MMT/TiO2 Nanofibers',8210,8311,NULL);
INSERT INTO "reagents" VALUES(5797,5554,'hydrochloric acid 6 mol/L','HCl','acid',NULL,NULL,NULL,NULL,NULL,'first, Ti(OC4H9)4 was added into 6 mol/L HCl dropwise and stirred for 30 min to prepare the TiO2 sol.','2.2. Preparation of Lac-Immobilized PAN/O-MMT/TiO2 Nanofibers',8210,8311,NULL);
