INSERT INTO "reagents" VALUES(5897,5612,'cadmium acetate dihydrate','Cd(CH3COO)2·2H2O','dopant',NULL,NULL,'x = Cd / (Cd + Zn) = 2.0% of a total of 15 mmol','99.5%','Kermel Chemical Reagent Co. (Tianjin, China)','The appropriate amount of Cd(CH3COO)2·2H2O was then added in accordance with the desired molar ratio (x = Cd / (Cd + Zn) = 0.0%, 2.0%, 5.0%, 10.0%, or 20.0%) to bring the total amounts of Zn(CH3COO)2·2H2O and Cd(CH3COO)2·2H2O to 15 mmol.','Methods',5165,5402,'Zinc acetate dihydrate (99.0%), cadmium acetate dihydrate (99.5%) and lithium hydroxide (90.0%) were procured from Kermel Chemical Reagent Co. (Tianjin, China).');
