INSERT INTO "reagents" VALUES(5908,5622,'N,N-dimethylformamide (solvent)','C3H7NO','solvent',29.0,'mL',NULL,'analytical grade','Sigma-Aldrich','the organic linker, terephthalic acid (H2BDC, 0.34 g, 2.046 mmol), was first dissolved in 29 mL of DMF','Synthesis of MOF Materials',6934,7036,'Aluminum sulfate hexadecahydrate (Al2(SO4)3·16H2O), magnesium sulfate heptahydrate (MgSO4·7H2O), ferric chloride hexahydrate (FeCl3·6H2O), N,N-dimethylformamide (DMF), sodium hydroxide (NaOH), hydrochloric acid (HCl), ethanol (C2H5OH), sodium chloride (NaCl), and antibiotic ciprofloxacin (CIP) were purchased from Sigma-Aldrich. All chemicals were of analytical grade and used as received without further purification.');
INSERT INTO "reagents" VALUES(5909,5622,'iron(III) chloride hexahydrate','FeCl3·6H2O','precursor',0.15,'g','0.15 g (0.555 mmol)','analytical grade','Sigma-Aldrich','Separately, a mixed-metal precursor solution was prepared by dissolving FeCl3·6H2O (0.15 g, 0.555 mmol), Al2(SO4)3·16H2O (0.3 g, 0.476 mmol), and MgSO4·7H2O (0.22 g, 0.893 mmol) in 9 mL of deionized water.','Synthesis of MOF Materials',7237,7442,'Aluminum sulfate hexadecahydrate (Al2(SO4)3·16H2O), magnesium sulfate heptahydrate (MgSO4·7H2O), ferric chloride hexahydrate (FeCl3·6H2O), N,N-dimethylformamide (DMF), sodium hydroxide (NaOH), hydrochloric acid (HCl), ethanol (C2H5OH), sodium chloride (NaCl), and antibiotic ciprofloxacin (CIP) were purchased from Sigma-Aldrich. All chemicals were of analytical grade and used as received without further purification.');
INSERT INTO "reagents" VALUES(5910,5622,'aluminum sulfate hexadecahydrate','Al2(SO4)3·16H2O','precursor',0.3,'g','0.3 g (0.476 mmol)','analytical grade','Sigma-Aldrich','Separately, a mixed-metal precursor solution was prepared by dissolving FeCl3·6H2O (0.15 g, 0.555 mmol), Al2(SO4)3·16H2O (0.3 g, 0.476 mmol), and MgSO4·7H2O (0.22 g, 0.893 mmol) in 9 mL of deionized water.','Synthesis of MOF Materials',7237,7442,'Aluminum sulfate hexadecahydrate (Al2(SO4)3·16H2O), magnesium sulfate heptahydrate (MgSO4·7H2O), ferric chloride hexahydrate (FeCl3·6H2O), N,N-dimethylformamide (DMF), sodium hydroxide (NaOH), hydrochloric acid (HCl), ethanol (C2H5OH), sodium chloride (NaCl), and antibiotic ciprofloxacin (CIP) were purchased from Sigma-Aldrich. All chemicals were of analytical grade and used as received without further purification.');
INSERT INTO "reagents" VALUES(5911,5622,'magnesium sulfate heptahydrate','MgSO4·7H2O','precursor',0.22,'g','0.22 g (0.893 mmol)','analytical grade','Sigma-Aldrich','Separately, a mixed-metal precursor solution was prepared by dissolving FeCl3·6H2O (0.15 g, 0.555 mmol), Al2(SO4)3·16H2O (0.3 g, 0.476 mmol), and MgSO4·7H2O (0.22 g, 0.893 mmol) in 9 mL of deionized water.','Synthesis of MOF Materials',7237,7442,'Aluminum sulfate hexadecahydrate (Al2(SO4)3·16H2O), magnesium sulfate heptahydrate (MgSO4·7H2O), ferric chloride hexahydrate (FeCl3·6H2O), N,N-dimethylformamide (DMF), sodium hydroxide (NaOH), hydrochloric acid (HCl), ethanol (C2H5OH), sodium chloride (NaCl), and antibiotic ciprofloxacin (CIP) were purchased from Sigma-Aldrich. All chemicals were of analytical grade and used as received without further purification.');
INSERT INTO "reagents" VALUES(5912,5622,'deionized water (metal solution)','H2O','solvent',9.0,'mL',NULL,NULL,NULL,'Separately, a mixed-metal precursor solution was prepared by dissolving FeCl3·6H2O (0.15 g, 0.555 mmol), Al2(SO4)3·16H2O (0.3 g, 0.476 mmol), and MgSO4·7H2O (0.22 g, 0.893 mmol) in 9 mL of deionized water.','Synthesis of MOF Materials',7237,7442,NULL);
