INSERT INTO "route_variations" VALUES(4505,4248,'MnO2NFs/NrGO dispersion (voie MnO2NFs-NrGO)',NULL,NULL,'absent',NULL,'5 μL','The bare glassy carbon electrodes (GCEs) were carefully polished using 0.3 μm and 0.05 μm alumina slurry, then alternately washed by anhydrous alcohol and deionized water several times, and allowed to dry under an infrared lamp.','2.4. Fabrication of MnO2NFs/NrGO Modified Electrodes',10271,10499,NULL);
