INSERT INTO "route_variations" VALUES(6095,5480,'iron nitrate',NULL,NULL,'replaced by FeC2O4',NULL,'iron nitrate','To determine the influence of the iron sources on the LiMnPO4/C composites, the Fe-substituted LiMnPO4/C materials were prepared using FeC2O4 and Fe2O3 as Fe sources using the same synthetic route, denoted as C-LMFP and O-LMFP, respectively.','Synthesis procedure',5999,6240,NULL);
