INSERT INTO "route_variations" VALUES(6393,5753,'duration',3,4.0,NULL,'h','48 h','Figure 5. (a) XRD patterns of ZSM-5 synthesized with different crystallization times by using 0.8 wt.% S80 and (b) the crystallization curves of the synthesized ZSM-5 zeolites with or without adding seeds.','Figure captions',35076,35281,'Fig. 5a');
INSERT INTO "route_variations" VALUES(6394,5754,'duration',3,5.0,NULL,'h','48 h','Figure 4. SEM images of ZSM-5 synthesized with different crystallization times by using 0.8 wt.% S80. (a) 1 h, (b) 2 h, (c) 2.5 h, (d) 5 h, (e) 12 h and (f) 48 h.','Figure captions',34913,35075,NULL);
INSERT INTO "route_variations" VALUES(6395,5755,'duration',3,8.0,NULL,'h','48 h','Figure 5. (a) XRD patterns of ZSM-5 synthesized with different crystallization times by using 0.8 wt.% S80 and (b) the crystallization curves of the synthesized ZSM-5 zeolites with or without adding seeds.','Figure captions',35076,35281,'Fig. 5a');
INSERT INTO "route_variations" VALUES(6396,5756,'duration',3,12.0,NULL,'h','48 h','Figure 4. SEM images of ZSM-5 synthesized with different crystallization times by using 0.8 wt.% S80. (a) 1 h, (b) 2 h, (c) 2.5 h, (d) 5 h, (e) 12 h and (f) 48 h.','Figure captions',34913,35075,NULL);
INSERT INTO "route_variations" VALUES(6397,5757,'duration',3,24.0,NULL,'h','48 h','Figure 5. (a) XRD patterns of ZSM-5 synthesized with different crystallization times by using 0.8 wt.% S80 and (b) the crystallization curves of the synthesized ZSM-5 zeolites with or without adding seeds.','Figure captions',35076,35281,'Fig. 5a');
INSERT INTO "route_variations" VALUES(6398,5759,'zinc nitrate solution',NULL,NULL,'0.5%Zn',NULL,'1%Zn','0.5%Zn/S60-0.2-0.5 | 0.51 | 0.15 | 0.13 | 0.29 | 0.114 | 0.136 | 379 | 0.184','Catalytic performance over Zn/HZSM-5 zeolites',27496,27572,NULL);
INSERT INTO "route_variations" VALUES(6399,5760,'zinc nitrate solution',NULL,NULL,'3%Zn',NULL,'1%Zn','3%Zn/S60-0.2-0.5 | 3.05 | 0.10 | 0.25 | 0.22 | 0.231 | 0.110 | 335 | 0.160','Catalytic performance over Zn/HZSM-5 zeolites',27648,27722,NULL);
INSERT INTO "route_variations" VALUES(6400,5761,'zinc nitrate solution',NULL,NULL,'5%Zn',NULL,'1%Zn','5%Zn/S60-0.2-0.5 | 5.06 | 0.10 | 0.27 | 0.20 | 0.270 | 0.063 | 327 | 0.155','Catalytic performance over Zn/HZSM-5 zeolites',27723,27797,NULL);
INSERT INTO "steps" VALUES(4929,3951,1,'wash','Rinse fresh leaves with tap water then double distilled water to remove dust.','Fresh and healthy leaves were collected locally and rinsed thoroughly with tap water followed by doubled distilled water to remove all dust and unwanted visible particles','Preparation of the leaf extract',5140,5310);
INSERT INTO "steps" VALUES(4930,3951,2,'dry','Dry the rinsed leaves at room temperature to remove surface water.','after which they were dried at room temperature to remove the water from the surface of leaves, then cut into small pieces.','Preparation of the leaf extract',5312,5435);
INSERT INTO "steps" VALUES(4931,3951,3,'cut','Cut the dried leaves into small pieces.','after which they were dried at room temperature to remove the water from the surface of leaves, then cut into small pieces.','Preparation of the leaf extract',5312,5435);
INSERT INTO "steps" VALUES(4932,3951,4,'heat','Boil the leaf pieces in distilled water to prepare the extract.','Next, 10 g of these finely incised leaves were transferred into 250 ml beakers containing 100 ml distilled water and boiled at 80 °C for 20 min.','Preparation of the leaf extract',5436,5580);
INSERT INTO "steps" VALUES(4933,3951,5,'cool','Cool the extract at room temperature.','After cooling at room temperature, leaves were centrifuged at 12,000 rpm for 15 min at 4 °C and filtered through 0.45 μm PTFE filter.','Preparation of the leaf extract',5581,5714);
INSERT INTO "steps" VALUES(4934,3951,6,'centrifuge','Centrifuge the cooled extract.','After cooling at room temperature, leaves were centrifuged at 12,000 rpm for 15 min at 4 °C and filtered through 0.45 μm PTFE filter.','Preparation of the leaf extract',5581,5714);
INSERT INTO "steps" VALUES(4935,3951,7,'filter','Filter the supernatant through a PTFE filter.','After cooling at room temperature, leaves were centrifuged at 12,000 rpm for 15 min at 4 °C and filtered through 0.45 μm PTFE filter.','Preparation of the leaf extract',5581,5714);
INSERT INTO "steps" VALUES(4936,3951,8,'collect','Store the filtrate (leaf extract) before use as reducing and stabilizing agent.','The filtrates were then stored at 4–8 °C and used as reducing and stabilizing agents in the synthesis of AgNPs.','Preparation of the leaf extract',5715,5826);
INSERT INTO "steps" VALUES(4937,3951,9,'dissolve','Prepare a 1 mM aqueous silver nitrate solution.','Aqueous solution of 1 mM silver nitrate (AgNO3) was prepared in a 250 ml Erlenmeyer flask and used for the synthesis of AgNPs.','AgNPs synthesis',5898,6024);
INSERT INTO "steps" VALUES(4938,3951,10,'add','Add the leaf extract into the silver nitrate solution (extract added to AgNO3, not the reverse).','Briefly, 10 ml of Aloe vera leaf extract was added into 90 ml of aqueous solution of 1 mM silver nitrate and incubated in the dark overnight at room temperature.','AgNPs synthesis',6025,6186);
INSERT INTO "steps" VALUES(4939,3951,11,'age','Incubate the mixture in the dark at room temperature until the colour turns brownish yellow.','Briefly, 10 ml of Aloe vera leaf extract was added into 90 ml of aqueous solution of 1 mM silver nitrate and incubated in the dark overnight at room temperature.','AgNPs synthesis',6025,6186);
INSERT INTO "steps" VALUES(4940,3951,12,'collect','Seal the colloidal mixture and store it for later use.','The colloidal mixture was then sealed and stored properly for future use.','AgNPs synthesis',6310,6383);
INSERT INTO "steps" VALUES(4941,3952,1,'dissolve','Dissolve zinc nitrate hexahydrate and 2,6-pyridine dicarboxylic acid in double distilled water.','A mixture of zinc nitrate hexahydrate (0,120 mmol) and 2,6-pyridine dicarboxylic acid (0,120 mmol) is dissolved in 21 mL of double distilled water','Ultrasonic assisted reverse micelle method',7441,7587);
INSERT INTO "steps" VALUES(4942,3952,2,'add','Add the aqueous solution to the sodium dodecyl sulfate / hexane mixture to form the reverse micelle system.','The resulting solution was added to a mixture of 0.077 mmol of sodium dodecyl sulfate and 8 mL of hexane.','Ultrasonic assisted reverse micelle method',7652,7757);
INSERT INTO "steps" VALUES(4943,3952,3,'stir','Stir the resulting mixture at 85 °C for 1 h.','Then, the resulting mixture was stirred at temperature of 85 °C for 1 h.','Ultrasonic assisted reverse micelle method',7758,7830);
INSERT INTO "steps" VALUES(4944,3952,4,'react','Ultrasonic irradiation of the mixture under the conditions called optimum by the authors.','The resulting solution was put into the ultrasonic device and was placed under ultrasonic irradiation in optimum conditions including ultrasonic duration of 21 min, power of 175 W and ultrasonic temperature of 40 °C.','Ultrasonic assisted reverse micelle method',7831,8047);
INSERT INTO "steps" VALUES(4945,3952,5,'age','Wait 30 min, after which the Zn-MOF crystals are formed (starting point of the 30 min is not specified).','After 30 min, the Zn-MOF crystals are formed that are separated by centrifugation and washed by DMF.','Ultrasonic assisted reverse micelle method',8048,8148);
INSERT INTO "steps" VALUES(4946,3952,6,'centrifuge','Separate the Zn-MOF crystals by centrifugation.','separated by centrifugation','Ultrasonic assisted reverse micelle method',8102,8129);
INSERT INTO "steps" VALUES(4947,3952,7,'wash','Wash the crystals with DMF.','washed by DMF','Ultrasonic assisted reverse micelle method',8134,8147);
INSERT INTO "steps" VALUES(4948,3953,1,'mix','Add the aqueous enzyme solution and the aqueous zinc nitrate solution into the aqueous 2-methylimidazole solution.','HRP, CALB, Cyt c water solution (5 mg/mL, 4 mL), and Zn(NO3)2 water solution (92.5 mg/mL, 4 mL) were added into 2-methylimidazole water solution (4.1 g dissolved in 40 mL water)','Synthesis of the enzyme/ZIF-8 composite',5029,5206);
INSERT INTO "steps" VALUES(4949,3953,2,'stir','Stir the mixture at room temperature; it turns milky almost instantly.','followed by stirring for 30 min at room temperature','Synthesis of the enzyme/ZIF-8 composite',5208,5259);
INSERT INTO "steps" VALUES(4950,3953,3,'age','Age the milky suspension at room temperature.','After aged at room temperature for 12 h','Synthesis of the enzyme/ZIF-8 composite',5317,5356);
INSERT INTO "steps" VALUES(4951,3953,4,'centrifuge','Collect the product by centrifugation.','the product was collected by centrifugation at 6000 rpm for 10 min','Synthesis of the enzyme/ZIF-8 composite',5358,5424);
INSERT INTO "steps" VALUES(4952,3953,5,'wash','Wash the collected solid with deionized water (washing and centrifugation cycles, removing adsorbed protein).','washed with DI water for three times','Synthesis of the enzyme/ZIF-8 composite',5426,5462);
INSERT INTO "steps" VALUES(4953,3956,1,'mix','Physically mix the as-prepared pure ZIF-8 crystals with the enzyme solutions.','physically mixing the as-prepared pure ZIF-8 crystals with enzyme solutions to form the enzyme-adsorbed ZIF-8 samples','Results and discussion',10961,11078);
INSERT INTO "steps" VALUES(4954,3956,2,'wash','Wash the samples with the same washing step as for the embedded composites (DI water, three times, per the composite protocol; see doubts).','After the same washing step','Results and discussion',11080,11107);
INSERT INTO "steps" VALUES(4955,3957,1,'mix','Add aqueous solutions of CuCl2, HAuCl4 and glucose into a 20-ml glass vial already containing a mixture of HDA and water, at room temperature (Au/Cu molar ratio 1:1).','0.3 ml of aqueous CuCl2·2H2O (100 mM), 0.3 ml of aqueous HAuCl4·3H2O (100 mM), 45 mg of HDA, 0.28 ml of aqueous glucose (1 M) and 4 ml of water were added in a 20-ml vial at room temperature','Synthesis of 200-nm pentacle Au–Cu alloy nanocrystals',32992,33182);
INSERT INTO "steps" VALUES(4956,3957,2,'stir','Cap the vial and stir magnetically at room temperature overnight.','After the vial had been capped, the solution was magnetically stirred at room temperature overnight.','Synthesis of 200-nm pentacle Au–Cu alloy nanocrystals',33184,33284);
INSERT INTO "steps" VALUES(4957,3957,3,'heat','Transfer the capped vial into an oil bath and heat at 100 °C under magnetic stirring; the colour changes from kelly green to brown.','The capped vial was then transferred into an oil bath and heated at 100 °C for 30 min under magnetic stirring.','Synthesis of 200-nm pentacle Au–Cu alloy nanocrystals',33285,33395);
INSERT INTO "steps" VALUES(4958,3957,4,'centrifuge','Centrifuge the product (described for preparing electron microscopy samples).','the pentacle nanocrystals were centrifugated at 10,000 r.p.m. for 8 min','Synthesis of 200-nm pentacle Au–Cu alloy nanocrystals',33544,33615);
INSERT INTO "steps" VALUES(4959,3957,5,'wash','Wash with water three times and ethanol twice to remove excess precursor, HDA and glucose.','washed with water three times and ethanol twice to remove excess precursor, HDA and glucose','Synthesis of 200-nm pentacle Au–Cu alloy nanocrystals',33620,33711);
INSERT INTO "steps" VALUES(4960,3975,1,'mix','Add aqueous CuCl2, aqueous HAuCl4, HDA, aqueous glucose and water into a 20-ml vial at room temperature.','0.3 ml of aqueous CuCl2·2H2O (100 mM), 0.3 ml of aqueous HAuCl4·3H2O (100 mM), 45 mg of HDA, 0.28 ml of aqueous glucose (1 M) and 4 ml of water were added in a 20-ml vial at room temperature. After the vial had been capped','Synthesis of 200-nm pentacle Au–Cu alloy nanocrystals',32992,33214);
INSERT INTO "steps" VALUES(4961,3975,2,'stir','Stir magnetically at room temperature overnight.','the solution was magnetically stirred at room temperature overnight. The capped vial was then transferred into an oil bath and heated at 100 °C for 3 min.','Controlling the size of pentacle Au–Cu alloy nanocrystals',34228,34382);
INSERT INTO "steps" VALUES(4962,3975,3,'heat','Transfer the capped vial into an oil bath and heat at 100 °C for 3 min.','The capped vial was then transferred into an oil bath and heated at 100 °C for 3 min.','Controlling the size of pentacle Au–Cu alloy nanocrystals',34297,34382);
INSERT INTO "steps" VALUES(4963,3975,4,'add','Add 30 mg of additional HDA to the reaction solution at 100 °C.','Then 30 mg HDA was added into the reaction solution at 100 °C.','Controlling the size of pentacle Au–Cu alloy nanocrystals',34383,34445);
INSERT INTO "steps" VALUES(4964,3975,5,'cool','Stop the reaction and cool the solution with iced water when its colour changes from kelly green to brown.','The reaction was stopped and the solution was cooled down using iced water when its colour changed from kelly green to brown.','Controlling the size of pentacle Au–Cu alloy nanocrystals',34446,34571);
INSERT INTO "steps" VALUES(4965,3978,1,'coat','Coat the surface of the pentacle nanocrystals with a monolayer of PEG (no procedure given in the article).','The surface of pentacle nanocrystals was coated with a monolayer of polyethylene glycol (PEG)','Plasmonic properties and photothermal therapy (PTT)',24655,24748);
INSERT INTO "steps" VALUES(4966,3979,1,'dissolve','Dissolve l-cysteine in distilled water under magnetic stirring to obtain a colorless solution.','3 mmol l-cysteine was dissolved in 30 mL distilled water under magnetic stirring for 15 min to obtain a colorless solution','Material Synthesis',5115,5237);
INSERT INTO "steps" VALUES(4967,3979,2,'add','Pour distilled water and SbCl3 into the beaker under stirring to obtain a milky suspension.','30 mL distilled water and 2 mmol SbCl3 were systematically poured into the beaker under stirring for 35 min to produce a milky suspension liquid','Material Synthesis',5245,5389);
INSERT INTO "steps" VALUES(4968,3979,3,'heat','Hydrothermal treatment of the suspension in a Teflon-lined stainless-steel autoclave.','the above solution was transferred into an 80-mL Teflon-lined stainless-steel autoclave and then maintained at 150 °C for 12 h','Material Synthesis',5402,5528);
INSERT INTO "steps" VALUES(4969,3979,4,'wash','Collect the product and wash it with absolute ethyl alcohol and deionized water.','The Sb2S3 was gathered and washed several times with absolute ethyl alcohol and deionized water','Material Synthesis',5530,5625);
INSERT INTO "steps" VALUES(4970,3979,5,'dry','Dry the washed product in vacuum.','dried at 80 °C for 5 h in vacuum','Material Synthesis',5631,5663);
INSERT INTO "steps" VALUES(4971,3982,1,'mix','Mix CMC, acetylene black and the Sb2S3 active material in the mass ratio 1:1:3.','The work electrode was prepared by mixing the carboxymethyl cellulose Na salt (CMC), acetylene black, and active material in the mass ratio of 1:1:3','Electrochemical Measurements',5959,6107);
INSERT INTO "steps" VALUES(4972,3982,2,'add','Adjust the viscosity of the mixture with distilled water.','after which the viscosity was varied with distilled water and magnetic stirring overnight','Electrochemical Measurements',6109,6198);
INSERT INTO "steps" VALUES(4973,3982,3,'stir','Stir the slurry magnetically overnight.','after which the viscosity was varied with distilled water and magnetic stirring overnight','Electrochemical Measurements',6109,6198);
INSERT INTO "steps" VALUES(4974,3983,1,'assemble','Assemble the test cell from the working electrode, Celgard 2300 separator, lithium counter electrode and LiPF6 electrolyte, in an argon-filled glove box.','For LIBs, the testing batteries were assembled with the working electrode already prepared, and with Celgard 2300 film as the separator, lithium metal as the reference/counter electrode, and 1 M LiPF6 in dimethyl carbonate (DMC)/ethylene carbonate (EC) (1:1 v/v) as the electrolyte.','Electrochemical Measurements',6261,6543);
INSERT INTO "steps" VALUES(4975,3985,1,'add','Add CTAB to bi-distilled water in a flat-bottomed flask.','0.2 g of CTAB was added to 100 mL of bi-distilled (BD) water, in a flat-bottomed flask','Synthesis of thorn-like ZnO nanoparticles',4849,4935);
INSERT INTO "steps" VALUES(4976,3985,2,'add','Add the zinc acetate dihydrate solution to the CTAB solution.','To this, 10 mL of 1% Zn(CH3COO)2·2H2O solution was added.','Synthesis of thorn-like ZnO nanoparticles',4937,4994);
INSERT INTO "steps" VALUES(4977,3985,3,'stir','Place the apparatus on a mechanical stirrer at the chosen stirring speed (500 rpm for this sample).','The whole apparatus was kept on mechanical stirrer under different stirring conditions viz. 500 rpm, 1000 rpm, 1500 rpm and 2000 rpm.','Synthesis of thorn-like ZnO nanoparticles',4995,5128);
INSERT INTO "steps" VALUES(4978,3985,4,'add','Add the NaOH solution drop-wise; the colloidal solution turns milky within a few minutes of agitation.','Subsequently, the NaOH solution was added drop-wise to the cocktail.','Synthesis of thorn-like ZnO nanoparticles',5129,5197);
INSERT INTO "steps" VALUES(4979,3985,5,'react','Keep the setup as such for half an hour.','The setup was retained as such for half an hour.','Synthesis of thorn-like ZnO nanoparticles',5268,5316);
INSERT INTO "steps" VALUES(4980,3985,6,'cool','Cool the system.','The system was then cooled, centrifuged, dried at room temperature in a desiccator, and washed with BD water and methanol.','Synthesis of thorn-like ZnO nanoparticles',5317,5439);
INSERT INTO "steps" VALUES(4981,3985,7,'centrifuge','Centrifuge the cooled system to collect the solid.','The system was then cooled, centrifuged, dried at room temperature in a desiccator, and washed with BD water and methanol.','Synthesis of thorn-like ZnO nanoparticles',5317,5439);
INSERT INTO "steps" VALUES(4982,3985,8,'dry','Dry at room temperature in a desiccator.','The system was then cooled, centrifuged, dried at room temperature in a desiccator, and washed with BD water and methanol.','Synthesis of thorn-like ZnO nanoparticles',5317,5439);
INSERT INTO "steps" VALUES(4983,3985,9,'wash','Wash with bi-distilled water and methanol.','The system was then cooled, centrifuged, dried at room temperature in a desiccator, and washed with BD water and methanol.','Synthesis of thorn-like ZnO nanoparticles',5317,5439);
INSERT INTO "steps" VALUES(4984,3985,10,'store','Store the ZnO nanoparticles in an amber-coloured container until use.','Finally, the samples of ZnO-NPs were stored in amber colour container until further use.','Synthesis of thorn-like ZnO nanoparticles',5561,5649);
INSERT INTO "steps" VALUES(4985,3989,1,'mix','Mix methylammonium bromide and lead bromide in DMF in a glass vial.','0.16 mmol of methylammonium bromide (MABr) and 0.2 mmol of lead bromide (PbBr2) were mixed in 5 ml dimethylformamide (DMF) solution','Size-varied perovskite NC synthesis',30876,31007);
INSERT INTO "steps" VALUES(4986,3989,2,'add','Add oleylamine and oleic acid to the DMF solution to obtain the final precursor solution.','50 μl of oleylamine and 0.5 ml oleic acid were also mixed in the DMF solution to form the final precursor solution','Size-varied perovskite NC synthesis',31016,31130);
INSERT INTO "steps" VALUES(4987,3989,3,'heat','Preheat toluene in a round-bottom flask in an oil bath.','Another round-bottom flask containing 5 ml of toluene was preheated to 60 °C in an oil bath.','Size-varied perovskite NC synthesis',31132,31224);
INSERT INTO "steps" VALUES(4988,3989,4,'add','Swiftly inject the precursor solution into the hot toluene under vigorous stirring; the solution turns green.','Then 250 μl of as-prepared precursor solution was swiftly injected into hot toluene solution under vigorous stirring condition.','Size-varied perovskite NC synthesis',31225,31352);
INSERT INTO "steps" VALUES(4989,3989,5,'react','Let the reaction continue after injection.','The reaction was continued for another 5 min and stopped by cooling in a water bath.','Size-varied perovskite NC synthesis',31433,31517);
INSERT INTO "steps" VALUES(4990,3989,6,'cool','Stop the reaction by cooling in a water bath.','The reaction was continued for another 5 min and stopped by cooling in a water bath.','Size-varied perovskite NC synthesis',31433,31517);
INSERT INTO "steps" VALUES(4991,3989,7,'centrifuge','Centrifuge the reaction solution; the speed selects the NC size (8,000 r.p.m. for the medium NCs).','The reaction solution was transferred into a centrifuge tube and centrifuged at the desired speed for different sized spherical-shaped MAPbBr3 NCs.','Size-varied perovskite NC synthesis',31518,31665);
INSERT INTO "steps" VALUES(4992,3989,8,'dissolve','Re-dissolve the precipitate in toluene.','The precipitation of MAPbBr3 NCs was re-dissolved in toluene solution for further studies.','Size-varied perovskite NC synthesis',31666,31756);
INSERT INTO "steps" VALUES(4993,3992,1,'deposit','Spin-coat the 0.6 M MAPbBr3 solution in DMF on quartz substrates.','A solution containing 0.6 M MAPbBr3 in DMF was spin-coated (5,000 r.p.m., 12 s) on quartz substrates.','MAPbBr3 bulk-film fabrication',32063,32164);
INSERT INTO "steps" VALUES(4994,3992,2,'add','Add a few drops of toluene on the spinning film.','During spin-coating, few drops of toluene were added to the film at 3 s after the beginning of spinning.','MAPbBr3 bulk-film fabrication',32165,32269);
INSERT INTO "steps" VALUES(4995,3992,3,'dry','Dry the film at room temperature.','The film was then dried in room temperature for 30 min and annealed at 70 °C for 5 min.','MAPbBr3 bulk-film fabrication',32270,32357);
INSERT INTO "steps" VALUES(4996,3992,4,'anneal','Anneal the film.','The film was then dried in room temperature for 30 min and annealed at 70 °C for 5 min.','MAPbBr3 bulk-film fabrication',32270,32357);
INSERT INTO "steps" VALUES(4997,3994,1,'deposit','Spin-coat the NC solution on glass substrates, two layers.','To prepare the NC film, NCs in toluene (10 mg ml−1) was spin-coated on glass substrates for two layers.','MAPbBr3 NCs and EDT-NC film fabrications',32766,32869);
INSERT INTO "steps" VALUES(4998,3997,1,'deposit','Spin-coat the NC solution on top of the substrate.','(1) spin-coating of NC solution on top of substrate','MAPbBr3 NCs and EDT-NC film fabrications',32980,33031);
INSERT INTO "steps" VALUES(4999,3997,2,'add','Cover the NC film with 0.2 M EDT solution in 2-propanol, wait, then spin-coat.','(2) cover the NC film with 0.2 M EDT solution in 2-Propanol and wait for 30 s and then spin coat','MAPbBr3 NCs and EDT-NC film fabrications',33033,33129);
INSERT INTO "steps" VALUES(5000,3997,3,'wash','Drop anhydrous toluene on the film and spin-coat to remove the remaining long-chained ligands.','(3) dropping of anhydrous toluene on film and followed by spin-coating to clean the remaining long-chained ligands.','MAPbBr3 NCs and EDT-NC film fabrications',33131,33246);
INSERT INTO "steps" VALUES(5001,3997,4,'deposit','Repeat the three-step layer cycle to build up the film thickness.','The above process was repeated for two to ten times, to obtain the NC film with different thickness.','MAPbBr3 NCs and EDT-NC film fabrications',33247,33347);
INSERT INTO "steps" VALUES(5002,3999,1,'deposit','Spin-coat the NC solution on top of the substrate.','(1) spin-coating of NC solution on top of substrate','MAPbBr3 NCs and EDT-NC film fabrications',32980,33031);
INSERT INTO "steps" VALUES(5003,3999,2,'add','Cover the NC film with 0.2 M EDT solution in 2-propanol, wait, then spin-coat.','(2) cover the NC film with 0.2 M EDT solution in 2-Propanol and wait for 30 s and then spin coat','MAPbBr3 NCs and EDT-NC film fabrications',33033,33129);
INSERT INTO "steps" VALUES(5004,3999,3,'wash','Drop anhydrous toluene on the film and spin-coat to remove the remaining long-chained ligands.','(3) dropping of anhydrous toluene on film and followed by spin-coating to clean the remaining long-chained ligands.','MAPbBr3 NCs and EDT-NC film fabrications',33131,33246);
INSERT INTO "steps" VALUES(5005,3999,4,'deposit','Repeat the three-step layer cycle to build up the film thickness.','The above process was repeated for two to ten times, to obtain the NC film with different thickness.','MAPbBr3 NCs and EDT-NC film fabrications',33247,33347);
INSERT INTO "steps" VALUES(5006,3999,5,'anneal','Post-anneal the EDT-treated NC film.','For post-annealed samples, the annealing was performed at 70 °C for 5 min.','MAPbBr3 NCs and EDT-NC film fabrications',33348,33422);
INSERT INTO "steps" VALUES(5007,4000,1,'deposit','Thermal evaporation of Bphen on the NC films under vacuum.','Bphen was deposited on spin-coated non-annealed or annealed perovskites NCs films at a rate of 0.1–0.2 nm s−1.','Bphen thin-film fabrication',33622,33732);
INSERT INTO "steps" VALUES(5008,4001,1,'place','Place the MoCl5 powder at the center of the tube furnace and the sulfur powder at the upstream entry.','1–50 mg of molybdenum chloride (MoCl5) powder (99.99%, Sigma-Aldrich) was placed at the center of the furnace and 1 g of sulfur powder (Sigma-Aldrich) were placed at the upstream entry of the furnace','Methods',23251,23450);
INSERT INTO "steps" VALUES(5009,4001,2,'place','Place the receiving substrates downstream of the furnace center (sapphire for the reference monolayer).','Receiving substrates were placed downstream in a distance of 1–7 centimeters away from the center of the furnace.','Methods',23452,23565);
INSERT INTO "steps" VALUES(5010,4001,3,'heat','Heat the furnace under Ar flow to the growth temperature, hold, to grow the MoS2 film on the substrates.','In typical experiments, the furnace was heated up at a rate of 28°C/min under a flow of Ar gas, held at a setting temperature for 10 min','Methods',23566,23702);
INSERT INTO "steps" VALUES(5011,4001,4,'cool','Let the furnace cool down naturally to room temperature.','and then naturally cooled down to room temperature','Methods',23704,23754);
INSERT INTO "steps" VALUES(5012,4024,1,'transfer','Transfer the MoS2 film grown on sapphire to degenerately doped silicon substrates covered with a 280 nm SiO2 layer.','We transferred the thin film grown on sapphire to degenerately doped silicon substrates covered with 280-nm-thick SiO2','Results',13051,13169);
INSERT INTO "steps" VALUES(5013,4024,2,'place','Place a copper grid on top of the film as a mask for the electrodes.','A copper grid (100mesh, 30 micron spacing, Ted Pella) was placed on top of the thin film as mask for the electrode fabrication.','Methods',25048,25175);
INSERT INTO "steps" VALUES(5014,4024,3,'deposit','Evaporate Ti/Au electrodes on top of the MoS2 film.','The field-effect transistor device was fabricated by evaporating Ti/Au (5/200 nm) electrodes directly onto top of MoS2 films transferred to degenerately doped Si substrates with 280 nm thick silicon oxide.','Methods',24842,25047);
INSERT INTO "steps" VALUES(5015,4025,1,'react','Synthesis of the MSNs from TEOS and CTAB with DEA as base catalyst; the article gives no further operating details (renvoi to previous reports).','The same concentration of silica source (TEOS) and template (CTAB), but different DEA (0.2 and 0.6 vt%) created 20 and 40 nm MSNs, respectively.','Size-controlled synthesis and characterization of Ru@MSNs nanosystems',18521,18665);
INSERT INTO "steps" VALUES(5016,4027,1,'react','Synthesis of the MSNs from TEOS with TEA as base catalyst and CTAB as template; the article gives no further operating details (renvoi to previous reports).','For example under the same condition with 0.3 vt% TEA as base catalyst and 0.75 vt% TEOS as silica source, MSNs at 60 or 80 nm was obtained with 10 wt% CTAB or CTAC as templates, respectively.','Size-controlled synthesis and characterization of Ru@MSNs nanosystems',18072,18264);
INSERT INTO "steps" VALUES(5017,4029,1,'dissolve','Dissolve RuPOP in DMSO.','In detail, 20 mg of RuPOP was dissolved in 10 mL DMSO.','Synthesis of different-sized Ru@MSNs nanosystems',9361,9415);
INSERT INTO "steps" VALUES(5018,4029,2,'mix','Suspend the MSNs in the RuPOP solution and stir at room temperature (loading of RuPOP).','Then 50 mg of different-sized MSNs were suspended into the solution and stirred for 24 h at room temperature, respectively.','Synthesis of different-sized Ru@MSNs nanosystems',9416,9539);
INSERT INTO "steps" VALUES(5019,4029,3,'centrifuge','Collect the RuPOP-loaded nanoparticles by centrifugation.','The nanoparticles were obtained by centrifugation at 12,000 rpm for 10 min','Synthesis of different-sized Ru@MSNs nanosystems',9540,9614);
INSERT INTO "steps" VALUES(5020,4029,4,'mix','Mix the nanoparticles with a pre-prepared PEI-FA solution to coat them.','mixed with pre-prepared PEI-FA solution for 24 h','Synthesis of different-sized Ru@MSNs nanosystems',9619,9667);
INSERT INTO "steps" VALUES(5021,4029,5,'centrifuge','Collect the final Ru@MSNs by centrifugation.','Finally, different-sized Ru@MSNs was obtained by centrifugation and low-temperature vacuum drying.','Synthesis of different-sized Ru@MSNs nanosystems',9669,9767);
INSERT INTO "steps" VALUES(5022,4029,6,'dry','Dry the Ru@MSNs at low temperature under vacuum.','Finally, different-sized Ru@MSNs was obtained by centrifugation and low-temperature vacuum drying.','Synthesis of different-sized Ru@MSNs nanosystems',9669,9767);
INSERT INTO "steps" VALUES(5023,4032,1,'grind','Crush the as-received fennel seeds with a mixer grinder to obtain a fennel powder.','As received fennel seeds were crushed using a mixer grinder (Tiger mixer grinder, Japan).','Synthesis of C-QD',6423,6512);
INSERT INTO "steps" VALUES(5024,4032,2,'heat','Pyrolysis of the ground fennel powder (0.2 g) in a crucible cup on a heat plate at constant temperature.','Ground greenish fennel powder (0.2 g) was transferred to the crucible cup (AS ONE, Japan) and was heated using a heat plate (AS ONE, Japan) at a constant temperature of 500 °C for 3 hours.','Synthesis of C-QD',6513,6701);
INSERT INTO "steps" VALUES(5025,4032,3,'cool','Let the crucible cool down to room temperature; the powder has turned into a dark-gray carbonized product.','Subsequently, the crucible was allowed to cool down to room temperature.','Synthesis of C-QD',6702,6774);
INSERT INTO "steps" VALUES(5026,4032,4,'dissolve','Dissolve the dark-gray carbonized product in deionized water.','Carbonization of the greenish fennel powder turned into a dark-gray product, and it was dissolved in deionized water followed by the sonication for 5 minutes.','Synthesis of C-QD',6775,6933);
INSERT INTO "steps" VALUES(5027,4032,5,'sonicate','Sonicate the suspension after dissolution in deionized water.','it was dissolved in deionized water followed by the sonication for 5 minutes','Synthesis of C-QD',6856,6932);
INSERT INTO "steps" VALUES(5028,4032,6,'centrifuge','Centrifuge the black suspension to remove the large undissolved particles and keep the supernatant.','The black color suspension was centrifuged at 15000 rpm for 10 minutes to remove the large un-dissolved particles.','Synthesis of C-QD',6934,7048);
INSERT INTO "steps" VALUES(5029,4032,7,'filter','Filter the supernatant through a 100 nm pore size filter.','The supernatant was filtered using 100 nm pore size filter (PALL ACRO DISC, Japan)','Synthesis of C-QD',7049,7131);
INSERT INTO "steps" VALUES(5030,4032,8,'dialyze','Purify the filtered solution by dialysis.','subjected to the dialysis using dialysis kit (Float-A-Lyzer G2 Dialysis, Japan) for further purification','Synthesis of C-QD',7136,7240);
INSERT INTO "steps" VALUES(5031,4032,9,'collect','Transfer the purified C-QDs to a glass vial and store them for characterization.','The purified C-QDs was transferred to the glass vial and stored for further characterization.','Synthesis of C-QD',7242,7335);
INSERT INTO "steps" VALUES(5032,4037,1,'remove','Remove the cortical components of the bovine bone to keep the spongy bone.','spongy bone samples which were obtained after removal of the cortical components','2.1. Synthesis of Hydroxyapatite Particles',6695,6775);
INSERT INTO "steps" VALUES(5033,4037,2,'clean','Clean the bovine bone samples mechanically.','bovine bone samples were mechanically cleaned','2.1. Synthesis of Hydroxyapatite Particles',6870,6915);
INSERT INTO "steps" VALUES(5034,4037,3,'heat','Heat treatment to remove the organic components.','a heat treatment at 500 °C for one hour in order to remove organic components','2.1. Synthesis of Hydroxyapatite Particles',6929,7006);
INSERT INTO "steps" VALUES(5035,4037,4,'calcine','Proper thermal treatment of the cleaned bone at 1200 °C.','Proper thermal treatment was performed at 1200 °C for 6 h with a heating rate of 10 °C/min.','2.1. Synthesis of Hydroxyapatite Particles',7008,7099);
INSERT INTO "steps" VALUES(5036,4037,5,'cool','Cool the samples in air.','After cooling in the air','2.1. Synthesis of Hydroxyapatite Particles',7100,7124);
INSERT INTO "steps" VALUES(5037,4037,6,'grind','Grind the samples in an agate ball mill.','the samples were ground in an agate ball mill and then sieved','2.1. Synthesis of Hydroxyapatite Particles',7126,7187);
INSERT INTO "steps" VALUES(5038,4037,7,'sieve','Sieve the ground powder and keep the particles smaller than 40 µm.','hydroxyapatite particles with sizes smaller than 40 µm were used','2.1. Synthesis of Hydroxyapatite Particles',7212,7276);
INSERT INTO "steps" VALUES(5039,4038,1,'dissolve','Dissolve polylactic acid in chloroform to make a 12 wt.% solution.','Polylactic acid was dissolved in chloroform at a concentration of 12 wt.%.','2.2. Synthesis of PLA/HA Composite Films',7322,7396);
INSERT INTO "steps" VALUES(5040,4038,2,'mix','Disperse the hydroxyapatite particles (from route HA_bovine) in the polymer solution by ultrasonication.','The hydroxyapatite particles were dispersed by ultrasonication for 30 min into the polymer solution at three different concentrations (1, 2, and 4 wt.%, respectively) in order to obtain a homogenous solution.','2.2. Synthesis of PLA/HA Composite Films',7397,7605);
INSERT INTO "steps" VALUES(5041,4038,3,'deposit','Cast the mixture into a glass Petri dish.','casting the obtained mixture into a Petri glass 60 mm in diameter (LabBox, Barcelona, Spain)','2.2. Synthesis of PLA/HA Composite Films',7646,7738);
INSERT INTO "steps" VALUES(5042,4038,4,'evaporate','Evaporate the solvent in an oven to form the film.','evaporating the solvent at 40 °C for 72 h in an oven','2.2. Synthesis of PLA/HA Composite Films',7743,7795);
INSERT INTO "steps" VALUES(5043,4038,5,'wash','Wash the films with distilled water and ethanol to remove chloroform and polymer residues.','After synthesis, the composite films were washed with distilled water and ethanol to remove any chloroform and polymer residues and kept dry until use.','2.2. Synthesis of PLA/HA Composite Films',7948,8099);
INSERT INTO "steps" VALUES(5044,4038,6,'store','Keep the films dry until use.','kept dry until use','2.2. Synthesis of PLA/HA Composite Films',8080,8098);
INSERT INTO "steps" VALUES(5045,4042,1,'dissolve','Dissolve nickel acetate tetrahydrate and thioacetamide in water in a flat-bottomed beaker (Ni:S molar ratio 1:1).','we dissolved 2.49 g (= 0.01 mol) of Ni(CH3COO)2 ∙ 4H2O and 0.75 g (= 0.01 mol) of C2H5NS in 50 mL of water in a 100 mL flat-bottomed beaker','Experimental',6988,7127);
INSERT INTO "steps" VALUES(5046,4042,2,'sonicate','Sonicate the solution in ambient atmosphere with a direct immersion titanium horn at 70% amplitude; the green solution turns black.','The mixture was sonicated in an ambient atmosphere for 1 h using a Sonics and Materials VCX 600 sonicator (20 kHz, 1 cm2 Ti direct immersion horn) at different amplitudes, namely 30%, 50%, 70% and 90%.','Experimental',7129,7330);
INSERT INTO "steps" VALUES(5047,4042,3,'centrifuge','Centrifuge the black precipitate.','The black precipitate obtained after 1 h of sonication was centrifuged at 7000 RPM','Experimental',7444,7526);
INSERT INTO "steps" VALUES(5048,4042,4,'wash','Wash the precipitate twice with water and twice with absolute ethanol.','washed twice with water and twice with absolute ethanol','Experimental',7528,7583);
INSERT INTO "steps" VALUES(5049,4042,5,'dry','Air-dry the washed solid.','air-dried for 24 h','Experimental',7588,7606);
INSERT INTO "steps" VALUES(5050,4055,1,'dissolve','Dissolve cobalt acetate dihydrate and thioacetamide in water (Co:S molar ratio 1:1); the solution is red.','we dissolved 2.13 g (= 0.01 mol) of Co(CH3COO)2 ∙ 2H2O and 0.75 g (= 0.01 mol) of C2H5NS in 50 mL of water','Experimental',8320,8426);
INSERT INTO "steps" VALUES(5051,4055,2,'sonicate','Sonicate the solution at 70% amplitude; the red solution turns black after 5 min.','sonicated the solution for 1 h at 70% amplitude','Experimental',8431,8478);
INSERT INTO "steps" VALUES(5052,4055,3,'centrifuge','Centrifuge the black precipitate; the article only says it is handled as described above, so the speed is the one of the nickel procedure (see doubts).','The black precipitate obtained after 1 h of sonication was handled as described above.','Experimental',8537,8623);
INSERT INTO "steps" VALUES(5053,4055,4,'wash','Wash the precipitate twice with water and twice with absolute ethanol, as for the nickel sulfides (renvoi « as described above »).','The black precipitate obtained after 1 h of sonication was handled as described above.','Experimental',8537,8623);
INSERT INTO "steps" VALUES(5054,4055,5,'dry','Air-dry the washed solid for 24 h, as for the nickel sulfides (renvoi « as described above »).','The black precipitate obtained after 1 h of sonication was handled as described above.','Experimental',8537,8623);
INSERT INTO "steps" VALUES(5055,4055,6,'heat','Heat the amorphous sonochemical product at 500 °C to obtain nanocrystalline cobalt sulfide.','nanocrystalline products were obtained by heating the precursors obtained by the sonochemical reaction for 2 h at 500 °C','Cobalt sulfides',19336,19456);
INSERT INTO "steps" VALUES(5056,4061,1,'dissolve','Dissolve zinc acetate and CTAB in distilled water under constant stirring.','1 g of zinc acetate (Zn(Ac)2 2H2O) and 2g cetyltrimethylammonium bromide (CTAB, C19H42BrN) were dissolved in 60 mL distilled water under constant stirring','3.2.1. Synthesis of ZnO Using CTAB (Constant) and SDS (Variant)',19773,19927);
INSERT INTO "steps" VALUES(5057,4061,2,'adjust_ph','Gradually introduce 5 mol/L NaOH solution until the pH reaches 13.','5 mol/L NaOH solution was gradually introduced to the mentioned solution until pH reached at 13','3.2.1. Synthesis of ZnO Using CTAB (Constant) and SDS (Variant)',19937,20032);
INSERT INTO "steps" VALUES(5058,4061,3,'add','Add a certain amount of SDS so that the CTAB:SDS molar ratio takes the tested value (1:0 for this sample, i.e. no SDS).','certain amount of sodium dodecyl sulfate (SDS, C12H25SO4Na) was added to the solution as molar ratio of CATB: SDS equaled to 1:0, 1:0.2, 1:0.36, 1:0.5, 1:1 and 1:1.5','3.2.1. Synthesis of ZnO Using CTAB (Constant) and SDS (Variant)',20040,20205);
INSERT INTO "steps" VALUES(5059,4061,4,'heat','Hydrothermal growth in a Teflon-lined stainless steel autoclave.','solution with white flocculent precipitate was transferred into a teflon-lined stainless steel autoclave 50 mL and hydrothermal growth was carried out at 120 °C for 18 h','3.2.1. Synthesis of ZnO Using CTAB (Constant) and SDS (Variant)',20216,20385);
INSERT INTO "steps" VALUES(5060,4061,5,'cool','Let the autoclaves cool down after treatment.','After treatment, the autoclaves were allowed to cool down','3.2.1. Synthesis of ZnO Using CTAB (Constant) and SDS (Variant)',20387,20444);
INSERT INTO "steps" VALUES(5061,4061,6,'centrifuge','Collect the white precipitates and centrifuge them; discard the supernatant.','the white precipitates were collected, centrifuged at 40,000 (× g) for 10 min and supernatant was discarded','3.2.1. Synthesis of ZnO Using CTAB (Constant) and SDS (Variant)',20449,20556);
INSERT INTO "steps" VALUES(5062,4061,7,'wash','Wash the particles with ethanol and distilled water to remove impurities.','The obtained particles were washed three times with ethanol and distilled water','3.2.1. Synthesis of ZnO Using CTAB (Constant) and SDS (Variant)',20558,20637);
INSERT INTO "steps" VALUES(5063,4061,8,'dry','Dry the washed particles.','dried at 60 °C for 24 h','3.2.1. Synthesis of ZnO Using CTAB (Constant) and SDS (Variant)',20673,20696);
INSERT INTO "steps" VALUES(5064,4069,1,'add','Add zinc acetate and NaOH to distilled water and stir the solution.','Firstly 1 g zinc acetate (Zn(Ac)2 2H2O) and 1.12 g NaOH were added in 25 mL distilled water and the solution was stirred.','3.2.2. Synthesis of ZnO Using SDS (Constant) and CTAB (Variant)',20765,20886);
INSERT INTO "steps" VALUES(5065,4069,2,'stir','Keep stirring the solution before adding SDS.','After 1 h, 0.1 g SDS was added to the solution.','3.2.2. Synthesis of ZnO Using SDS (Constant) and CTAB (Variant)',20887,20934);
INSERT INTO "steps" VALUES(5066,4069,3,'add','Add SDS to the solution.','After 1 h, 0.1 g SDS was added to the solution.','3.2.2. Synthesis of ZnO Using SDS (Constant) and CTAB (Variant)',20887,20934);
INSERT INTO "steps" VALUES(5067,4069,4,'add','Add a certain amount of CTAB so that the SDS:CTAB molar ratio takes the tested value (1:0 for this sample, i.e. no CTAB).','certain amount of CTAB was added to above solution so that the molar ratio of SDS:CTAB was set to 1:0, 1:0.5, 1:1, 1:1.5 and 1:2','3.2.2. Synthesis of ZnO Using SDS (Constant) and CTAB (Variant)',20941,21069);
INSERT INTO "steps" VALUES(5068,4069,5,'heat','Hydrothermal growth in a Teflon-lined stainless steel autoclave (rest of the process same as in the CTAB-constant synthesis).','solution with white flocculent precipitate was transferred into a teflon-lined stainless steel autoclave 50 mL and hydrothermal growth was carried out at 120 °C for 18 h','3.2.1. Synthesis of ZnO Using CTAB (Constant) and SDS (Variant)',20216,20385);
INSERT INTO "steps" VALUES(5069,4069,6,'cool','Let the autoclaves cool down after treatment.','After treatment, the autoclaves were allowed to cool down','3.2.1. Synthesis of ZnO Using CTAB (Constant) and SDS (Variant)',20387,20444);
INSERT INTO "steps" VALUES(5070,4069,7,'centrifuge','Collect the white precipitates and centrifuge them; discard the supernatant.','the white precipitates were collected, centrifuged at 40,000 (× g) for 10 min and supernatant was discarded','3.2.1. Synthesis of ZnO Using CTAB (Constant) and SDS (Variant)',20449,20556);
INSERT INTO "steps" VALUES(5071,4069,8,'wash','Wash the particles with ethanol and distilled water to remove impurities.','The obtained particles were washed three times with ethanol and distilled water','3.2.1. Synthesis of ZnO Using CTAB (Constant) and SDS (Variant)',20558,20637);
INSERT INTO "steps" VALUES(5072,4069,9,'dry','Dry the washed particles.','dried at 60 °C for 24 h','3.2.1. Synthesis of ZnO Using CTAB (Constant) and SDS (Variant)',20673,20696);
INSERT INTO "steps" VALUES(5073,4070,1,'calcine','Calcine the as-synthesised ZnO-SDS powder at 500 °C.','The as-synthesised ZnO-SDS nanoparticles calcined at 500 °C shows no significant difference compared with that of the uncalcined one.','2.2. Morphology',5730,5863);
INSERT INTO "steps" VALUES(5074,4077,1,'calcine','Calcine the as-produced ZnO powder at 500 °C for 5 h.','FTIR spectra of as-produced ZnO samples at different mole ratios of (A) SDS:CTAB = 1:0.5 and (B) CTAB:SDS = 1:1 before and after the calcinations at 500 °C for 5 h.','Figure captions',26302,26466);
INSERT INTO "steps" VALUES(5075,4078,1,'calcine','Calcine the as-produced ZnO powder at 500 °C for 5 h.','FTIR spectra of as-produced ZnO samples at different mole ratios of (A) SDS:CTAB = 1:0.5 and (B) CTAB:SDS = 1:1 before and after the calcinations at 500 °C for 5 h.','Figure captions',26302,26466);
INSERT INTO "steps" VALUES(5076,4079,1,'degas','Degas formamidinium acetate, oleic acid and 1-octadecene in a three-necked flask under vacuum, first at room temperature then at 50 °C.','In a three-necked round-bottom flask, 15 mmol (1.563 g) of FA-acetate, 15 mL of OA, and 15 mL of ODE were degassed under a vacuum at room temperature and 50 °C for 30 min, respectively.','Synthesis of FA-Oleate Precursor',23814,23999);
INSERT INTO "steps" VALUES(5077,4079,2,'heat','Heat the FA-acetate / oleic acid / 1-octadecene mixture under N2 to form the FA-oleate stock solution and hold it at that temperature.','The temperature was then increased to 120 °C under N2 and kept at this temperature.','Synthesis of FA-Oleate Precursor',24000,24083);
INSERT INTO "steps" VALUES(5078,4079,3,'degas','Degas PbBr2 and 1-octadecene in a three-necked flask under vacuum, first at room temperature then at 120 °C.','In a three-necked round-bottom flask, 0.74 mmol (0.272 g) of PbBr2 and 25 mL of 1-ODE were degassed under vacuum at room temperature and 120 °C for 30 min, respectively.','Synthesis of FAPbBr3 NCs',24112,24281);
INSERT INTO "steps" VALUES(5079,4079,4,'add','Inject the preheated oleic acid and amine-ligand mixture (given ratio of (R)-2-octylamine to oleylamine) into the PbBr2 mixture under vacuum until the PbBr2 is dissolved and the solution is clear.','Mixtures of 12.1 mmol (4 mL) of OA and 6.05 mmol of amine ligands with different ratios of (R)-2-octylamine to OAm (1:0, 0.5:0.5, 0.25:0.75, 0:1) were preheated to 120 °C, then injected into the PbBr2 mixture under vacuum.','Synthesis of FAPbBr3 NCs',24282,24504);
INSERT INTO "steps" VALUES(5080,4079,5,'cool','Lower the temperature of the clear PbBr2 solution before injection to avoid rapid crystal growth.','Then the temperature of the solution was reduced to 80 °C to prevent rapid growth of FAPbBr3 crystals.','Synthesis of FAPbBr3 NCs',24565,24667);
INSERT INTO "steps" VALUES(5081,4079,6,'add','Swiftly inject the FA-oleate stock solution into the PbBr2 mixture under N2 flow (hot injection).','Under N2 flow, 5 mL of the FA-oleate stock solution was swiftly injected into the PbBr2 mixture, which was then quenched by immersing the flask in an ice bath.','Synthesis of FAPbBr3 NCs',24668,24827);
INSERT INTO "steps" VALUES(5082,4079,7,'quench','Quench the reaction by immersing the flask in an ice bath.','which was then quenched by immersing the flask in an ice bath.','Synthesis of FAPbBr3 NCs',24765,24827);
INSERT INTO "steps" VALUES(5083,4079,8,'centrifuge','Centrifuge the cooled solution to remove unreacted ligands and 1-octadecene.','After cooling to room temperature, the solution was centrifuged at 7500 rpm for 5 min to remove unreacted ligands and 1-ODE.','Synthesis of FAPbBr3 NCs',24828,24952);
INSERT INTO "steps" VALUES(5084,4079,9,'centrifuge','Disperse the precipitate in hexane and centrifuge again to remove the large precipitated particles.','The precipitate was dispersed in 5 mL of hexane, then centrifuged at 7500 rpm for 5 min to remove the precipitated large particles.','Synthesis of FAPbBr3 NCs',24953,25084);
INSERT INTO "steps" VALUES(5085,4079,10,'collect','Keep the supernatant NC solution in a refrigerator.','The supernatant NC solution was stored in a refrigerator.','Synthesis of FAPbBr3 NCs',25085,25142);
INSERT INTO "steps" VALUES(5086,4083,1,'mix','Place methylbenzylamine and ethanol in a flask in an ice bath.','In a one-necked round-bottom flask in an ice bath, 78 mmol (10 mL) of R-,S-MBA and 30 mL of ethanol were added','Synthesis of R-,S-MBA:Br',25171,25281);
INSERT INTO "steps" VALUES(5087,4083,2,'add','Add aqueous HBr dropwise under vigorous stirring.','then 116 mmol (13.2 mL) of HBr aqueous solution was added dropwise into the flask under vigorous stirring.','Synthesis of R-,S-MBA:Br',25283,25389);
INSERT INTO "steps" VALUES(5088,4083,3,'stir','Keep the solution stirring in the ice bath overnight.','The solution was kept stirring in an ice bath overnight.','Synthesis of R-,S-MBA:Br',25390,25446);
INSERT INTO "steps" VALUES(5089,4083,4,'collect','Collect the yellowish precipitate by evaporating the solvents.','The yellowish precipitate was collected by evaporation of solvents at 70 °C for 30 min','Synthesis of R-,S-MBA:Br',25447,25533);
INSERT INTO "steps" VALUES(5090,4083,5,'wash','Wash by repeated redissolution in ethanol and recrystallisation in diethyl ether until the solid is colorless.','then washed thoroughly by repeated redissolution in ethanol and recrystallization in diethyl ether until colorless.','Synthesis of R-,S-MBA:Br',25535,25650);
INSERT INTO "steps" VALUES(5091,4083,6,'recrystallize','Dissolve the white precipitate in a little hot ethanol to make a saturated solution and recrystallise it in a freezer.','The white precipitate was dissolved in a small amount of hot ethanol to make a saturated solution, then recrystallized in a freezer','Synthesis of R-,S-MBA:Br',25651,25782);
INSERT INTO "steps" VALUES(5092,4083,7,'dry','Dry the recrystallised product under vacuum.','The recrystallized precipitate was dried under vacuum overnight.','Synthesis of R-,S-MBA:Br',25897,25961);
INSERT INTO "steps" VALUES(5093,4084,1,'add','Add methyl acetate (antisolvent) to the NC stock solution.','To purify the FAPbBr3 NCs, 10 mL of MeOAc was added to 5 mL of a stock solution; then it was centrifuged at 7500 rpm for 5 min.','Purification and Ligand Treatment of FAPbBr3 NCs',26014,26141);
INSERT INTO "steps" VALUES(5094,4084,2,'centrifuge','Centrifuge the MeOAc / NC mixture and keep the precipitate.','To purify the FAPbBr3 NCs, 10 mL of MeOAc was added to 5 mL of a stock solution; then it was centrifuged at 7500 rpm for 5 min.','Purification and Ligand Treatment of FAPbBr3 NCs',26014,26141);
INSERT INTO "steps" VALUES(5095,4084,3,'centrifuge','Redisperse the precipitate in hexane and centrifuge again to discard aggregated particles.','The resulting precipitate was redispersed in 5 mL of hexane and centrifuged again at 7500 rpm for 5 min to discard the aggregated particles.','Purification and Ligand Treatment of FAPbBr3 NCs',26142,26282);
INSERT INTO "steps" VALUES(5096,4085,1,'add','Add methyl acetate (antisolvent) to the NC stock solution.','To purify the FAPbBr3 NCs, 10 mL of MeOAc was added to 5 mL of a stock solution; then it was centrifuged at 7500 rpm for 5 min.','Purification and Ligand Treatment of FAPbBr3 NCs',26014,26141);
INSERT INTO "steps" VALUES(5097,4085,2,'centrifuge','Centrifuge the MeOAc / NC mixture and keep the precipitate.','To purify the FAPbBr3 NCs, 10 mL of MeOAc was added to 5 mL of a stock solution; then it was centrifuged at 7500 rpm for 5 min.','Purification and Ligand Treatment of FAPbBr3 NCs',26014,26141);
INSERT INTO "steps" VALUES(5098,4085,3,'centrifuge','Redisperse the precipitate in hexane and centrifuge again to discard aggregated particles.','The resulting precipitate was redispersed in 5 mL of hexane and centrifuged again at 7500 rpm for 5 min to discard the aggregated particles.','Purification and Ligand Treatment of FAPbBr3 NCs',26142,26282);
INSERT INTO "steps" VALUES(5099,4085,4,'sonicate','Prepare a saturated solution of the chiral ligand in ethyl acetate by sonication.','a saturated solution of R-,S-MBA:Br in EtOAc was prepared by sonicating 200 mg of R-,S-MBA:Br in 20 mL of EtOAc','Purification and Ligand Treatment of FAPbBr3 NCs',26331,26442);
INSERT INTO "steps" VALUES(5100,4085,5,'centrifuge','Centrifuge the sonicated suspension to remove undissolved solid.','a saturated solution of R-,S-MBA:Br in EtOAc was prepared by sonicating 200 mg of R-,S-MBA:Br in 20 mL of EtOAc, then centrifuging at 3500 rpm for 5 min.','Purification and Ligand Treatment of FAPbBr3 NCs',26331,26484);
INSERT INTO "steps" VALUES(5101,4085,6,'mix','Mix the saturated ligand solution with the purified NCs and stir mildly at room temperature.','The 1 mL of saturated R-,S-MBA:Br solution was mixed with 5 mL of purified FAPbBr3 NCs; the mixture was stirred mildly for 5 min at room temperature','Purification and Ligand Treatment of FAPbBr3 NCs',26485,26633);
INSERT INTO "steps" VALUES(5102,4085,7,'centrifuge','Centrifuge to precipitate aggregated particles and collect the supernatant (treated NCs).','the mixture was stirred mildly for 5 min at room temperature and then centrifuged at 7500 rpm for 5 min to precipitate the aggregated particles; the supernatant was collected.','Purification and Ligand Treatment of FAPbBr3 NCs',26573,26748);
INSERT INTO "steps" VALUES(5103,4087,1,'dissolve','Dissolve cobalt nitrate hexahydrate and lithium nitrate in deionized water at a Li:Co molar ratio of 1.05:1.','The nitrate precursor was formulated by dissolving cobalt nitrate hexahydrate [Co(NO3)2·6H2O, Thermo Scientific] and lithium nitrate [LiNO3, Thermo Scientific] in deionized water, achieving a Li:Co molar ratio of 1.05:1.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',8850,9070);
INSERT INTO "steps" VALUES(5104,4087,2,'atomize','Atomize the precursor solution into fine aerosol droplets with a quartz nebulizer.','A quartz nebulizer atomized the precursor solutions into fine aerosol droplets, subsequently vaporized in a stainless steel preheating section.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9712,9855);
INSERT INTO "steps" VALUES(5105,4087,3,'heat','Vaporize the droplets in the stainless steel preheating section under a nitrogen flow.','This section operated at an uptake rate of 1 m/min and was coupled with a nitrogen flow rate of 1 L/min (99.998% purity, BOC), with the preheating temperature regulated at 400 °C to ensure thorough vaporization.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9856,10067);
INSERT INTO "steps" VALUES(5106,4087,4,'react','Pyrolysis of the dried droplets in the heated section of a quartz tube furnace; the temperature is the set point, which is the peak of a parabolic axial furnace profile.','Postvaporization, the dried droplets were directed into a tube furnace (quartz tube).','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10298,10383);
INSERT INTO "steps" VALUES(5107,4087,5,'quench','Quench the decomposed particles with an air flow.','The quenching section, employing an air flow rate of 30 L/min, reduced the temperature of the decomposed particles, which had partially transformed into oxides (discussed further below), to below 150 °C before collecting them in a filter bag.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10636,10878);
INSERT INTO "steps" VALUES(5108,4087,6,'collect','Collect the particles in a filter bag fitted with a HEPA filter at the end of the housing.','before collecting them in a filter bag','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10839,10877);
INSERT INTO "steps" VALUES(5109,4087,7,'anneal','Anneal about 2 g of collected particles in an alumina crucible inside a second tube furnace under airflow, at 775 °C for 1 h.','For the purpose of achieving a higher crystalline layered structure, the collected particles (approximately 2 g) with promising structure and morphology were annealed in an alumina crucible.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10996,11186);
INSERT INTO "steps" VALUES(5110,4094,1,'dissolve','Dissolve cobalt nitrate hexahydrate and lithium nitrate in deionized water at a Li:Co molar ratio of 1.05:1.','The nitrate precursor was formulated by dissolving cobalt nitrate hexahydrate [Co(NO3)2·6H2O, Thermo Scientific] and lithium nitrate [LiNO3, Thermo Scientific] in deionized water, achieving a Li:Co molar ratio of 1.05:1.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',8850,9070);
INSERT INTO "steps" VALUES(5111,4094,2,'atomize','Atomize the precursor solution into fine aerosol droplets with a quartz nebulizer.','A quartz nebulizer atomized the precursor solutions into fine aerosol droplets, subsequently vaporized in a stainless steel preheating section.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9712,9855);
INSERT INTO "steps" VALUES(5112,4094,3,'heat','Vaporize the droplets in the stainless steel preheating section under a nitrogen flow.','This section operated at an uptake rate of 1 m/min and was coupled with a nitrogen flow rate of 1 L/min (99.998% purity, BOC), with the preheating temperature regulated at 400 °C to ensure thorough vaporization.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9856,10067);
INSERT INTO "steps" VALUES(5113,4094,4,'react','Pyrolysis of the dried droplets in the heated section of a quartz tube furnace; the temperature is the set point, which is the peak of a parabolic axial furnace profile.','Postvaporization, the dried droplets were directed into a tube furnace (quartz tube).','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10298,10383);
INSERT INTO "steps" VALUES(5114,4094,5,'quench','Quench the decomposed particles with an air flow.','The quenching section, employing an air flow rate of 30 L/min, reduced the temperature of the decomposed particles, which had partially transformed into oxides (discussed further below), to below 150 °C before collecting them in a filter bag.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10636,10878);
INSERT INTO "steps" VALUES(5115,4094,6,'collect','Collect the as-synthesized particles in a filter bag fitted with a HEPA filter at the end of the housing; no annealing.','before collecting them in a filter bag','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10839,10877);
INSERT INTO "steps" VALUES(5116,4102,1,'dissolve','Dissolve cobalt(II) acetate tetrahydrate and lithium acetate dihydrate in deionized water, with the same metal ratio, concentration and lithium excess as the nitrate solution.','In parallel, the acetate precursor was prepared by dissolving cobalt(II) acetate tetrahydrate [C4H6CoO4·4H2O, Acros Organics] and lithium acetate dihydrate [C2H3LiO2·2H2O, Acros Organics] in deionized water, ensuring the same metal ratios, concentration, and excess lithium were preserved.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9214,9503);
INSERT INTO "steps" VALUES(5117,4102,2,'atomize','Atomize the precursor solution into fine aerosol droplets with a quartz nebulizer.','A quartz nebulizer atomized the precursor solutions into fine aerosol droplets, subsequently vaporized in a stainless steel preheating section.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9712,9855);
INSERT INTO "steps" VALUES(5118,4102,3,'heat','Vaporize the droplets in the stainless steel preheating section under a nitrogen flow.','This section operated at an uptake rate of 1 m/min and was coupled with a nitrogen flow rate of 1 L/min (99.998% purity, BOC), with the preheating temperature regulated at 400 °C to ensure thorough vaporization.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9856,10067);
INSERT INTO "steps" VALUES(5119,4102,4,'react','Pyrolysis of the dried droplets in the heated section of a quartz tube furnace; the temperature is the set point, which is the peak of a parabolic axial furnace profile.','Postvaporization, the dried droplets were directed into a tube furnace (quartz tube).','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10298,10383);
INSERT INTO "steps" VALUES(5120,4102,5,'quench','Quench the decomposed particles with an air flow.','The quenching section, employing an air flow rate of 30 L/min, reduced the temperature of the decomposed particles, which had partially transformed into oxides (discussed further below), to below 150 °C before collecting them in a filter bag.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10636,10878);
INSERT INTO "steps" VALUES(5121,4102,6,'collect','Collect the particles in a filter bag fitted with a HEPA filter at the end of the housing.','before collecting them in a filter bag','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10839,10877);
INSERT INTO "steps" VALUES(5122,4102,7,'anneal','Anneal about 2 g of collected particles in an alumina crucible inside a second tube furnace under airflow, at 750 °C for 3 h.','For the purpose of achieving a higher crystalline layered structure, the collected particles (approximately 2 g) with promising structure and morphology were annealed in an alumina crucible.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10996,11186);
INSERT INTO "steps" VALUES(5123,4107,1,'dissolve','Dissolve cobalt(II) acetate tetrahydrate and lithium acetate dihydrate in deionized water, with the same metal ratio, concentration and lithium excess as the nitrate solution.','In parallel, the acetate precursor was prepared by dissolving cobalt(II) acetate tetrahydrate [C4H6CoO4·4H2O, Acros Organics] and lithium acetate dihydrate [C2H3LiO2·2H2O, Acros Organics] in deionized water, ensuring the same metal ratios, concentration, and excess lithium were preserved.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9214,9503);
INSERT INTO "steps" VALUES(5124,4107,2,'atomize','Atomize the precursor solution into fine aerosol droplets with a quartz nebulizer.','A quartz nebulizer atomized the precursor solutions into fine aerosol droplets, subsequently vaporized in a stainless steel preheating section.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9712,9855);
INSERT INTO "steps" VALUES(5125,4107,3,'heat','Vaporize the droplets in the stainless steel preheating section under a nitrogen flow.','This section operated at an uptake rate of 1 m/min and was coupled with a nitrogen flow rate of 1 L/min (99.998% purity, BOC), with the preheating temperature regulated at 400 °C to ensure thorough vaporization.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',9856,10067);
INSERT INTO "steps" VALUES(5126,4107,4,'react','Pyrolysis of the dried droplets in the heated section of a quartz tube furnace; the temperature is the set point, which is the peak of a parabolic axial furnace profile.','Postvaporization, the dried droplets were directed into a tube furnace (quartz tube).','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10298,10383);
INSERT INTO "steps" VALUES(5127,4107,5,'quench','Quench the decomposed particles with an air flow.','The quenching section, employing an air flow rate of 30 L/min, reduced the temperature of the decomposed particles, which had partially transformed into oxides (discussed further below), to below 150 °C before collecting them in a filter bag.','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10636,10878);
INSERT INTO "steps" VALUES(5128,4107,6,'collect','Collect the as-synthesized particles in a filter bag fitted with a HEPA filter at the end of the housing; no annealing.','before collecting them in a filter bag','Synthesis of LiCoO2 via Spray Pyrolysis Reactor',10839,10877);
INSERT INTO "steps" VALUES(5129,4114,1,'dissolve','Dissolve the PVDF in NMP to adjust the viscosity of the slurry.','PVDF was dissolved in N-methyl-2-pyrrolidone (NMP) to fine-tune the slurry’s viscosity, ensuring optimal electrode coating quality.','Coin Cell Assembly and Electrochemical Tests',11658,11789);
INSERT INTO "steps" VALUES(5130,4114,2,'mix','Blend the active material, Super-P and PVDF solution (weight ratio 90:5:5) in a Thinky mixer at 2000 rpm.','The mixture was blended at 2000 rpm in a Thinky mixer','Coin Cell Assembly and Electrochemical Tests',11790,11843);
INSERT INTO "steps" VALUES(5131,4114,3,'deposit','Cast the slurry onto aluminum foil with a linear coater.','cast onto aluminum foil using a linear coater set to a 150 μm gap','Coin Cell Assembly and Electrochemical Tests',11845,11910);
INSERT INTO "steps" VALUES(5132,4114,4,'dry','Dry the cast electrode film at 120 °C for 30 min.','and dried at 120 °C for 30 min','Coin Cell Assembly and Electrochemical Tests',11912,11942);
INSERT INTO "steps" VALUES(5133,4114,5,'cut','Shape the electrode into 13 mm discs.','The electrodes, shaped into 13 mm discs, were dried overnight in a vacuum oven at the same temperature.','Coin Cell Assembly and Electrochemical Tests',11944,12047);
INSERT INTO "steps" VALUES(5134,4114,6,'dry','Dry the electrode discs overnight in a vacuum oven, at the same temperature as the first drying.','The electrodes, shaped into 13 mm discs, were dried overnight in a vacuum oven at the same temperature.','Coin Cell Assembly and Electrochemical Tests',11944,12047);
INSERT INTO "steps" VALUES(5135,4114,7,'assemble','Assemble CR2032 coin cells in an argon-filled glovebox with a Li metal disc, a Celgard separator and LP40 electrolyte.','CR2032 coin cells were assembled in an argon-filled glovebox, each containing a 15 mm Li metal disc counter electrode, a 19 mm diameter Celgard separator, and filled with 20 μL of LP40 electrolyte (1 M LiPF6 in EC/DEC, 1:1 v/v).','Coin Cell Assembly and Electrochemical Tests',12048,12276);
INSERT INTO "steps" VALUES(5136,4114,8,'crimp','Crimp the coin cells at 1000 psi.','Cells were crimped at 1000 psi and underwent electrochemical testing','Coin Cell Assembly and Electrochemical Tests',12277,12345);
INSERT INTO "steps" VALUES(5137,4115,1,'mix','Mix the acetate-derived LCO, Super P and PVDF (80:10:10) into a slurry.','This slurry was mixed, cast, dried, and calendared to enhance the electrode’s structural integrity and ensure effective electrolyte infiltration.','Coin Cell Assembly and Electrochemical Tests',12667,12812);
INSERT INTO "steps" VALUES(5138,4115,2,'deposit','Cast the slurry.','This slurry was mixed, cast, dried, and calendared to enhance the electrode’s structural integrity and ensure effective electrolyte infiltration.','Coin Cell Assembly and Electrochemical Tests',12667,12812);
INSERT INTO "steps" VALUES(5139,4115,3,'dry','Dry the cast electrode.','This slurry was mixed, cast, dried, and calendared to enhance the electrode’s structural integrity and ensure effective electrolyte infiltration.','Coin Cell Assembly and Electrochemical Tests',12667,12812);
INSERT INTO "steps" VALUES(5140,4115,4,'calender','Calender the dried electrode to improve its structural integrity and electrolyte infiltration.','This slurry was mixed, cast, dried, and calendared to enhance the electrode’s structural integrity and ensure effective electrolyte infiltration.','Coin Cell Assembly and Electrochemical Tests',12667,12812);
INSERT INTO "steps" VALUES(5141,4115,5,'cut','Punch the processed electrodes into 14 mm discs.','The processed electrodes were punched into 14 mm discs','Coin Cell Assembly and Electrochemical Tests',12813,12867);
INSERT INTO "steps" VALUES(5142,4115,6,'assemble','Assemble 2032-type coin cells with an 18 mm Celgard separator and 80 μL of electrolyte.','The processed electrodes were punched into 14 mm discs and assembled into 2032-type coin cells, incorporating an 18 mm Celgard separator and 80 μL of 1.3 M LiPF6 electrolyte in EC:DEC (3:7 wt/wt), tailored for the electrode’s specific needs.','Coin Cell Assembly and Electrochemical Tests',12813,13054);
INSERT INTO "steps" VALUES(5143,4115,7,'crimp','Crimp the coin cells at 700 psi.','Crimped at 700 psi, the cells were conditioned for 8 h before being subjected to formation cycling at 0.1C, stability tests at 0.5C, and rate capability assessments ranging from 0.5C to 20C.','Coin Cell Assembly and Electrochemical Tests',13055,13245);
INSERT INTO "steps" VALUES(5144,4115,8,'age','Condition the crimped cells for 8 h before the electrochemical tests.','Crimped at 700 psi, the cells were conditioned for 8 h before being subjected to formation cycling at 0.1C, stability tests at 0.5C, and rate capability assessments ranging from 0.5C to 20C.','Coin Cell Assembly and Electrochemical Tests',13055,13245);
INSERT INTO "steps" VALUES(5145,4116,1,'react','Synthesis of salicylaldimine: APTES, salicylaldehyde and ethanol reacted in a flask.','8.85 g (39.98 mmoL) of APTES, 4.88 g (39.96 mmoL) of salicylaldehyde, and 100 mL of ethanol were added to a flask and reacted at 95 °C for 3 h','2.2.1. Preparation of Salicylaldimine',8251,8393);
INSERT INTO "steps" VALUES(5146,4116,2,'evaporate','Remove ethanol by rotary evaporation.','After removing ethanol with rotary evaporation','2.2.1. Preparation of Salicylaldimine',8395,8441);
INSERT INTO "steps" VALUES(5147,4116,3,'dissolve','Dissolve the intermediate product in dichloromethane.','the intermediate products were dissolved in 10 mL (156.01 mmoL) of dichloromethane','2.2.1. Preparation of Salicylaldimine',8443,8525);
INSERT INTO "steps" VALUES(5148,4116,4,'wash','Wash the product with deionized water.','the product was washed with deionized water three times','2.2.1. Preparation of Salicylaldimine',8533,8588);
INSERT INTO "steps" VALUES(5149,4116,5,'age','Leave the mixture to stand.','After being left to stand for 12 h','2.2.1. Preparation of Salicylaldimine',8590,8624);
INSERT INTO "steps" VALUES(5150,4116,6,'extract','Extract the organic layer.','the organic layer was extracted','2.2.1. Preparation of Salicylaldimine',8626,8657);
INSERT INTO "steps" VALUES(5151,4116,7,'dry','Remove residual water with anhydrous magnesium sulfate.','0.5 g (4.15 mmoL) anhydrous magnesium sulfate was used to remove the residual water','2.2.1. Preparation of Salicylaldimine',8663,8746);
INSERT INTO "steps" VALUES(5152,4116,8,'filter','Filter off magnesium sulfate and dichloromethane to obtain salicylaldimine.','the final product was filtered to remove dichloromethane and magnesium sulfate to obtain salicylaldimine','2.2.1. Preparation of Salicylaldimine',8757,8861);
INSERT INTO "steps" VALUES(5153,4116,9,'dissolve','Dissolve CTAB, ammonia solution and deionized water in the flask with stirring.','a total of 1.5 g (4.12 mmoL) of CTAB, 105 mL of ammonia solution (wt = 25%), and 150 mL of deionized water were added to the flask to be completely dissolved at 60 °C with 1 h of stirring','2.2.2. Preparation of Salicylaldimine-Modified Mesoporous Silica (Sal-MCM)',9290,9477);
INSERT INTO "steps" VALUES(5154,4116,10,'add','Add TEOS dropwise to the solution.','7.5 g (35.28 mmoL) of TEOS was added to the solution dropwise','2.2.2. Preparation of Salicylaldimine-Modified Mesoporous Silica (Sal-MCM)',9485,9546);
INSERT INTO "steps" VALUES(5155,4116,11,'add','One hour after the TEOS addition, add the as-synthesized salicylaldimine.','After 1 h, 2.5 g of the as-synthesized salicylaldimine was added','2.2.2. Preparation of Salicylaldimine-Modified Mesoporous Silica (Sal-MCM)',9548,9612);
INSERT INTO "steps" VALUES(5156,4116,12,'stir','Stir the reaction mixture for a further period.','the reaction was stirred for another 6 h','2.2.2. Preparation of Salicylaldimine-Modified Mesoporous Silica (Sal-MCM)',9618,9658);
INSERT INTO "steps" VALUES(5157,4116,13,'age','Crystallization of the mixture.','being crystallized for 24 h at 30 °C','2.2.2. Preparation of Salicylaldimine-Modified Mesoporous Silica (Sal-MCM)',9666,9702);
INSERT INTO "steps" VALUES(5158,4116,14,'filter','Filter the solid.','filtered, washed, and dried at 80 °C','2.2.2. Preparation of Salicylaldimine-Modified Mesoporous Silica (Sal-MCM)',9704,9740);
INSERT INTO "steps" VALUES(5159,4116,15,'wash','Wash the solid (washing solvent not stated).','filtered, washed, and dried at 80 °C','2.2.2. Preparation of Salicylaldimine-Modified Mesoporous Silica (Sal-MCM)',9704,9740);
INSERT INTO "steps" VALUES(5160,4116,16,'dry','Dry the solid at 80 °C.','filtered, washed, and dried at 80 °C','2.2.2. Preparation of Salicylaldimine-Modified Mesoporous Silica (Sal-MCM)',9704,9740);
INSERT INTO "steps" VALUES(5161,4116,17,'reflux','Remove the CTAB template by reflux extraction with ethanol to obtain Sal-MCM-41.','the template was removed with 100 mL ethanol at 110 °C for 72 h by the mean of reflux extraction to obtain Sal-MCM-41','2.2.2. Preparation of Salicylaldimine-Modified Mesoporous Silica (Sal-MCM)',9751,9868);
INSERT INTO "steps" VALUES(5162,4116,18,'impregnate','Wet impregnation of Sal-MCM-41 with the zinc nitrate solution under stirring.','50 mL (100 mmoL) of zinc nitrate solution was added to 500 mg of Sal-MCM-41 or MCM-41 at 30 °C with stirring for 24 h','2.2.3. Preparation of Zinc Oxide Supported by Mesoporous Silica (ZnO-MCM)',10366,10483);
INSERT INTO "steps" VALUES(5163,4116,19,'filter','Filter the Zn-loaded solid to obtain Zn/Sal-MCM-41.','Zn/Sal-MCM-41 and Zn/MCM-41 was obtained after being filtered, washed, and dried','2.2.3. Preparation of Zinc Oxide Supported by Mesoporous Silica (ZnO-MCM)',10491,10571);
INSERT INTO "steps" VALUES(5164,4116,20,'wash','Wash the Zn-loaded solid (conditions not stated).','Zn/Sal-MCM-41 and Zn/MCM-41 was obtained after being filtered, washed, and dried','2.2.3. Preparation of Zinc Oxide Supported by Mesoporous Silica (ZnO-MCM)',10491,10571);
INSERT INTO "steps" VALUES(5165,4116,21,'dry','Dry the Zn-loaded solid (conditions not stated).','Zn/Sal-MCM-41 and Zn/MCM-41 was obtained after being filtered, washed, and dried','2.2.3. Preparation of Zinc Oxide Supported by Mesoporous Silica (ZnO-MCM)',10491,10571);
INSERT INTO "steps" VALUES(5166,4116,22,'calcine','Calcination in air converting Zn ions to ZnO and removing the salicylaldimine.','following calcination at 550 °C for 6 h in air, ZnO-MCM was obtained','2.2.3. Preparation of Zinc Oxide Supported by Mesoporous Silica (ZnO-MCM)',10582,10650);
INSERT INTO "steps" VALUES(5167,4118,1,'prepare','Preparation of MCM-41, the mesoporous silica without salicylaldimine modification: the article gives no procedure, reagents, quantities, temperatures or durations for this sample.','Additionally, mesoporous silica without salicylaldimine modification was synthesized and noted as MCM-41.','2.2.2. Preparation of Salicylaldimine-Modified Mesoporous Silica (Sal-MCM)',10068,10173);
INSERT INTO "steps" VALUES(5168,4118,2,'impregnate','Wet impregnation of MCM-41 with the zinc nitrate solution under stirring.','50 mL (100 mmoL) of zinc nitrate solution was added to 500 mg of Sal-MCM-41 or MCM-41 at 30 °C with stirring for 24 h','2.2.3. Preparation of Zinc Oxide Supported by Mesoporous Silica (ZnO-MCM)',10366,10483);
INSERT INTO "steps" VALUES(5169,4118,3,'filter','Filter the Zn-loaded solid to obtain Zn/MCM-41.','Zn/Sal-MCM-41 and Zn/MCM-41 was obtained after being filtered, washed, and dried','2.2.3. Preparation of Zinc Oxide Supported by Mesoporous Silica (ZnO-MCM)',10491,10571);
INSERT INTO "steps" VALUES(5170,4118,4,'wash','Wash the Zn-loaded solid (conditions not stated).','Zn/Sal-MCM-41 and Zn/MCM-41 was obtained after being filtered, washed, and dried','2.2.3. Preparation of Zinc Oxide Supported by Mesoporous Silica (ZnO-MCM)',10491,10571);
INSERT INTO "steps" VALUES(5171,4118,5,'dry','Dry the Zn-loaded solid (conditions not stated).','Zn/Sal-MCM-41 and Zn/MCM-41 was obtained after being filtered, washed, and dried','2.2.3. Preparation of Zinc Oxide Supported by Mesoporous Silica (ZnO-MCM)',10491,10571);
INSERT INTO "steps" VALUES(5172,4118,6,'calcine','Calcination in air converting Zn ions to ZnO.','following calcination at 550 °C for 6 h in air, ZnO-MCM was obtained','2.2.3. Preparation of Zinc Oxide Supported by Mesoporous Silica (ZnO-MCM)',10582,10650);
INSERT INTO "steps" VALUES(5173,4119,1,'anneal','Anneal the Fe foil under hydrogen to smoothen its surface before growth.','the Fe foil (Alfa Aesar) was annealed at 1,100 °C for 1 h to smoothen the Fe surface under a 10 s.c.c.m. hydrogen atmosphere','Synthesis of multi- and monolayer materials',27642,27766);
INSERT INTO "steps" VALUES(5174,4119,2,'deposit','Grow h-BN by supplying borazine vapour and hydrogen over the Fe foil.','borazine vapour and hydrogen with a rate of 0.1 and 10 s.c.c.m., respectively, were supplied at 1,100 °C for 30 min','Synthesis of multi- and monolayer materials',27785,27900);
INSERT INTO "steps" VALUES(5175,4119,3,'cool','Cool slowly down to 700 °C without supplying additional borazine, so that dissolved B and N segregate and precipitate at the surface.','different cooling rates (slow: 5 °C min−1, fast: 30 °C min−1) until 700 °C were applied','Synthesis of multi- and monolayer materials',27921,28008);
INSERT INTO "steps" VALUES(5176,4121,1,'anneal','Anneal the Cu foil under hydrogen.','copper foil (Alfa Aesar) was annealed at 1,040 °C for 30 min under a 10 s.c.c.m. hydrogen atmosphere','Synthesis of multi- and monolayer materials',28146,28246);
INSERT INTO "steps" VALUES(5177,4121,2,'deposit','First growth step with low methane flow to reduce the nucleation density.','then methane and hydrogen with a rate of 0.1 and 10 s.c.c.m., respectively, for 20 min was supplied to reduce the nucleation density','Synthesis of multi- and monolayer materials',28251,28383);
INSERT INTO "steps" VALUES(5178,4121,3,'deposit','Second growth step with higher methane flow to form a continuous graphene film.','followed by increasing the methane flow rate to 2 s.c.c.m. while maintaining the same flow rate of hydrogen to form a continuous graphene film','Synthesis of multi- and monolayer materials',28385,28527);
INSERT INTO "steps" VALUES(5179,4122,1,'deposit','CVD growth of monolayer MoS2 on a SiO2/Si substrate.','The growth of monolayers MoS2 and WSe2 was conducted at 750 °C for 10 min on a SiO2/Si substrate, respectively.','Synthesis of multi- and monolayer materials',28638,28749);
INSERT INTO "steps" VALUES(5180,4123,1,'deposit','CVD growth of monolayer WSe2 on a SiO2/Si substrate.','The growth of monolayers MoS2 and WSe2 was conducted at 750 °C for 10 min on a SiO2/Si substrate, respectively.','Synthesis of multi- and monolayer materials',28638,28749);
INSERT INTO "steps" VALUES(5181,4124,1,'spin_coat','Spin coat the h-BN/Fe sample with PMMA.','h-BN/Fe, graphene/Cu and MoS2 (or WSe2)/SiO2 were spin coated with PMMA (C4, Micro Chem) at 2,500 r.p.m. for 1 min and then dried in the oven at 80 °C for 30 min.','Transfer of multi- and monolayer materials',28972,29134);
INSERT INTO "steps" VALUES(5182,4124,2,'dry','Dry the PMMA-coated sample in an oven.','h-BN/Fe, graphene/Cu and MoS2 (or WSe2)/SiO2 were spin coated with PMMA (C4, Micro Chem) at 2,500 r.p.m. for 1 min and then dried in the oven at 80 °C for 30 min.','Transfer of multi- and monolayer materials',28972,29134);
INSERT INTO "steps" VALUES(5183,4124,3,'immerse','Immerse PMMA/h-BN/Fe in aqueous NaOH, the Fe foil acting as cathode.','The PMMA/h-BN/Fe was immersed in an aqueous solution of 0.1 M NaOH and used as a cathode.','Transfer of multi- and monolayer materials',29211,29300);
INSERT INTO "steps" VALUES(5184,4124,4,'delaminate','Delaminate PMMA/h-BN from the Fe foil by applying a voltage of 2 V.','PMMA/h-BN was delaminated from the Fe foil by applying a voltage of 2 V.','Transfer of multi- and monolayer materials',29301,29373);
INSERT INTO "steps" VALUES(5185,4124,5,'wash','Rinse the PMMA/h-BN film with distilled water.','After all PMMA/h-BN, PMMA/graphene and PMMA/MoS2 (or WSe2) films were rinsed with distilled water three times, the films were transferred onto the target substrate.','Transfer of multi- and monolayer materials',29590,29754);
INSERT INTO "steps" VALUES(5186,4124,6,'deposit','Transfer the film onto the target substrate.','After all PMMA/h-BN, PMMA/graphene and PMMA/MoS2 (or WSe2) films were rinsed with distilled water three times, the films were transferred onto the target substrate.','Transfer of multi- and monolayer materials',29590,29754);
INSERT INTO "steps" VALUES(5187,4124,7,'wash','Remove the PMMA with acetone.','The PMMA on 2D materials was removed by acetone and thermal annealing under forming gas at 450 °C.','Transfer of multi- and monolayer materials',29755,29853);
INSERT INTO "steps" VALUES(5188,4124,8,'anneal','Anneal the transferred film under forming gas to remove PMMA residues.','The PMMA on 2D materials was removed by acetone and thermal annealing under forming gas at 450 °C.','Transfer of multi- and monolayer materials',29755,29853);
INSERT INTO "steps" VALUES(5189,4125,1,'spin_coat','Spin coat the MoS2 (or WSe2)/SiO2 sample with PMMA.','h-BN/Fe, graphene/Cu and MoS2 (or WSe2)/SiO2 were spin coated with PMMA (C4, Micro Chem) at 2,500 r.p.m. for 1 min and then dried in the oven at 80 °C for 30 min.','Transfer of multi- and monolayer materials',28972,29134);
INSERT INTO "steps" VALUES(5190,4125,2,'dry','Dry the PMMA-coated sample in an oven.','h-BN/Fe, graphene/Cu and MoS2 (or WSe2)/SiO2 were spin coated with PMMA (C4, Micro Chem) at 2,500 r.p.m. for 1 min and then dried in the oven at 80 °C for 30 min.','Transfer of multi- and monolayer materials',28972,29134);
INSERT INTO "steps" VALUES(5191,4125,3,'immerse','Immerse PMMA/MoS2 (or WSe2)/SiO2 in 0.1 M KOH to detach the PMMA/MoS2 (or WSe2) film from the SiO2 substrate.','The PMMA/MoS2 (or WSe2)/SiO2 was immersed in 0.1 M KOH to detach the PMMA/MoS2 (or WSe2) film from the SiO2 substrate.','Transfer of multi- and monolayer materials',29374,29492);
INSERT INTO "steps" VALUES(5192,4125,4,'wash','Rinse the PMMA/h-BN film with distilled water.','After all PMMA/h-BN, PMMA/graphene and PMMA/MoS2 (or WSe2) films were rinsed with distilled water three times, the films were transferred onto the target substrate.','Transfer of multi- and monolayer materials',29590,29754);
INSERT INTO "steps" VALUES(5193,4125,5,'deposit','Transfer the film onto the target substrate.','After all PMMA/h-BN, PMMA/graphene and PMMA/MoS2 (or WSe2) films were rinsed with distilled water three times, the films were transferred onto the target substrate.','Transfer of multi- and monolayer materials',29590,29754);
INSERT INTO "steps" VALUES(5194,4125,6,'wash','Remove the PMMA with acetone.','The PMMA on 2D materials was removed by acetone and thermal annealing under forming gas at 450 °C.','Transfer of multi- and monolayer materials',29755,29853);
INSERT INTO "steps" VALUES(5195,4125,7,'anneal','Anneal the transferred film under forming gas to remove PMMA residues.','The PMMA on 2D materials was removed by acetone and thermal annealing under forming gas at 450 °C.','Transfer of multi- and monolayer materials',29755,29853);
INSERT INTO "steps" VALUES(5196,4126,1,'spin_coat','Spin coat the graphene/Cu sample with PMMA.','h-BN/Fe, graphene/Cu and MoS2 (or WSe2)/SiO2 were spin coated with PMMA (C4, Micro Chem) at 2,500 r.p.m. for 1 min and then dried in the oven at 80 °C for 30 min.','Transfer of multi- and monolayer materials',28972,29134);
INSERT INTO "steps" VALUES(5197,4126,2,'dry','Dry the PMMA-coated sample in an oven.','h-BN/Fe, graphene/Cu and MoS2 (or WSe2)/SiO2 were spin coated with PMMA (C4, Micro Chem) at 2,500 r.p.m. for 1 min and then dried in the oven at 80 °C for 30 min.','Transfer of multi- and monolayer materials',28972,29134);
INSERT INTO "steps" VALUES(5198,4126,3,'etch','Etch the Cu foil away with a copper etchant (wet-etching transfer).','For graphene, the conventional wet-etching transfer was used. Cu was etched by a copper etchant.','Transfer of multi- and monolayer materials',29493,29589);
INSERT INTO "steps" VALUES(5199,4126,4,'wash','Rinse the PMMA/h-BN film with distilled water.','After all PMMA/h-BN, PMMA/graphene and PMMA/MoS2 (or WSe2) films were rinsed with distilled water three times, the films were transferred onto the target substrate.','Transfer of multi- and monolayer materials',29590,29754);
INSERT INTO "steps" VALUES(5200,4126,5,'deposit','Transfer the film onto the target substrate.','After all PMMA/h-BN, PMMA/graphene and PMMA/MoS2 (or WSe2) films were rinsed with distilled water three times, the films were transferred onto the target substrate.','Transfer of multi- and monolayer materials',29590,29754);
INSERT INTO "steps" VALUES(5201,4126,6,'wash','Remove the PMMA with acetone.','The PMMA on 2D materials was removed by acetone and thermal annealing under forming gas at 450 °C.','Transfer of multi- and monolayer materials',29755,29853);
INSERT INTO "steps" VALUES(5202,4126,7,'anneal','Anneal the transferred film under forming gas to remove PMMA residues.','The PMMA on 2D materials was removed by acetone and thermal annealing under forming gas at 450 °C.','Transfer of multi- and monolayer materials',29755,29853);
INSERT INTO "steps" VALUES(5203,4127,1,'deposit','Pattern the Ti/Pt bottom electrodes by electron-beam lithography and lift-off on the SiO2 wafer.','First, non-oxidizing metal electrodes (10 nm Ti/20 nm Pt) were patterned by lift-off using electron-beam lithography onto a 1-μm thick thermally grown silicon dioxide wafer.','Device fabrication and analysis',30145,30318);
INSERT INTO "steps" VALUES(5204,4127,2,'deposit','Transfer the CVD h-BN film on top of the bottom electrodes as gate dielectric (standard transfer procedure).','Then CVD h-BN was transferred on-top as the gate dielectric following a standard transfer procedure and the second metal electrode (50 nm Pd) was deposited on-top forming a cross-bar structure.','Device fabrication and analysis',30319,30512);
INSERT INTO "steps" VALUES(5205,4127,3,'deposit','Deposit the 50 nm Pd top electrode to form a cross-bar structure (1 × 1 μm2 overlap for the breakdown devices).','Then CVD h-BN was transferred on-top as the gate dielectric following a standard transfer procedure and the second metal electrode (50 nm Pd) was deposited on-top forming a cross-bar structure.','Device fabrication and analysis',30319,30512);
INSERT INTO "steps" VALUES(5206,4129,1,'deposit','Transfer the large-area CVD h-BN film onto 300-nm-thick SiO2/Si wafers (see hBN_transfer_PMMA).','a large-area CVD h-BN film was first transferred onto 300-nm-thick SiO2/Si wafers','Device applications of multilayer h-BN',18216,18297);
INSERT INTO "steps" VALUES(5207,4129,2,'deposit','Transfer the single-crystalline CVD graphene onto the h-BN film (wet-etching transfer, see graphene_transfer_PMMA_Cu_etch).','For the CVD graphene devices, a large-area CVD h-BN film was first transferred onto 300-nm-thick SiO2/Si wafers, followed by the transfer of large-area single-crystalline CVD-grown graphene (SCG) on the top of a 15-nm-thick h-BN film (Supplementary Fig. 14).','Device applications of multilayer h-BN',18186,18444);
INSERT INTO "steps" VALUES(5208,4129,3,'deposit','Pattern Ti/Au ohmic contacts by e-beam lithography, electron-beam evaporation and lift-off.','Ohmic contacts (electron beam evaporated—1 nm Ti/30 nm Au) were patterned first using e-beam lithography and lift-off.','Device fabrication and analysis',30928,31046);
INSERT INTO "steps" VALUES(5209,4129,4,'etch','Isolate the graphene channel by oxygen plasma etching through a PMMA mask.','Electrical isolation was achieved using PMMA as a etch mask utilizing a reactive oxygen etching tool (Plasma-therm—50 W for 10 s).','Device fabrication and analysis',31047,31177);
INSERT INTO "steps" VALUES(5210,4132,1,'deposit','Transfer the CVD h-BN film onto the SiO2/Si substrate first (see hBN_transfer_PMMA).','For a graphene, MoS2 or WSe2 FET device, the h-BN film was first transferred, followed by transferring graphene, MoS2 or WSe2 on the h-BN substrate.','Transfer of multi- and monolayer materials',29854,30002);
INSERT INTO "steps" VALUES(5211,4132,2,'deposit','Transfer the monolayer MoS2 film onto the h-BN/SiO2/Si substrate (see MoS2_WSe2_transfer_PMMA_KOH).','For the MoS2 FET, after the MoS2 film was transferred to the h-BN/SiO2/Si substrate, the channel and electrode regime were defined using electron-beam lithography','Device fabrication and analysis',31178,31340);
INSERT INTO "steps" VALUES(5212,4132,3,'etch','Define the channel by electron-beam lithography and reactive ion etching with SF6.','plasma etching (reactive ion etching (RIE): SF6 10 s.c.c.m., 20 W, 10 s)','Device fabrication and analysis',31342,31414);
INSERT INTO "steps" VALUES(5213,4132,4,'deposit','Vacuum metallization with Pd/Au and lift-off to form the two-terminal FET.','vacuum metallization (Pd/Au, 10/30 nm and a lift-off process, to fabricate two-terminal FET','Device fabrication and analysis',31416,31507);
INSERT INTO "steps" VALUES(5214,4132,5,'anneal','Anneal the devices in vacuum to improve the electrode contact and remove oxygen-related groups from the MoS2 surface.','The devices were annealed at 150 °C for 2 h in 10−6 torr to improve the contact between the electrodes and MoS2, and also to remove any oxygen-related functional groups on the MoS2 surface.','Device fabrication and analysis',31509,31698);
INSERT INTO "steps" VALUES(5215,4136,1,'dissolve','Dissolve β-glucan in deionized water in a two-neck round-bottom flask at 65 °C, under stirring and nitrogen, with potassium persulfate as initiator.','The biopolymeric nanocomposites were prepared by dissolving 2 g β-glucan (BG) in deionized-water and transferred into round bottom two-neck flask heated at 65 °C with constant stirring under an inert nitrogen atmosphere with addition of 0.05 g potassium persulfate as initiator.','2.2. Bioactive Nanocomposite Scaffold Fabrication',7302,7580);
INSERT INTO "steps" VALUES(5216,4136,2,'add','Add acrylic acid (monomer) and the N,N''-methylene-bis-acrylamide crosslinker to the reaction medium.','After 30 min, 0.40 mL of AAc as monomer and N, N-MBA crosslinker (0.05 % of AAc) were added into reaction media.','2.2. Bioactive Nanocomposite Scaffold Fabrication',7581,7693);
INSERT INTO "steps" VALUES(5217,4136,3,'add','Add n-HAp powder gradually to the reaction medium.','After 45 min, (2.5 g) n-HAp powder was added gradually with continuous stirring for 3 h.','2.2. Bioactive Nanocomposite Scaffold Fabrication',7694,7782);
INSERT INTO "steps" VALUES(5218,4136,4,'stir','Stir continuously for 3 h (graft polymerization of AAc on β-glucan, HAp trapped in the polymer network).','After 45 min, (2.5 g) n-HAp powder was added gradually with continuous stirring for 3 h.','2.2. Bioactive Nanocomposite Scaffold Fabrication',7694,7782);
INSERT INTO "steps" VALUES(5219,4136,5,'cool','Remove N2 gas from the reaction medium and let it cool at ambient temperature.','N2 gas was removed from the reaction media, followed by cooling at ambient.','2.2. Bioactive Nanocomposite Scaffold Fabrication',7977,8052);
INSERT INTO "steps" VALUES(5220,4136,6,'filter','Filter the reaction suspension under vacuum to remove unreacted reactants.','The reaction suspension was filtered under vacuum to remove unreacted reactants and washed with deionized water later it dried at 55 °C overnight in the oven.','2.2. Bioactive Nanocomposite Scaffold Fabrication',8053,8211);
INSERT INTO "steps" VALUES(5221,4136,7,'wash','Wash the filtered powder with deionized water.','The reaction suspension was filtered under vacuum to remove unreacted reactants and washed with deionized water later it dried at 55 °C overnight in the oven.','2.2. Bioactive Nanocomposite Scaffold Fabrication',8053,8211);
INSERT INTO "steps" VALUES(5222,4136,8,'dry','Dry the washed powder in an oven overnight.','The reaction suspension was filtered under vacuum to remove unreacted reactants and washed with deionized water later it dried at 55 °C overnight in the oven.','2.2. Bioactive Nanocomposite Scaffold Fabrication',8053,8211);
INSERT INTO "steps" VALUES(5223,4136,9,'mix','Homogenize the nanocomposite powder in deionized water to form a slurry.','The bioactive nanocomposite powder (5 g) was homogenized into deionized-water (10 mL) to form slurry.','2.2. Bioactive Nanocomposite Scaffold Fabrication',8316,8417);
INSERT INTO "steps" VALUES(5224,4136,10,'freeze','Fill the slurry into cylindrical molds and keep it frozen.','Then slurry was filled into cylindrical molds (2 cm × 6 cm) and kept at −40 °C for 24 h.','2.2. Bioactive Nanocomposite Scaffold Fabrication',8418,8506);
INSERT INTO "steps" VALUES(5225,4136,11,'freeze_dry','Obtain the porous scaffolds by freeze drying.','The porous bioactive nanocomposite scaffolds were obtained by and freeze drying method.','2.2. Bioactive Nanocomposite Scaffold Fabrication',8507,8594);
INSERT INTO "steps" VALUES(5226,4136,12,'treat','Treat the scaffolds with aqueous NaOH, left at ambient.','The bioactive scaffolds were washed with deionized water after treating with 10 wt. % NaOHaq. The solution was kept at ambient for 5 min.','2.3. Deposition of Silver Particles on Bioactive Nanocomposite Scaffolds',8831,8968);
INSERT INTO "steps" VALUES(5227,4136,13,'wash','Wash the NaOH-treated scaffolds with deionized water.','The bioactive scaffolds were washed with deionized water after treating with 10 wt. % NaOHaq.','2.3. Deposition of Silver Particles on Bioactive Nanocomposite Scaffolds',8831,8924);
INSERT INTO "steps" VALUES(5228,4136,14,'dissolve','Prepare the silver nitrate solution; the concentration is the parameter varied between BNS1 to BNS4.','Initially, different concentrations of silver nitrate (AgNO3) solution was prepared from 0.15 to 0.60 M.','2.3. Deposition of Silver Particles on Bioactive Nanocomposite Scaffolds',8969,9073);
INSERT INTO "steps" VALUES(5229,4136,15,'add','Add aqua ammonia dropwise to the AgNO3 solution.','Dropwise aqua ammonia (25 wt. %) was added into AgNO3 solutions.','2.3. Deposition of Silver Particles on Bioactive Nanocomposite Scaffolds',9074,9138);
INSERT INTO "steps" VALUES(5230,4136,16,'stir','Stir until a clear [Ag(NH3)2]+ solution is obtained.','It was stirred to obtain a clear [Ag(NH3)2]+ solution.','2.3. Deposition of Silver Particles on Bioactive Nanocomposite Scaffolds',9139,9193);
INSERT INTO "steps" VALUES(5231,4136,17,'deposit','Dip the scaffolds into the [Ag(NH3)2]+ solution; the dip and drying cycle is repeated.','Then, scaffolds were dipped into the [Ag(NH3)2]+ solution for 20 s and oven-dried for 5 min at 100 °C.','2.3. Deposition of Silver Particles on Bioactive Nanocomposite Scaffolds',9194,9296);
INSERT INTO "steps" VALUES(5232,4136,18,'dry','Oven-dry the scaffolds after each dipping.','Then, scaffolds were dipped into the [Ag(NH3)2]+ solution for 20 s and oven-dried for 5 min at 100 °C.','2.3. Deposition of Silver Particles on Bioactive Nanocomposite Scaffolds',9194,9296);
INSERT INTO "steps" VALUES(5233,4136,19,'wash','Wash the Ag-coated scaffolds (solvent not specified).','Finally, Ag-coated bioactive nanocomposite scaffolds (BNS) were washed and dried as shown in the Figure 1.','2.3. Deposition of Silver Particles on Bioactive Nanocomposite Scaffolds',9371,9477);
INSERT INTO "steps" VALUES(5234,4136,20,'dry','Dry the Ag-coated scaffolds (conditions not specified).','Finally, Ag-coated bioactive nanocomposite scaffolds (BNS) were washed and dried as shown in the Figure 1.','2.3. Deposition of Silver Particles on Bioactive Nanocomposite Scaffolds',9371,9477);
INSERT INTO "steps" VALUES(5235,4140,1,'collect','Separate the oil from the walnut.','The oil was separated from walnut','Synthesis of Carbon Dots',4973,5006);
INSERT INTO "steps" VALUES(5236,4140,2,'filter','Pass the oil through Whatman filter paper to remove large particles.','passed through Whatman filter paper to eliminate large particles.','Synthesis of Carbon Dots',5011,5076);
INSERT INTO "steps" VALUES(5237,4140,3,'centrifuge','Centrifuge the filtered oil several times to clarify it.','The oil was then centrifuged for 15 min at 6000 rpm for five times.','Synthesis of Carbon Dots',5077,5144);
INSERT INTO "steps" VALUES(5238,4140,4,'heat','Hydrothermal treatment of the clear walnut oil in a Teflon-lined stainless steel autoclave heated in an oven.','Then, 30 ml of the clear walnut oil was transferred into a 100 mL Teflon-lined stainless steel laboratory autoclave and heated in an oven at temperature of 220°C for 24 h, and cooled to room temperature.','Synthesis of Carbon Dots',5145,5348);
INSERT INTO "steps" VALUES(5239,4140,5,'cool','Let the autoclave cool to room temperature.','and cooled to room temperature','Synthesis of Carbon Dots',5317,5347);
INSERT INTO "steps" VALUES(5240,4140,6,'centrifuge','Centrifuge the brownish solution to remove large or agglomerated particles and keep the supernatant containing the CQDs.','The brownish solution was centrifuged at 14000 rpm for 15 min for three times to remove large or agglomerated particles','Synthesis of Carbon Dots',5349,5468);
INSERT INTO "steps" VALUES(5241,4140,7,'filter','Purify the supernatant containing the CQDs through a membrane.','the supernatant containing CQDs was further purified using a 0.2 µm membrane','Synthesis of Carbon Dots',5473,5549);
INSERT INTO "steps" VALUES(5242,4141,1,'react','Culture of the Ganoderma neo-japonicum Imazeki KUM61076 mycelia on potato dextrose agar.','The mycelia were cultured on potato dextrose agar and incubated at 28°C ± 2°C for 7 days.','Culturing and maintenance of Ganoderma neo-japonicum',10147,10236);
INSERT INTO "steps" VALUES(5243,4141,2,'react','Transfer of the mycelia into glucose yeast malt peptone broth, incubation under agitation.','The inoculated medium was incubated at 28°C ± 2°C and agitated at 150 rpm for 10 days.','Culturing and maintenance of Ganoderma neo-japonicum',10308,10394);
INSERT INTO "steps" VALUES(5244,4141,3,'wash','Harvest the mycelia and wash them with distilled water.','After incubation, the mycelia were harvested and washed with distilled water.','Culturing and maintenance of Ganoderma neo-japonicum',10395,10472);
INSERT INTO "steps" VALUES(5245,4141,4,'dry','Freeze-dry the mycelia and store them at 4°C in air-tight containers.','The mycelia were freeze-dried and stored at 4°C in air-tight containers prior to use.','Culturing and maintenance of Ganoderma neo-japonicum',10473,10558);
INSERT INTO "steps" VALUES(5246,4141,5,'heat','Soak the freeze-dried mycelia in distilled water (ratio 1:20) and double-boil.','the freeze-dried mycelia were soaked in distilled water at a ratio of 1:20 and double-boiled for 30 minutes','Preparation of mycelia hot aqueous extract',10708,10815);
INSERT INTO "steps" VALUES(5247,4141,6,'cool','Leave the double-boiled mixture to cool.','left to cool and filtered through grade 4 Whatman filter paper','Preparation of mycelia hot aqueous extract',10817,10879);
INSERT INTO "steps" VALUES(5248,4141,7,'filter','Filter the cooled mixture through grade 4 Whatman filter paper.','left to cool and filtered through grade 4 Whatman filter paper','Preparation of mycelia hot aqueous extract',10817,10879);
INSERT INTO "steps" VALUES(5249,4141,8,'dry','Freeze-dry the hot aqueous extract and store it at 4°C in airtight containers.','The hot aqueous extract was then freeze-dried at −50°C ± 2°C for 48 hours and stored at 4°C in airtight containers.','Preparation of mycelia hot aqueous extract',10881,10996);
INSERT INTO "steps" VALUES(5250,4141,9,'mix','Mix the freeze-dried extract (1 mg/mL) with the aqueous 1 mM AgNO3 solution.','1 mg/mL of freeze-dried hot aqueous mushroom mycelia extract was mixed with an aqueous solution of 1 mM AgNO3 solution and kept at room temperature for 24 hours.','Synthesis of AgNPs',11250,11411);
INSERT INTO "steps" VALUES(5251,4141,10,'age','Keep the mixture at room temperature to reduce Ag+ to Ag0.','1 mg/mL of freeze-dried hot aqueous mushroom mycelia extract was mixed with an aqueous solution of 1 mM AgNO3 solution and kept at room temperature for 24 hours.','Synthesis of AgNPs',11250,11411);
INSERT INTO "steps" VALUES(5252,4142,1,'load','Place the silicon powder upstream and the carbon black powder downstream in an alumina boat, with a Si:C molar ratio of about 1:1.','The silicon powder was placed in the upstream and the carbon black powder in the downstream of an alumina boat (100 × 20 × 20 mm) with a silicon and carbon molar ratio of about 1:1.','Experimental Conditions',4988,5169);
INSERT INTO "steps" VALUES(5253,4142,2,'place','Put the boat in the center of the horizontal alumina tube of the furnace.','The alumina boat was then placed in the center of the reaction chamber (horizontal alumina tube).','Experimental Conditions',5170,5267);
INSERT INTO "steps" VALUES(5254,4142,3,'evacuate','Evacuate the chamber with a rotary vacuum pump before heating.','Before heating, the chamber was first evacuated to ~10 mTorr by a rotary vacuum pump.','Experimental Conditions',5268,5353);
INSERT INTO "steps" VALUES(5255,4142,4,'adjust','Bring the chamber to the working pressure with ultra pure argon and keep a continuous argon flow during the whole process.','Then, the chamber pressure was adjusted to the desired pressure level with ultra pure argon (Ar) gas (99.999%, Airgas, Radnor, PA).','Experimental Conditions',5354,5485);
INSERT INTO "steps" VALUES(5256,4142,5,'heat','Ramp the furnace from room temperature to the reaction temperature.','After that, the chamber was ramped from room temperature to 1,500°C (center position temperature) at a rate of 10°C/min','Experimental Conditions',5486,5605);
INSERT INTO "steps" VALUES(5257,4142,6,'react','Hold the chamber at the reaction temperature for the reaction duration.','and was maintained at this temperature for desired reaction duration','Experimental Conditions',5606,5674);
INSERT INTO "steps" VALUES(5258,4142,7,'cool','Cool the chamber back to room temperature.','Finally, the chamber was cooled down to room temperature at 10°C/min rate.','Experimental Conditions',5676,5750);
INSERT INTO "steps" VALUES(5259,4142,8,'collect','Collect the grey powder found in the carbon black section of the boat.','After the reaction, grey colored powder was found in the carbon black powder section of the alumina boat.','Experimental Conditions',5870,5975);
INSERT INTO "steps" VALUES(5260,4154,1,'dissolve','Dissolve zinc acetate dihydrate in DMF.','0.5268 g of Zinc acetate dihydrate (C4H6O4Zn·2H2O, AR, Sinopharm) was dissolved in 3 ml N, N-dimethylformamide (DMF, AR, Sinopharm).','Preparation of ZnSe@N-CNFs',5500,5632);
INSERT INTO "steps" VALUES(5261,4154,2,'dissolve','Dissolve PAN in DMF under magnetic stirring at 60 °C.','0.4534 g polyacrylonitrile (PAN, Mw 150000, Macklin) was dissolved in 3 ml DMF under magnetic stirring for 30 min at 60°C.','Preparation of ZnSe@N-CNFs',5633,5755);
INSERT INTO "steps" VALUES(5262,4154,3,'mix','Mix the two solutions and stir further.','The two solutions were mixed and stirred for another 12 h.','Preparation of ZnSe@N-CNFs',5756,5814);
INSERT INTO "steps" VALUES(5263,4154,4,'deposit','Electrospin the mixture from a syringe to obtain nanofibers.','Then the mixture was transferred into a syringe to electrospin with the distance 20 cm and voltage 13 kV, respectively.','Preparation of ZnSe@N-CNFs',5815,5934);
INSERT INTO "steps" VALUES(5264,4154,5,'calcine','Mix the nanofibers with selenium powder and calcine in a tube furnace under vacuum (selenization).','The obtained nanofibers were mixed with 1.3 g Selenium powder (99.9%, Aladdin) and calcined at 650°C for 2 h (a ramp rate of 10°C min−1) in a tube furnace under vacuum to produce the ZnSe@N-CNFs.','Preparation of ZnSe@N-CNFs',5935,6130);
INSERT INTO "steps" VALUES(5265,4156,1,'dissolve','Dissolve zinc acetate dihydrate in DMF (solution de précurseur, préparée comme pour ZnSe@N-CNFs).','0.5268 g of Zinc acetate dihydrate (C4H6O4Zn·2H2O, AR, Sinopharm) was dissolved in 3 ml N, N-dimethylformamide (DMF, AR, Sinopharm).','Preparation of ZnSe@N-CNFs',5500,5632);
INSERT INTO "steps" VALUES(5266,4156,2,'dissolve','Dissolve PAN in DMF under magnetic stirring at 60 °C (comme pour ZnSe@N-CNFs).','0.4534 g polyacrylonitrile (PAN, Mw 150000, Macklin) was dissolved in 3 ml DMF under magnetic stirring for 30 min at 60°C.','Preparation of ZnSe@N-CNFs',5633,5755);
INSERT INTO "steps" VALUES(5267,4156,3,'mix','Mix the two solutions and stir further (comme pour ZnSe@N-CNFs) to give the precursor solution.','The two solutions were mixed and stirred for another 12 h.','Preparation of ZnSe@N-CNFs',5756,5814);
INSERT INTO "steps" VALUES(5268,4156,4,'dry','Dry the precursor solution directly, without electrospinning.','The ZnSe@N-C was synthesized by precursor solution directly dried at 80°C overnight and calcined at the same way with Se powder.','Preparation of ZnSe@N-CNFs',6325,6453);
INSERT INTO "steps" VALUES(5269,4156,5,'calcine','Calcine with Se powder « at the same way » as ZnSe@N-CNFs : renvoi explicite à la calcination de la voie de base, dont les valeurs ne sont pas répétées ici.','The ZnSe@N-C was synthesized by precursor solution directly dried at 80°C overnight and calcined at the same way with Se powder.','Preparation of ZnSe@N-CNFs',6325,6453);
INSERT INTO "steps" VALUES(5270,4157,1,'mix','Make a slurry of the active material, acetylene black and CMC in deionized water and ethanol (3:2).','A slurry made of ZnSe@N-CNFs (80 wt.%), acetylene black (10 wt.%), and carboxymethyl cellulose sodium (10 wt.%) was dissolved in deionized water and ethanol (3:2)','Electrochemical Characterization',7358,7520);
INSERT INTO "steps" VALUES(5271,4157,2,'deposit','Spread the slurry onto Cu foil.','spread onto Cu foil and dried at 80°C for 12 h to prepare the anodes','Electrochemical Characterization',7522,7590);
INSERT INTO "steps" VALUES(5272,4157,3,'dry','Dry the coated foil.','spread onto Cu foil and dried at 80°C for 12 h to prepare the anodes','Electrochemical Characterization',7522,7590);
INSERT INTO "steps" VALUES(5273,4158,1,'assemble','Assemble the coin-type cell from the anode, lithium metal, electrolyte and separator in an argon-filled glove box.','The LIBs were assembled into 2,032 coin-type cells in an Argon-filled glove box with lithium metal as the reference electrode, LiPF6 (1M) in ethylene carbonate (EC) and dimethyl carbonate (DMC) at a 1:1 volume ratio as electrolyte and polypropylene film (Celgard 2400) as separator.','Electrochemical Characterization',7592,7874);
INSERT INTO "steps" VALUES(5274,4160,1,'dissolve','Mix TiOSO4 with water under magnetic stirring at 50 °C until the solution is colorless.','A concentration of 2.4 g TiOSO4 was mixed with 25 mL H2O under constant magnetic stirring until the mixed solution turned into colorless solution at 50°C','Experimental Section',5798,5951);
INSERT INTO "steps" VALUES(5275,4160,2,'add','Add the CTAB solution to the colorless TiOSO4 solution.','and then 25 mL CTAB (60 mM) was added into the colorless solution and hold statically for 12 h at 50°C','Experimental Section',5953,6055);
INSERT INTO "steps" VALUES(5276,4160,3,'age','Hold the mixture statically at 50 °C.','hold statically for 12 h at 50°C','Experimental Section',6023,6055);
INSERT INTO "steps" VALUES(5277,4160,4,'filter','Filter the product.','The product obtained was filtered, washed with distilled water for several times, and dried at 120°C overnight.','Experimental Section',6057,6168);
INSERT INTO "steps" VALUES(5278,4160,5,'wash','Wash the product with distilled water.','The product obtained was filtered, washed with distilled water for several times, and dried at 120°C overnight.','Experimental Section',6057,6168);
INSERT INTO "steps" VALUES(5279,4160,6,'dry','Dry the washed product.','The product obtained was filtered, washed with distilled water for several times, and dried at 120°C overnight.','Experimental Section',6057,6168);
INSERT INTO "steps" VALUES(5280,4161,1,'mix','Prepare HCl aqueous solutions of different concentrations by diluting concentrated HCl with distilled water.','Hydrochloric acid aqueous solutions with different concentrations were initially prepared from concentrated HCl with distilled H2O, including 0.1–8 M.','Experimental Section',6169,6319);
INSERT INTO "steps" VALUES(5281,4161,2,'mix','Disperse the nanoskeleton in the HCl solution with stirring.','0.5 g Hex-ncTiO2/CTAB nanoskeleton was dispersed in 30 mL of the HCl aqueous solutions with stirring for 0.5 h','Experimental Section',6334,6444);
INSERT INTO "steps" VALUES(5282,4161,3,'heat','Hydrothermal treatment in a Teflon-lined stainless steel autoclave.','The autoclave was heated and maintained at 150°C for 24 h','Experimental Section',6533,6590);
INSERT INTO "steps" VALUES(5283,4161,4,'cool','Cool the autoclave to room temperature.','then cooled to room temperature','Experimental Section',6595,6626);
INSERT INTO "steps" VALUES(5284,4161,5,'collect','Collect the precipitate.','The precipitate was collected, centrifuged, washed with distilled water for several times, and then dried in a vacuum oven overnight at 60°C.','Experimental Section',6628,6769);
INSERT INTO "steps" VALUES(5285,4161,6,'centrifuge','Centrifuge the precipitate.','The precipitate was collected, centrifuged, washed with distilled water for several times, and then dried in a vacuum oven overnight at 60°C.','Experimental Section',6628,6769);
INSERT INTO "steps" VALUES(5286,4161,7,'wash','Wash the precipitate with distilled water.','The precipitate was collected, centrifuged, washed with distilled water for several times, and then dried in a vacuum oven overnight at 60°C.','Experimental Section',6628,6769);
INSERT INTO "steps" VALUES(5287,4161,8,'dry','Dry in a vacuum oven.','dried in a vacuum oven overnight at 60°C','Experimental Section',6728,6768);
INSERT INTO "steps" VALUES(5288,4172,1,'dissolve','Dissolve aluminium nitrate nonahydrate in distilled water.','0.844 g of Al(NO3)3·9H2O (≥98%, Sigma-Aldrich) was dissolved in 15 mL of distilled water','Synthesis',5494,5582);
INSERT INTO "steps" VALUES(5289,4172,2,'dissolve','Dissolve trimesic acid and CTAB separately from the aluminium solution, in ethanol.','0.331 g of trimesic acid (H3BTC, ≥97%, Sigma-Aldrich) and 1.004 g of cetyltrimethylammonium bromide (CTAB, ≥98%, Sigma-Aldrich) were dissolved separately in 15 mL of EtOH (≥99%, Sigma-Aldrich)','Synthesis',5588,5780);
INSERT INTO "steps" VALUES(5290,4172,3,'mix','Pour the aqueous solution into the ethanolic solution and stir at room temperature; final CTAB/Al and H2O/EtOH ratios and pH of the synthesis solution.','Subsequently, the aqueous solution was poured into the ethanolic solution and stirred for 30 min at RT.','Synthesis',5782,5885);
INSERT INTO "steps" VALUES(5291,4172,4,'heat','Solvothermal treatment in a Teflon-lined stainless steel autoclave under static conditions.','The mixture was transferred to a Teflon®-lined stainless steel autoclave and heated at 120 °C for 12 h under static conditions.','Synthesis',6008,6135);
INSERT INTO "steps" VALUES(5292,4172,5,'cool','Cool the autoclave down.','After cooling down, the product was filtered off and washed with fresh EtOH.','Synthesis',6136,6212);
INSERT INTO "steps" VALUES(5293,4172,6,'filter','Filter off the product.','After cooling down, the product was filtered off and washed with fresh EtOH.','Synthesis',6136,6212);
INSERT INTO "steps" VALUES(5294,4172,7,'wash','Wash the product with fresh ethanol.','After cooling down, the product was filtered off and washed with fresh EtOH.','Synthesis',6136,6212);
INSERT INTO "steps" VALUES(5295,4172,8,'reflux','Activation: suspend 100 mg of MOF in 100 mL of ethanol and keep under reflux.','Finally, to activate the MOFs, 100 mg were suspended in 100 mL of EtOH and kept under reflux at 60 °C overnight','Synthesis',6213,6324);
INSERT INTO "steps" VALUES(5296,4172,9,'filter','Filter off the activated MOF.','filtered off and dried overnight at room temperature','Synthesis',6326,6378);
INSERT INTO "steps" VALUES(5297,4172,10,'dry','Dry the activated MOF overnight at room temperature.','filtered off and dried overnight at room temperature','Synthesis',6326,6378);
INSERT INTO "steps" VALUES(5298,4186,1,'dissolve','Dissolve PbBr2 and CsBr in DMF to make the precursor solution.','the precursor solution was made by dissolving PbBr2 (0.1 mmol) and CsBr (0.1 mmol) in DMF (2.5 mL)','Synthesis of CsPbX3 NCs',28178,28276);
INSERT INTO "steps" VALUES(5299,4186,2,'add','Stabilize the precursor solution by adding oleic acid and oleylamine.','stabilized by adding OA (0.25 mL) and OLAm (0.13 mL)','Synthesis of CsPbX3 NCs',28281,28333);
INSERT INTO "steps" VALUES(5300,4186,3,'add','Inject part of the precursor solution into toluene under vigorous stirring to precipitate the nanocrystals at room temperature.','1 mL precursor solution was added into toluene (10 mL) under vigorous stirring for 1 min at room temperature','Synthesis of CsPbX3 NCs',28335,28443);
INSERT INTO "steps" VALUES(5301,4187,1,'dissolve','Dissolve NdBr3, PbBr2 and CsBr in DMF to make the doped precursor solution.','the precursor solution of CsPbBr3:xNd3+ (x = 7.2%) NCs was prepared by dissolving NdBr3 (0.15 mmol), PbBr2 (0.1 mmol), and CsBr (0.1 mmol) in DMF (2.5 mL)','Synthesis of Nd3+‐Doped CsPbBr3 NCs',28889,29043);
INSERT INTO "steps" VALUES(5302,4187,2,'add','Stabilize the precursor solution by adding oleic acid and oleylamine.','stabilized by adding OA (0.25 mL) and OLAm (0.13 mL)','Synthesis of CsPbX3 NCs',28281,28333);
INSERT INTO "steps" VALUES(5303,4187,3,'add','Inject part of the precursor solution into toluene under vigorous stirring to precipitate the nanocrystals at room temperature.','1 mL precursor solution was added into toluene (10 mL) under vigorous stirring for 1 min at room temperature','Synthesis of CsPbX3 NCs',28335,28443);
INSERT INTO "steps" VALUES(5304,4187,4,'centrifuge','Centrifuge the crude toluene suspension.','The crude samples in toluene were separated by centrifugation at 10 000 rpm for 10 min.','Purification',29118,29205);
INSERT INTO "steps" VALUES(5305,4187,5,'collect','Keep the strongly luminescent supernatant and discard the precipitate.','The supernatant with strong luminescence was preserved and the precipitate was discarded','Purification',29206,29294);
INSERT INTO "steps" VALUES(5306,4187,6,'precipitate','Add methyl acetate to precipitate the doped nanocrystals and remove unreacted components and byproducts.','to remove the unreacted component and byproducts, methyl acetate was adopted to assist precipitation of the doped NCs','Purification',29332,29449);
INSERT INTO "steps" VALUES(5307,4187,7,'dissolve','Redissolve the precipitate in toluene.','the precipitate was then dissolved in toluene','Purification',29454,29499);
INSERT INTO "steps" VALUES(5308,4188,1,'dissolve','Dissolve NdBr3 (amount not stated), PbBr2 and CsBr in DMF to make the doped precursor solution.','The solution of Nd3+‐doped CsPbBr3 NCs was prepared by mixing a specific molar quantity of NdBr3 in the precursor solution without changing the other operation procedures.','Synthesis of Nd3+‐Doped CsPbBr3 NCs',28703,28874);
INSERT INTO "steps" VALUES(5309,4188,2,'add','Stabilize the precursor solution by adding oleic acid and oleylamine.','stabilized by adding OA (0.25 mL) and OLAm (0.13 mL)','Synthesis of CsPbX3 NCs',28281,28333);
INSERT INTO "steps" VALUES(5310,4188,3,'add','Inject part of the precursor solution into toluene under vigorous stirring to precipitate the nanocrystals at room temperature.','1 mL precursor solution was added into toluene (10 mL) under vigorous stirring for 1 min at room temperature','Synthesis of CsPbX3 NCs',28335,28443);
