INSERT INTO "steps" VALUES(5329,4191,1,'dissolve','Dissolve NdBr3 (amount not stated), PbBr2 and CsBr in DMF to make the doped precursor solution.','The solution of Nd3+‐doped CsPbBr3 NCs was prepared by mixing a specific molar quantity of NdBr3 in the precursor solution without changing the other operation procedures.','Synthesis of Nd3+‐Doped CsPbBr3 NCs',28703,28874);
