INSERT INTO "synthesis_routes" VALUES(4042,123,369,NULL,'Ni3',1,'sonochemical synthesis in water with a direct immersion ultrasonic probe (70% amplitude, 1 h), thioacetamide as sulfur precursor',NULL,45.5,'%','Ni3 | C2H5NS | 1:1 | - | 60 | 70 | NiS | 17 | 45.5',1,'["sonication_temperature", "sonication_pulse_mode", "centrifugation_duration", "drying_temperature", "water_purity", "stirring_speed"]',0.75,'In a typical synthesis of nickel sulfides, we dissolved 2.49 g (= 0.01 mol) of Ni(CH3COO)2 ∙ 4H2O and 0.75 g (= 0.01 mol) of C2H5NS in 50 mL of water in a 100 mL flat-bottomed beaker.','Experimental',6945,7128,'material');
