INSERT INTO "synthesis_routes" VALUES(4047,123,62,4042,'Ni3-2',0,'sonochemical synthesis in water with a direct immersion ultrasonic probe (70% amplitude, 1 h), thioacetamide as sulfur precursor',NULL,46.4,'%','Ni3-2 | C2H5NS | 1:1 | - | 120 | 70 | NiS | 19 | 46.4',1,'[]',0.75,'the diffraction pattern as well as the reaction yield of NiS obtained by using a longer reaction time of 120 min (Ni3-2, pattern not shown) was not significantly different when compared to the product obtained after 60 min','Nickel sulfides',13583,13805,'material');
