INSERT INTO "synthesis_routes" VALUES(4084,52,91,NULL,'FAPbBr3_purified',1,'antisolvent purification of as-synthesized FAPbBr3 NC stock solution with methyl acetate',NULL,NULL,NULL,NULL,1,'["which_as-synthesized_sample_(x)_is_purified", "yield", "temperature_of_centrifugation"]',0.875,'To purify the FAPbBr3 NCs, 10 mL of MeOAc was added to 5 mL of a stock solution; then it was centrifuged at 7500 rpm for 5 min.','Purification and Ligand Treatment of FAPbBr3 NCs',26014,26141,'post_treatment');
