INSERT INTO "synthesis_routes" VALUES(4154,65,132,NULL,'ZnSe@N-CNFs',1,'electrospinning of a Zn acetate/PAN solution in DMF, then selenization (calcination with Se powder) under vacuum',NULL,NULL,NULL,NULL,1,'["stirring_speed", "electrospinning_flow_rate", "needle_or_collector_type", "electrospinning_temperature_and_humidity", "electrospinning_duration", "vacuum_pressure", "selenium_placement_in_furnace", "cooling_rate", "yield", "purity_of_PAN"]',1.0,'The obtained nanofibers were mixed with 1.3 g Selenium powder (99.9%, Aladdin) and calcined at 650°C for 2 h (a ramp rate of 10°C min−1) in a tube furnace under vacuum to produce the ZnSe@N-CNFs.','Preparation of ZnSe@N-CNFs',5935,6130,'material');
