INSERT INTO "synthesis_routes" VALUES(4157,65,381,NULL,'Electrode_ZnSe@N-CNFs',0,'slurry of active material, acetylene black and CMC in water/ethanol spread onto Cu foil and dried',NULL,NULL,NULL,NULL,1,'[]',0.625,'A slurry made of ZnSe@N-CNFs (80 wt.%), acetylene black (10 wt.%), and carboxymethyl cellulose sodium (10 wt.%) was dissolved in deionized water and ethanol (3:2), spread onto Cu foil and dried at 80°C for 12 h to prepare the anodes.','Electrochemical Characterization',7358,7591,'device');
INSERT INTO "synthesis_routes" VALUES(4158,65,382,NULL,'LIB_cell_ZnSe@N-CNFs',0,'assembly of a coin-type test cell in an argon-filled glove box',NULL,NULL,NULL,NULL,1,'[]',0.125,'The LIBs were assembled into 2,032 coin-type cells in an Argon-filled glove box with lithium metal as the reference electrode, LiPF6 (1M) in ethylene carbonate (EC) and dimethyl carbonate (DMC) at a 1:1 volume ratio as electrolyte and polypropylene film (Celgard 2400) as separator.','Electrochemical Characterization',7592,7874,'device');
