INSERT INTO "synthesis_routes" VALUES(4262,82,198,4260,'ZeoX-T100',0,'one-step hydrothermal synthesis (gel formation, aging, crystallization) from diatomite and aluminum hydroxide in NaOH solution',NULL,NULL,NULL,NULL,0,'[]',0.75,'When the temperature was raised to 100 °C, typical diffraction peaks of X zeolite (JCPDS 38-0237) can be seen at 2θ = 6.10°, 9.97°, 11.76°, 15.39°, 18.46°, 20.12°, 23.24°, 26.58° and 30.86° suggesting that zeolite X started to crystallize (Figure 2a).','3.2. Effect of Crystallization',9846,10097,'material');
INSERT INTO "synthesis_routes" VALUES(4263,82,199,4260,'ZeoX-T120',0,'one-step hydrothermal synthesis (gel formation, aging, crystallization) from diatomite and aluminum hydroxide in NaOH solution',NULL,NULL,NULL,NULL,0,'[]',0.75,'When the reaction temperature was further raised to 120 °C, almost pure phase of zeolite X was observed along with some zeolite A (JCPDS 43-0142).','3.2. Effect of Crystallization',10381,10527,'material');
INSERT INTO "synthesis_routes" VALUES(4264,82,422,4260,'ZeoX-T130',0,'one-step hydrothermal synthesis (gel formation, aging, crystallization) from diatomite and aluminum hydroxide in NaOH solution',NULL,NULL,NULL,NULL,NULL,'[]',0.75,'Figure 5 Effect of (a) crystallization temperature and (b) crystallization time on CEC.','Figure captions',24051,24138,'material');
INSERT INTO "synthesis_routes" VALUES(4265,82,201,4260,'ZeoX-t3h',0,'one-step hydrothermal synthesis (gel formation, aging, crystallization) from diatomite and aluminum hydroxide in NaOH solution',NULL,NULL,NULL,NULL,0,'[]',0.75,'As shown in Figure 2b, no zeolite X was obtained at crystallization time of 3 h at 110 °C.','3.2. Effect of Crystallization',10655,10745,'material');
INSERT INTO "synthesis_routes" VALUES(4266,82,202,4260,'ZeoX-t4h',0,'one-step hydrothermal synthesis (gel formation, aging, crystallization) from diatomite and aluminum hydroxide in NaOH solution',NULL,NULL,NULL,NULL,NULL,'[]',0.75,'When the crystallization time was 4 h, the synthesized products formed crystals with no distinct faces, and the particles were not uniform.','3.2. Effect of Crystallization',11968,12107,'material');
INSERT INTO "synthesis_routes" VALUES(4267,82,203,4260,'ZeoX-t6h',0,'one-step hydrothermal synthesis (gel formation, aging, crystallization) from diatomite and aluminum hydroxide in NaOH solution',NULL,NULL,NULL,NULL,NULL,'[]',0.75,'When the crystallization time was up to 6 h, the synthesized products do not show smooth faces.','3.2. Effect of Crystallization',12219,12314,'material');
INSERT INTO "synthesis_routes" VALUES(4268,82,204,4260,'ZeoX-age0',0,'one-step hydrothermal synthesis (gel formation, aging, crystallization) from diatomite and aluminum hydroxide in NaOH solution',NULL,NULL,NULL,NULL,0,'[]',0.75,'However, the synthetic product without aging exhibited extremely weak diffraction peaks of zeolite X (Figure 6b).','3.3. Effect of Aging',14156,14269,'material');
INSERT INTO "synthesis_routes" VALUES(4269,82,205,4260,'ZeoX-age60',0,'one-step hydrothermal synthesis (gel formation, aging, crystallization) from diatomite and aluminum hydroxide in NaOH solution',NULL,NULL,NULL,NULL,0,'[]',0.75,'However, when the aging time was up to 60 and 120 min, some obvious diffraction peaks of zeolite A appeared indicating that the aging time plays a significant role in the formation of zeolite prepared from diatomite.','3.3. Effect of Aging',14545,14761,'material');
INSERT INTO "synthesis_routes" VALUES(4270,82,206,4260,'ZeoX-age120',0,'one-step hydrothermal synthesis (gel formation, aging, crystallization) from diatomite and aluminum hydroxide in NaOH solution',NULL,NULL,NULL,NULL,0,'[]',0.75,'However, when the aging time was up to 60 and 120 min, some obvious diffraction peaks of zeolite A appeared indicating that the aging time plays a significant role in the formation of zeolite prepared from diatomite.','3.3. Effect of Aging',14545,14761,'material');
