INSERT INTO "synthesis_routes" VALUES(4272,82,208,4260,'ZeoX-H2O50',0,'one-step hydrothermal synthesis (gel formation, aging, crystallization) from diatomite and aluminum hydroxide in NaOH solution',NULL,NULL,NULL,NULL,0,'[]',0.75,'When the H2O/Na2O ratio was up to 50, there was only one sharp diffraction peak attributable to aluminum hydroxide.','3.4. Effect of Alkalinity',16499,16614,'material');
