INSERT INTO "synthesis_routes" VALUES(4311,18,222,4301,'ZIF-8-Out_50C',0,NULL,NULL,NULL,NULL,NULL,NULL,'[]',0.75,'It was observed that the average diameter of the prepared hollow spheres was lower (i.e., average diameterZIF-8-Out, 50°C = ∼0.65 ± 0.10 μm) than ZIF-8-Out (i.e., average diameterZIF-8-Out, 30°C = ∼0.75 ± 0.14 μm).','Synthesis Temperature',48407,48621,'material');
