INSERT INTO "synthesis_routes" VALUES(4370,56,254,NULL,'QD_EtOAc',1,'room temperature, open atmosphere anti-solvent precipitation in ethyl acetate with oleylamine and oleic acid as capping ligands',NULL,NULL,NULL,NULL,1,'["stirring_speed", "reaction_temperature_value", "wash_volume", "number_of_washes", "yield"]',0.875,'When ethyl acetate is used as the anti-solvent, 2.6 ± 0.9 nm sized quasi-cubic CsPbBr3 QDs are formed immediately on addition of the precursor solution.','Quantum Dots',4630,4782,'material');
INSERT INTO "synthesis_routes" VALUES(4371,56,255,4370,'NPL_EtOAc_10min',0,'room temperature, open atmosphere anti-solvent precipitation in ethyl acetate with oleylamine and oleic acid as capping ligands',NULL,NULL,NULL,NULL,1,'[]',0.875,'Allowing the reaction up to 10 minutes, a few unit cell thick, square shaped CsPbBr3 NPLs of 60 nm edge length are obtained.','Nanoplates',5478,5602,'material');
INSERT INTO "synthesis_routes" VALUES(4372,56,256,4370,'Nanobar_EtOAc_40h',0,'room temperature, open atmosphere anti-solvent precipitation in ethyl acetate with oleylamine and oleic acid as capping ligands',NULL,NULL,NULL,NULL,1,'[]',0.875,'After 40 hours, the reaction medium contains mostly the nanobars with an average aspect ratio of 2.55 (~140 nm long and ~55 nm wide).','Nanobars',6615,6748,'material');
INSERT INTO "synthesis_routes" VALUES(4373,56,257,4370,'NC12_toluene',0,'room temperature, open atmosphere anti-solvent precipitation in ethyl acetate with oleylamine and oleic acid as capping ligands',NULL,NULL,NULL,NULL,1,'[]',0.875,'By changing the anti-solvent to toluene and keeping OLA (20–70 μl) and OA (200 μl) as capping ligand, we can further manipulate the morphology of CsPbBr3 NCs.','Nanocubes of Different Sizes',8123,8281,'material');
INSERT INTO "synthesis_routes" VALUES(4374,56,258,4373,'NC34_toluene_1h',0,NULL,NULL,NULL,NULL,NULL,1,'[]',0.875,'When 70 μl OLA is used, larger nanocubes of ~34 nm edge-length are formed as evident from the TEM (Fig. 2d, S6, SI) and FESEM (Fig. 2e) images.','Nanocubes of Different Sizes',9086,9229,'material');
INSERT INTO "synthesis_routes" VALUES(4375,56,259,4374,'NC_toluene_50h',0,NULL,NULL,NULL,NULL,NULL,NULL,'[]',0.875,'Further increase in reaction time up to 50 hours or more ends up with larger nanocubes and few nanorods of larger dimension (Figure S7, SI).','Nanocubes of Different Sizes',9568,9708,'material');
INSERT INTO "synthesis_routes" VALUES(4376,56,260,4373,'NR_toluene_1h',0,NULL,NULL,NULL,NULL,NULL,1,'[]',0.875,'Less quantity of OLA (20 μl) provides a faster kinetics and forms CsPbBr3 nanorods of good crystalline quality (after 1 hour) at the expense of nanocubes formed initially.','Nanorods and Nanowires',9735,9906,'material');
INSERT INTO "synthesis_routes" VALUES(4377,56,261,4376,'NW_toluene_40h',0,NULL,NULL,NULL,NULL,NULL,1,'[]',0.875,'after 40 hours of reaction, nanowires of diameter ~70 nm and length ≥15 μm are obtained.','Nanorods and Nanowires',10665,10753,'material');
INSERT INTO "synthesis_routes" VALUES(4378,56,262,4370,'CHCl3_early',0,'room temperature, open atmosphere anti-solvent precipitation in ethyl acetate with oleylamine and oleic acid as capping ligands',NULL,NULL,NULL,NULL,1,'[]',0.875,'In chloroform, smaller NCs emitting at 487 nm and nanocubes emitting at 510 nm (~12 nm) are formed at the early stages of the reaction.','Effect of Other Solvents',12001,12136,'material');
