INSERT INTO "synthesis_routes" VALUES(4897,472,556,4895,'ZLCH-Fe_AR88_100',0,'contact de ZLCH-Fe avec une solution de nitrate et de colorant azoïque AR88 à pH 2 (gélification), puis séchage',NULL,NULL,NULL,NULL,NULL,'[]',0.75,'Thus, we increased the initial AR88 concentration up to 100 mg/L under the same conditions reported above.','3.9. Dye Effect Studies',16184,16290,'post_treatment');
