INSERT INTO "synthesis_routes" VALUES(5511,152,732,5510,'Co0.25-Fe0.75-MOF',0,'solvothermal (DMF, 130 °C, 12 h)',NULL,NULL,NULL,NULL,1,'[]',0.75,'A mixture of cobalt nitrate and iron(III) nitrate with different molar ratios (0.25:0.75, 0.50:0.50, and 0.75:0.25) was mixed with terephthalic acid and dissolved in DMF (40 mL) under continuous stirring for 1 h.','Synthesis of (Cox–Fe1–x–MOF)',6534,6746,'material');
