INSERT INTO "synthesis_routes" VALUES(5513,152,734,5510,'Fe-MOF',0,'solvothermal (DMF, 130 °C, 12 h)',NULL,NULL,NULL,NULL,1,'[]',0.75,'Also, monometallic Fe–MOF was synthesized by the same procedure without adding the cobalt precursor.','Synthesis of (Cox–Fe1–x–MOF)',7207,7307,'material');
INSERT INTO "synthesis_routes" VALUES(5553,180,738,NULL,'PAN_OMMT_fibers',0,'electrospinning of a PAN / O-MMT solution in DMF',NULL,NULL,NULL,NULL,1,'["quantité de DMF et de solution par aiguille", "durée d''électrofilage"]',0.875,'The PAN/O-MMT nanofibers were electrospun in an apparatus employing a high voltage (15 kV) power supply.','2.2. Preparation of Lac-Immobilized PAN/O-MMT/TiO2 Nanofibers',7880,7984,'intermediate');
INSERT INTO "synthesis_routes" VALUES(5554,180,739,NULL,'PAN_OMMT_TiO2',0,'sol-gel coating by immersion of the PAN/O-MMT membrane in an aged TiO2 sol',NULL,NULL,NULL,NULL,1,'["quantités de Ti(OC4H9)4, de HCl et d''eau", "teneur ou épaisseur du dépôt de TiO2", "phase du TiO2"]',0.75,'The PAN/O-MMT/TiO2 nanofibers was prepared as follows: first, Ti(OC4H9)4 was added into 6 mol/L HCl dropwise and stirred for 30 min to prepare the TiO2 sol.','2.2. Preparation of Lac-Immobilized PAN/O-MMT/TiO2 Nanofibers',8155,8311,'intermediate');
INSERT INTO "synthesis_routes" VALUES(5555,180,740,NULL,'Lac_PAN_OMMT_TiO2',1,'electrostatic adsorption of laccase on the TiO2-coated membrane in sodium acetate solution',NULL,NULL,NULL,NULL,1,'["origine et activité spécifique de la laccase", "composition et concentration du tampon", "protocole de marquage FITC"]',0.75,'A 400 mg of PAN/O-MMT/TiO2 nanofibrous membrane was immersed into a 250 mL flask containing 100 mL of 0.3 g/L Lac in sodium acetate solution (pH = 4) and adsorbed by electro-static force between ionized enzyme and cationic TiO2 precursors.','2.2. Preparation of Lac-Immobilized PAN/O-MMT/TiO2 Nanofibers',8777,9016,'material');
